import java.io.File;
import java.util.Scanner;

/**
 * B구획의 빌딩 최고 높이 구하기
 */ 
public class BuildingTest {

	public static void main(String[] args) throws Exception{
		// 코드를 작성해주세요.
		Scanner sc = new Scanner(new File("input.txt"));
		int []dx = {-1,-1,-1,0,0,1,1,1};
		int []dy = {1,0,-1,1,-1,1,0,-1};
		int T = sc.nextInt();
		while(T-- >0)
		{
			int N = sc.nextInt();
			char[][] board = new char[N][N];

			for(int i=0;i<N;i++)
			{
				for(int j=0;j<N;j++)
				{
					board[i][j] = sc.next().charAt(0);
				}
			}

//			for(int i=0;i<N;i++)
//			{
//				for(int j=0;j<N;j++)
//				{
//					System.out.print(board[i][j] + " ");
//				}
//				System.out.println();
//			}

			int ans = 0;

			for(int i=0;i<N;i++)
			{
				for(int j=0;j<N;j++)
				{
					if(board[i][j]=='G') continue;
					int temp = 0;
					int flag = 0;
					for(int dir = 0;dir<8;dir++)
					{
						int nx = i + dx[dir];
						int ny = j + dy[dir];

						if(nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
						if(board[nx][ny] == 'G')
						{
							flag = 1;
							break;
						}
					}

					if(flag == 1)
					{
						temp = 2;
					}

					else
					{
						for(int k=0;k<N;k++)
						{
							if(board[i][k]=='B') temp++;
							if(board[k][j]=='B') temp++;
						}
						temp--;
					}

					ans = Math.max(temp,ans);

				}
			}

			System.out.println(ans);
		}

		//
	}
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * B구획의 빌딩 최고 높이 구하기
 */ 
public class BuildingTest {
	//8방향 탐색 위 오 아 왼 왼위 오위 오아래 왼아래 순
	static int[] dx = {0, 1, 0, -1, -1, 1, 1, -1};
	static int[] dy = {-1, 0, 1, 0, -1, -1, 1, 1};
	static char n[][] = new char[22][22];
	static int a;
	static boolean findPark(int y, int x) {
		for(int i = 0; i < 8; i++) {
			int ny = y + dy[i];
			int nx = x + dx[i];
			if(ny < 0 || nx < 0 || ny >= a || nx >= a || n[ny][nx] == '0') continue;
			if(n[ny][nx] == 'G') return true;
		}
		return false;
	}
	static int building(int y, int x) {
		int cnt = 1;
		for(int i = 0; i < 4; i++) {
			int ny = y + dy[i];
			int nx = x + dx[i];
			while(true) {
				if(ny < 0 || nx < 0 || ny >= a || nx >= a || n[ny][nx] == '0') break;
				if(n[ny][nx] == 'B') cnt++;
				ny += dy[i];
				nx += dx[i];
			}
		}
		return cnt;
	}
	public static void main(String[] args) throws Exception{
		int t, ret;
		Scanner sc = new Scanner(System.in);
		t = sc.nextInt();
		for(int test = 1; test <= t; test++) {
			a = sc.nextInt();
			//맵만들기, 결과는 어차피 2가 최소이니 2로 초기화
			ret = 2;
			for(char[] i : n) {
				Arrays.fill(i, '0');
			}
			for(int i = 0; i < a; i++) {
				for(int j = 0; j < a; j++) {
					char c = sc.next().charAt(0);
					n[i][j] = c;
				}
			}
			// 8방향에 G 있는지 확인부터 하고 있으면 다음칸 없으면 결과갱신?
			for(int i = 0; i < a; i++) {
				for(int j = 0; j < a; j++) {
					if(n[i][j] == 'G' || findPark(i, j)) continue;
					else {
						ret = Math.max(ret, building(i, j));
					}
				}
			}
			System.out.println("#" + test + " " + ret);
		}
	}
}

import java.util.*;
/**
 * B구획의 빌딩 최고 높이 구하기
 */ 
public class BuildingTest {
	private static final int[] dx = new int[] {1,-1, 0, 1, -1, 0, 1, -1};
	private static final int[] dy = new int[] {0, 0, 1, 1, 1, -1, -1,-1};


	public static void main(String[] args) throws Exception{
		Scanner sc = new Scanner(System.in);
		int T = sc.nextInt();

		for(int i = 1; i <= T; i ++) {
			int n = sc.nextInt();
			char[][] buildings = new char[n][n];

			for(int j = 0; j < n; j ++) {
				for(int k = 0; k < n; k ++) {
					buildings[j][k] = sc.next().charAt(0);
				}
			}
			System.out.printf("#%d %d\n", i, getHighestBuildHeight(n, buildings));
		}
	}

	private static int getHighestBuildHeight(int n, char[][] buildings) {

		int[] rowHeight = new int[n];
		int[] colHeight = new int[n];

		for(int i = 0; i < n; i ++) {		
			for(char building : buildings[i]) {
				if(building == 'B') rowHeight[i] ++;
			}
		}

		if(Arrays.stream(rowHeight).sum() == 0)
			return 0;

		for(int i = 0; i < n; i ++) {
			for(int j = 0; j < n; j++)	{
				if(buildings[j][i] == 'B') colHeight[i] ++;
			}
		}

		int highestBuildHeight = 2;

		for(int i = 0; i < n; i ++) {
			for(int j = 0; j < n; j ++) {
				if(buildings[i][j] == 'G') continue;
				boolean flag = false;

				for(int k = 0; k < 8; k ++) {
					int nx = i + dx[k];
					int ny = j + dy[k];
					if(nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
					if(buildings[nx][ny] == 'G') {
						flag = true;
						break;
					}
				}

				if(flag) continue;

				highestBuildHeight = Math.max(highestBuildHeight, rowHeight[i] + colHeight[j] - 1);	

			}
		}

		return highestBuildHeight;
	}
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * B구획의 빌딩 최고 높이 구하기
 */ 
public class BuildingTest {
	static Scanner sc = new Scanner(System.in);

	static int sch(int x, int y, int n, char[][] arr) {

		int dx[] = {-1, 1, 0, 0, -1, 1 ,-1, 1};
		int dy[] = {0, 0, -1, 1, -1, 1, 1, -1};

		//탐색 - G있으면 바로 2로 return
		for(int d=0; d<8; d++) {
			int nx = x+dx[d], ny = y+dy[d];
			if(nx<0||nx>=n||ny<0||ny>=n) continue;
			if(arr[nx][ny]=='G') return 2;
		}

		//아니면 B 개수 카운트
		int bCnt=1;
		for(int d=0; d<4; d++) {
			int nx = x+dx[d], ny = y+dy[d];
			//정상 범위 내에서만
			while(nx>=0&&nx<n&&ny>=0&&ny<n) {
				if(arr[nx][ny]=='B') bCnt++; 
				nx+=dx[d]; ny+=dy[d];
			}
		}

		return bCnt;
	}

	public static void main(String[] args) throws Exception{


		int t = sc.nextInt();


		for(int test_case=1; test_case<=t; test_case++) {
			//--입력
			int n = sc.nextInt();
			Queue<int[]> q = new ArrayDeque<>();

			char[][] arr = new char[n][n];
			for(int i=0; i<n; i++) {
				for(int j=0; j<n; j++) {
					arr[i][j] = sc.next().charAt(0);
					if(arr[i][j]=='B') q.offer(new int[] {i, j});
				}
			}

			//--출력
			int mV = 0;
			while(!q.isEmpty()) {
				//모든 B에 대해 인접구역 탐색
				int x = q.peek()[0]; int y = q.peek()[1]; q.poll();

				mV = Math.max(sch(x, y, n, arr), mV);
			}

			System.out.println("#"+test_case+" "+mV);

		}

	}
}

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * B구획의 빌딩 최고 높이 구하기
 */
public class BuildingTest {

	public static void main(String[] args) throws Exception {

		System.setIn(new FileInputStream("input.txt"));
		// 입력받기
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int test_case = Integer.parseInt(br.readLine());

		for (int tc = 0; tc < test_case; tc++) {

			int N = Integer.parseInt(br.readLine());
			// dx,dy
			int[] dr = { 0, 0, -1, 1, -1, -1, 1, 1 };
			int[] dc = { -1, 1, 0, 0, -1, 1, -1, 1 };

			StringBuilder sb = new StringBuilder();
			String[][] map = new String[N][N];
			int[][] chkMap = new int[N][N];
			int[] rowB = new int[N];
			int[] colB = new int[N];

			// map에 B,G 받기
			for (int i = 0; i < N; i++) {
				StringTokenizer st = new StringTokenizer(br.readLine());
				for (int j = 0; j < N; j++) {
					String chr = st.nextToken();
					map[i][j] = chr;

					if (chr.equals("B")) {
						colB[j]++;
						rowB[i]++;
					}
				}
			}

			// for 문 돌면서 2차원 회전
			// map에 B,G 받기
			int result = 0;

			for (int i = 0; i < N; i++) {
				for (int j = 0; j < N; j++) {
					int cr = i;
					int cc = j;
					boolean chk = false; // false면 빌딩건물
					// 8방향 탐색
					for (int k = 0; k < 8; k++) {
						int nr = cr + dr[k];
						int nc = cc + dc[k];

						// 범위체크
						if (nr >= 0 && nr < N && nc >= 0 && nc < N && map[nr][nc].equals("G")) {
							chk = true;
							break;
						}
					}

					// 탐색종료, 건물을 세울 수 있다면
					if (chk == false) {
						chkMap[cr][cc] = rowB[i] + colB[j] - 1;
					} else {
						chkMap[cr][cc] = 2;
					}

					result = Math.max(chkMap[cr][cc], result);
				}
			}

			sb.append("#").append(tc + 1).append(" ").append(result);
			System.out.println(sb);
		} // end tc

	}
}

import java.io.*;
import java.util.*;

public class BuildingTest {
	static int[] dx = new int[] {-1, 1, 0, 0, -1, -1, 1, 1};
	static int[] dy = new int[] {0, 0, -1, 1, -1, 1, -1, 1};
	static char[][] board;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine());

		for(int t = 1; t <= T; t++) {
			int N = Integer.parseInt(br.readLine());
			board = new char[N][N];
			int result = 0; // board가 모두 G인 경우 0

			for(int i = 0; i < N; i++) {
				StringTokenizer st = new StringTokenizer(br.readLine());
				for(int j = 0; j < N; j++) {
					board[i][j] = st.nextToken().charAt(0); // char로 저장
				}
			}

			for(int i = 0; i < N; i++) {
				for(int j = 0; j < N; j++) {
					// 현재 위치가 B면 높이 조사해서 기존 최대값과 비교
					if(board[i][j] == 'B') {
						result = Math.max(result, getHeight(i, j));
					}
				}
			}

			sb.append("#" + t + " " + result + "\n");
		}

		System.out.print(sb);
	}

	private static int getHeight(int x, int y) {
		int bCnt = 1; // 현재 위치 B 개수 1개
		boolean isGExist = false;

		// 주변 8방향에 G가 존재하는지 검사
		for(int i = 0; i < 8; i++) {
			int nx = x + dx[i];
			int ny = y + dy[i];

			if(0 > nx || nx >= board.length || 0 > ny || ny >= board.length) {
				continue;
			}

			if(board[nx][ny] == 'G') {
				isGExist = true;
			}
		}

		// G가 존재하면 높이는 반드시 2
		if(isGExist) {
			return 2;
		}

		// G가 존재하지 않으면 상하좌우 직선의 B 개수 조사
		for(int i = 0; i < 4; i++) {

			for(int j = 1; j < board.length; j++) {
				int nx = x + dx[i] * j;
				int ny = y + dy[i] * j;

				if(0 > nx || nx >= board.length || 0 > ny || ny >= board.length) {
					break;
				}

				if(board[nx][ny] == 'B') {
					bCnt++;
				}
			}
		}

		return bCnt;
	}
}

