/**
 * B구획의 빌딩 최고 높이 구하기
 */ 
public class BuildingTest {
	static int[] dx = {-1, 0, 1, 0, -1, 1, 1, -1 };
	static int[] dy = {0, 1, 0, -1, 1, 1, -1, -1 };

	public static boolean hasG(char[][] building, int x, int y) {
		int n= building.length;

		for(int i = 0; i<8; i++) {
			int nx = x+dx[i];
			int ny = y+dy[i];

			if(nx<0||ny<0||nx>=n||ny>=n) {
				continue;
			}

			if(building[nx][ny]==('G')) {
				return true;
			}
		}
		return false;
	}

	public static void main(String[] args) throws Exception{
		// 코드를 작성해주세요.
		//Scanner sc = new Scanner(new File("input.txt"));
		Scanner sc = new Scanner(System.in);
		int T = sc.nextInt();

		for(int k=1; k<=T; k++) {
			int N = sc.nextInt();
			char[][] building = new char[N][N];

			for(int i=0; i<N; i++) {
				for(int j=0; j<N; j++) {
					building[i][j]= sc.next().charAt(0);
				}
			}

			int[] rowB = new int[N];
			int[] colB = new int[N];

			for(int i=0; i<N; i++) {
				for(int j=0; j<N; j++) {
					if(building[i][j]=='B') {
						rowB[i]++;
						colB[j]++;
					}
				}
			}

			int maxHeight=0;

			for(int i=0; i<N; i++) {
				for(int j=0; j<N; j++) {
					if(building[i][j]!='B') {
						continue;
					}

					int height;
					if(hasG(building, i, j)) {
						height=2;
					}
					else {
						height = rowB[i]+colB[j]-1;
					}

					maxHeight=Math.max(maxHeight, height);
				}
			}	
			System.out.println("#"+k+" "+maxHeight);
		}
	}
}

import java.util.Scanner;

/**
 * B구획의 빌딩 최고 높이 구하기
 */ 
public class BuildingTest {

	public static void main(String[] args) throws Exception{
		Scanner sc= new Scanner(System.in);
		int T=sc.nextInt();
		for (int test_case=1;test_case<T+1;test_case++) {
			int N=sc.nextInt();
			sc.nextLine();

			int[][] area=new int[N][N];
			for(int i=0;i<N;i++) {
				String[] Tokens=(sc.nextLine()).split(" ");
				for(int j=0;j<N;j++) {
					if(Tokens[j].equals("G")) {
						area[i][j]=0;
					}else {
						area[i][j]=1;
					}		
				}
			}

			int[] r= {1,1,1,-1,-1,-1,0,0};
			int[] c= {0,1,-1,0,1,-1,1,-1};

			int numMax=2;
			for (int i=0;i<N;i++) {
				for (int j=0;j<N;j++) {
					boolean K= true;

					for (int k=0;k<8;k++) {
						int nr=i+r[k];
						int nc=j+c[k];
						if((nr>=0 && nr<N) && (nc>=0 && nc<N)) {
							if(area[nr][nc]==0) {
								K=false;
								break;
							}
						}
					}


					if(K) {
						int count=0;
						for(int k=0;k<N;k++) {
							if(area[i][k]==1) {
								count++;
							}
							if(area[k][j]==1) {
								count++;
							}
						}
						numMax=Math.max(numMax, count-1);
					}



				}
			}


			System.out.println("#"+test_case+" "+numMax);




		}


	}
}

import java.io.*;
import java.util.*;

/**
 * B구획의 빌딩 최고 높이 구하기
 */
public class BuildingTest {

	static int[] dx = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] dy = { -1, 0, 1, -1, 1, -1, 0, 1 };

	public static void main(String[] args) throws Exception {
		// 코드를 작성해주세요.
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int testcase = Integer.parseInt(br.readLine());
		for (int t = 1; t <= testcase; t++) {

			int n = Integer.parseInt(br.readLine());
			char[][] map = new char[n][n];
			for (int i = 0; i < n; i++) {
				StringTokenizer st = new StringTokenizer(br.readLine());
				for (int j = 0; j < n; j++) {
					map[i][j] = st.nextToken().charAt(0);
				}
			}

			int maxHeight = 0;
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					if (map[i][j] == 'G')
						continue;
					boolean nearByPark = false;
					for (int d = 0; d < 8; d++) {
						int x = i + dx[d];
						int y = j + dy[d];
						if (x >= 0 && x < n && y >= 0 && y < n) {
							if (map[x][y] == 'G') {
								nearByPark = true;
								break;
							}
						}
					}
					if (nearByPark) {
						maxHeight = Math.max(maxHeight, 2);
					} else {
						int temp = 0;
						for (int r = 0; r < n; r++) {
							if (map[r][j] == 'B') {
								temp++;
							}
						}
						for (int c = 0; c < n; c++) {
							if (map[i][c] == 'B') {
								temp++;
							}
						}
						temp -= 1;
						maxHeight = Math.max(maxHeight, temp);
					}
				}
			}

			System.out.println(String.format("#%d %d", t, maxHeight));
		}
	}
}

import java.util.*;
import java.io.*;
/**
 * B구획의 빌딩 최고 높이 구하기
 */ 
public class BuildingTest {
	static char[][] arr;
	static int max = 0;
	static int[] dx = {1,1,1,-1,-1,-1,0,0};
	static int[] dy = {0,1,-1,-1,0,1,1,-1};
	static int N;

	public static void main(String[] args) throws Exception{

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int T = Integer.parseInt(br.readLine());

		for(int tc = 1; tc <= T; tc++) {

			N = Integer.parseInt(br.readLine());
			arr = new char[N][N];
			max = 0;

			for(int i = 0; i < N; i++) {
				String line = br.readLine();
				for(int j = 0; j < N; j++) {
					arr[i][j] = line.charAt(j);
				}
			}

			for(int i = 0; i < N; i++) {
				for(int j = 0; j < N; j++) {
					if(arr[i][j] == 'B') {
						if(simulate(i,j)) {

							int temp = calculate(i,j);

							max = Math.max(temp,max);

						}else {
							if(max == 0)
							max = 2;
						}
					}
				}
			}
			System.out.println("#" + tc + " " +  max);


		}



	}
	static boolean simulate(int a, int b) {
		boolean[][] visited = new boolean[a][b];

		for(int i = 0; i < 8; i++) {
			int nx = a + dx[i];
			int ny = b + dy[i];

			if(!inRange(nx,ny)) continue;

			if(arr[nx][ny] == 'G') return false;
		}

		return true;
	}

	static int calculate(int a,int b) {
		int score = 0;

		for(int i= 0; i < N; i++) {
			if(arr[i][b] == 'B') {
				score += 1;
			}
		}

		for(int i= 0; i < N; i++) {
			if(arr[a][i] == 'B') {
				score += 1;
			}
		}

		return score -1; //현재 좌표를 2번 세므로 -1

	}

	static boolean inRange(int x, int y) {
