 */ 

//부지는 한 변이 N 인 정사각형
//부지는 1인 구획으로 나누어짐
//빌딩 : B , 공원 : G
//G와 인접한 구역은 반드시 2층
//G와 인접하지 않은 구역은 현위치 가로/세로의 B를 더한 만큼 빌딩을 세운다.
public class BuildingTest {

    public static void main(String[] args) throws Exception {

    	BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    	int T = Integer.parseInt(br.readLine());

    	StringBuilder sb = new StringBuilder();

        for (int testCase = 1; testCase <= T; testCase++) {
            int N = Integer.parseInt(br.readLine());
            // char 2차원 배열(B, C)
            char[][] map = new char[N][N];

            for (int row = 0; row < N; row++) {

                StringTokenizer st = new StringTokenizer(br.readLine());

                for (int column = 0; column < N; column++) {

                	map[row][column] = st.nextToken().charAt(0);
                }
            }

            // 각 행과 열에 있는 B의 수를 미리 계산 ex) 행[0] = 2, 열[0] = 2...
            int[] rowCount = new int[N];
            int[] columnCount = new int[N];

            for (int row = 0; row < N; row++) {
                for (int column = 0; column < N; column++) {
                    if (map[row][column] == 'B') {
                        rowCount[row]++;
                        columnCount[column]++;
                    }
                }
            }

            int maxHeight = 0;

            for (int row = 0; row < N; row++) {
                for (int column = 0; column < N; column++) {
                    // 공원에는 빌딩x => continue
                    if (map[row][column] == 'G') {
                        continue;
                    }

                    int height;

                    if (hasPark(map, row, column, N)) {
                        height = 2;
                    } else {
                        // 중복 1 뺌
                        height = rowCount[row] + columnCount[column] - 1;
                    }
                    // 최댓값 갱신
                    if (height > maxHeight) {
                        maxHeight = height;
                    }
                }
            }

            sb.append('#').append(testCase).append(' ').append(maxHeight).append('\n');


        }
        System.out.print(sb);
    }

    // 3x3 칸에 G가 있는지 탐색
    static boolean hasPark(char[][] map, int row, int column, int N) {

        for (int nextRow = row - 1; nextRow <= row + 1; nextRow++) {

        	for (int nextColumn = column - 1; nextColumn <= column + 1; nextColumn++) {

                // 경계 밖
                if (nextRow < 0 || nextRow >= N || nextColumn < 0 || nextColumn >= N) {
                    continue;
                }


                if (map[nextRow][nextColumn] == 'G') {
                    return true;
                }
            }
        }

        return false;
    }
}

