/**
 * B구획의 빌딩 최고 높이 구하기
 * 
 * - N x N의 칸을 모두 탐색한다.
 * 		- 만약 인접 부분에 G가 있으면 -> height = 2 (boolean hasG = true)
 * 		- maxHeight를 구한다.
 * 			- 만약 hasG -> currHeight = 2
 * 			- 아니라면 -> 현 위치의 row, col 탐색하며 B의 개수 카운트 -> currHeight = rowB + colB
 * 			- maxHeight 업데이트하기
 * 		- maxHeight가 답이된다.
 *
 */ 
public class BuildingTest {

	public static void main(String[] args) throws Exception{

		// 인접 부분 8칸
		int[] dy = new int[] {-1, -1, -1, 0, 0, 1, 1, 1};
		int[] dx = new int[] {-1, 0, 1, -1, 1, -1, 0, 1};

		// use buffer to take input
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		/*
		입력:
			- 테스트 케이스 T
			- 배열의 크기 N
			- char[][] building = new char[N][N]
		*/
		int T = Integer.parseInt(br.readLine());

		for (int t = 1; t <= T; t++) {

			int N = Integer.parseInt(br.readLine());

			char[][] building = new char[N][N];

			for (int i = 0; i < N; i++) {
				StringTokenizer st = new StringTokenizer(br.readLine());
				for (int j = 0; j < N; j++) {
					building[i][j] = st.nextToken().charAt(0);
				}
			}

			int maxHeight = 0;

			// 만약 인접 부분에 G가 있으면 -> height = 2 (boolean hasG = true)
			for (int i = 0; i < N; i++) {
				for (int j = 0; j < N; j++) {

					if (building[i][j] == 'G') continue;

					boolean hasG = false;

					for (int d = 0; d < 8; d++) {
						int ny = i + dy[d];
						int nx = j + dx[d];

						// ny nx가 N x N 범위 안에 있는지 확인
						if (ny >= 0 && ny < N && nx >= 0 && nx < N) {
							if (building[ny][nx] == 'G') {
								hasG = true;
								break;
							}
						}
					}
					// maxHeight 구하기
					int currHeight;

					if (hasG) {
						currHeight = 2;
					} else {
						// 현 위치의 row, col 탐색하며 B의 개수 카운트 -> currHeight = rowB + colB
						int rowB = 0;
						int colB = 0;

						// row의 B 카운트 -> row만 업데이트
						for (int c = 0; c < N; c++) {
							if (building[i][c] == 'B') rowB++;
						}

						// col의 B 카운트 -> col만 업데이트
						for (int r = 0; r < N; r++) {
							if (building[r][j] == 'B') colB++;
						}
						currHeight = rowB + colB - 1;
					}
					// maxHeight 업데이트하기
					maxHeight = Math.max(currHeight, maxHeight);
				}
			}
			System.out.println("#" + t + " " + maxHeight);
		}

	}
}

