				if(!checkB(nextX,nextY)) {
					return false;
				}
			}
		}
		return true;
	}

	public static int check4(int x, int y) {
		int sumB=1;
		for(int i=0;i<n;i++) {
			if (i==x) {
				continue;
			}
			if (checkB(i,y)) {
				sumB+=1;
			}
		}
		for(int j=0;j<n;j++) {
			if (j==y) {
				continue;
			}
			if(checkB(x,j)) {
				sumB+=1;
			}
		}
		return sumB;
	}

	public static void main(String[] args) throws IOException {
		System.setIn(new FileInputStream("input.txt"));
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		T = Integer.parseInt(br.readLine());
		for (int idx = 0; idx < T; idx++) {
			n = Integer.parseInt(br.readLine());
			a = new char[n][n];
//			int[][] b = new int[n][n];
			for (int i = 0; i < n; i++) {
				StringTokenizer st = new StringTokenizer(br.readLine());
				for (int j = 0; j < n; j++) {
					a[i][j] = (st.nextToken()).charAt(0);
				}
			}
			int maxValue=Integer.MIN_VALUE;
			for (int i=0;i<n;i++) {
				for (int j=0;j<n;j++) {
					if(checkB(i,j)) {
						if(check8(i,j)) {
							maxValue=Math.max(maxValue,check4(i,j));
						}
						else {
							maxValue=Math.max(maxValue,2);
						}
					}
				}
			}
			System.out.println("#"+(idx+1)+" "+maxValue);

		}

	}
}

import java.io.BufferedReader;
