/**
 * B구획의 빌딩 최고 높이 구하기
 */ 
public class BuildingTest {

	public static int bfs(String[][] area) {

		int n = area.length;
		int[] dx = {-1,-1,-1,0,1,1,1,0};
		int[] dy = {-1,0,1,1,1,0,-1,-1};
		int ans = 0;

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (area[i][j].equals("B")) {
					// 최소 2층이 된다.
					ans = Math.max(ans, 2);
					boolean flag = true;
					for (int k = 0; k < 8; k++) {
						int x = i + dx[k], y = j + dy[k];
						if ((x >= 0) && (x < n) && (y >= 0) && (y < n)) {
							if (area[x][y].equals("B")) {
								continue;
							} 
							flag = false;
							break;
						}

					}
					if (flag) {
						int cnt = 0;
						for (int a = 0; a < n; a++) {
							if (area[i][a].equals("B")) {
								cnt++;
							}
							if (area[a][j].equals("B")) {
								cnt++;
							}
						}
						cnt -= 1;
						ans = Math.max(ans, cnt);

					} else {
						continue;
					}
				}
			}
		}

		return ans;

	}

	public static void main(String[] args) throws Exception{

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int tc = Integer.parseInt(br.readLine());

		for (int t = 1; t <= tc; t++) {
			int n = Integer.parseInt(br.readLine());
			String[][] area = new String[n][n];
			for (int i = 0; i < n; i++) {
				StringTokenizer st = new StringTokenizer(br.readLine());				
				for (int j = 0; j < n; j++) {					
					area[i][j] = st.nextToken();
				}
			}

			int result = bfs(area);
			StringBuilder sb = new StringBuilder();
			sb.append("#").append(t).append(" ").append(result).append("\n");
			System.out.print(sb);



		}
	}
}

