public class BuildingTest {

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {

            int N = Integer.parseInt(br.readLine());

            char[][] map = new char[N][N];

            for (int i = 0; i < N; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());

                for (int j = 0; j < N; j++) {
                    map[i][j] = st.nextToken().charAt(0);
                }
            }

            int max = 0;

            int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
            int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {

                    if (map[i][j] == 'G')
                        continue;

                    boolean nearG = false;

                    // 상하좌우에 G가 있는지 확인
                    for (int d = 0; d < 8; d++) {
                        int nx = i + dx[d];
                        int ny = j + dy[d];

                        if (nx >= 0 && nx < N && ny >= 0 && ny < N) {
                            if (map[nx][ny] == 'G') {
                                nearG = true;
                                break;
                            }
                        }
                    }

                    int height;

                    if (nearG) {
                        height = 2;
                    } else {
                        height = 0;

                        // 같은 행의 B 개수
                        for (int k = 0; k < N; k++) {
                            if (map[i][k] == 'B')
                                height++;
                        }

                        // 같은 열의 B 개수
                        for (int k = 0; k < N; k++) {
                            if (map[k][j] == 'B')
                                height++;
                        }

                        // 자기 자신 중복 제거
                        height--; 
                    }

                    if (height > max)
                        max = height;
                }
            }

            System.out.println("#" + tc + " " + max);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * B구획의 빌딩 최고 높이 구하기
 */ 
public class BuildingTest {

	public static void main(String[] args) throws IOException {
		// 코드를 작성해주세요.
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine());

		final int D = 8;
		int[] dr = new int[] {1, 0, -1, 0, -1, 1, -1, 1};
		int[] dc = new int[] {0, 1, 0, -1, -1, -1, 1, 1};

		// 현재 좌표인근에 G가 위치한다면 높이는 2가 최대
		// 바운드 밖에는 G가 없다고 가정
		// 현재 위치에 대해 dx,dy를 통해 주변 탐색
		// 인접하지 않은 같은 행과 같은 열에 있는 빌딩의 수를 합산하여 최대 높이 계산

		for (int tc = 1; tc <= T; tc += 1) {
			sb.append('#').append(String.valueOf(tc)).append(' ');
			int maxRes = 0;

			int n = Integer.parseInt(br.readLine());
			char[][] grid = new char[n][n];

			for (int j = 0; j < n; j += 1) {
				st = new StringTokenizer(br.readLine());

				for (int k = 0; k < n; k += 1) {
					grid[j][k] = st.nextToken().charAt(0);
				}
			}


			for (int r = 0; r < n; r += 1) {
				for (int c = 0; c < n; c += 1) {
					char cur = grid[r][c];
					boolean isIsolated = true;

					if (cur == 'G') continue;

					for (int d = 0; d < D; d += 1) {
						int nr = r + dr[d];
						int nc = c + dc[d];

						if (0 > nr || nr >= n || 0 > nc || nc >= n) continue;

						if (grid[nr][nc] == 'G') {
							isIsolated = false;
							break;
						}
					}

					if (!isIsolated) {
						maxRes = Math.max(maxRes, 2);
						continue;
					}

					int cnt = 0;

					for (int i = 0; i < n; i += 1) {
						cnt += grid[r][i] == 'B' ? 1 : 0;
						cnt += grid[i][c] == 'B' ? 1 : 0;
					}

					maxRes = Math.max(maxRes, cnt - 1);
				}
			}

			sb.append(String.valueOf(maxRes)).append('\n');
		}


		bw.write(sb.toString());
		bw.flush();
		bw.close();

	}
}

