/*
 * 전략:
 * - 입력 받을때 1이 나타나는 첫 인덱스를 저장한다.
 * - 0으로 초기화 된 배열을 1이 나타나는 첫 인덱스부터 끝까지 1로 채워준다. -> 채울때마다 답++ 해주기
 * - 1이 나타나는 첫 인덱스의 다음 인덱스부터 반복문을 돌며 nums와 original인덱스를 비교한다:
 * -	같으면 스킵
 * -	nums[i] == 1이면 1로 채우고 답 +1
 * -	nums[i] == 0이면 0으로 채우고 답 +1
 * */

public class swea1289 {

	public static void main(String[] args) throws NumberFormatException, IOException {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {

			int answer = 0;

			String line = br.readLine();

			int[] nums = new int[line.length()];
			int[] original = new int[line.length()];

			// 인풋 숫자들을 int[]로 변경해주고,
			// 새로 만들 숫자들을 0으로 초기화해주기
			for (int i = 0; i < line.length(); i++) {
				nums[i] = line.charAt(i) - '0';
				original[i] = 0;
			}

			// 1. 첫 1이 나오는 인덱스 찾기
			boolean oneFound = false;
			int firstOneIndex = 0;
			for (int i = 0; i < line.length(); i++) {
				if (nums[i] == 1) {
					oneFound = true;
					firstOneIndex = i;
					break;
				}
			}

			// 만약 1이 없으면 답은 0이다
			if (!oneFound) {
				answer = 0;
			}

			else {
				// 2. firstOneIndex 부터 끝까지 1로 채워주기
				for (int i = firstOneIndex; i < nums.length; i++) {
					original[i] = 1;
				}
				// 채울때마다 답 +1
				answer++;

				// 3. firstOneIndex의 다음 인덱스 부터 시작
				for (int i = firstOneIndex + 1; i < nums.length; i++) {
					// 4. 만약 nums와 original이 같으면 끝났다
					if (Arrays.equals(nums, original)) {
						break;
					}
					// 5. nums[i] original[i] 같으면 스킵
					if (nums[i] == original[i]) {
						continue;
					}
					// 6. nums[i] == 1이면 1로 채우고 답 +1
					if (nums[i] == 1) {
						for (int j = i; j < nums.length; j++) {
							original[j] = 1;
						}
						answer++;
					}
					// 7. nums[i] == 0이면 0으로 채우고 답 +1
					else {

						for (int j = i; j < nums.length; j++) {
							original[j] = 0;
						}
						answer++;
					}
				}
			}
			// 8. 답 프린트
			System.out.println("#" + tc + " " + answer);
		}
	}
}

