			// 5. 현재 테스트 케이스의 카드 개수 N 입력 및 정수 변환
			int N = Integer.parseInt(br.readLine());

			// 6. 예외 처리: 카드가 1장인 경우, 셔플이 필요 없으므로 바로 읽어서 결과에 추가 후 다음 케이스로 이동
			if (N == 1) {
				sb.append(br.readLine()); // 카드 1장을 읽어서 추가
				sb.append("\n");          // 줄바꿈 반영
				continue;                 // 아래의 셔플 로직을 건너뛰고 다음 테스트 케이스 실행
			}

			// 7. 한 줄로 나열된 카드 목록을 공백(" ") 문자 기준으로 분리하여 배열에 저장
			card = br.readLine().split(" ");

			// 8. 카드 개수(N)가 짝수인 경우의 퍼펙트 셔플 로직
			if (N % 2 == 0) {
				// 카드 묶음의 정확한 절반 크기(N/2)만큼 반복 수행
				for (int i = 0; i < N / 2; i++) {
					sb.append(card[i]).append(" "); // 앞쪽 절반 묶음의 i번째 카드 추가
					sb.append(card[i + N / 2]).append(" "); // 뒤쪽 절반 묶음의 i번째 카드 추가 (절반만큼 건너뛴 인덱스)
				}
			}
			// 9. 카드 개수(N)가 홀수인 경우의 퍼펙트 셔플 로직
			else {
				// 앞쪽 묶음이 뒤쪽보다 1장 더 많아야 하므로, 뒤쪽 묶음 크기인 N/2 직전까지만 먼저 교대로 추가
				for (int i = 0; i < N / 2; i++) {
					sb.append(card[i]).append(" "); // 앞쪽 절반 묶음의 i번째 카드 추가
					sb.append(card[i + N / 2 + 1]).append(" "); // 뒤쪽 절반 묶음의 i번째 카드 추가 (앞쪽이 1장 더 많으므로 인덱스에 +1 반영)
				}
				// 앞쪽 묶음의 가장 마지막에 남아있는 카드(가운데 인덱스인 N/2번 카드)를 최종 추가
				sb.append(card[N / 2]);
			}

			// 10. 현재 테스트 케이스의 카드 셔플 출력이 모두 끝나면 줄바꿈 추가
			sb.append("\n");
		}

		// 11. StringBuilder에 모인 모든 전체 결과를 BufferedWriter를 통해 표준 출력으로 전달
		bw.write(sb.toString());
		bw.flush(); // 남아있는 출력 스트림 버퍼를 깨끗이 비움
		bw.close(); // 사용이 끝난 입출력 스트림 자원 해제
	}
}

