import java.io.*;
import java.util.*;

public class Swea_3499 {
//	card shuffle을 위한 덱의 크기 N, 출력부 최적화를 위한 StringBuilder를 static 으로 전역 초기화
	static int N;
	static StringBuilder sb = new StringBuilder();

//	- 핵심 로직(중앙값을 찾은 뒤, for문을 통한 순회로 인덱싱하여 deck을 셔플함
	static void shuffleCard(String[] decks) {
		int mid = (N + 1) / 2;

		for (int i = 0; i < mid; i += 1) {
			sb.append(decks[i]).append(' ');

			if (i + mid < N) {
				sb.append(decks[mid + i]).append(' ');
			}
		}
		sb.append('\n');
	}

	public static void main(String[] args) throws IOException {
		// 입력 및 초기 설정
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
		StringTokenizer st;


		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc += 1) {
			sb.append('#').append(tc).append(' ');

			N = Integer.parseInt(br.readLine());
			String[] decks = new String[N];

//			카드를 입력받아 decks 배열에 저장 후, shuffleCard 함수로 넘겨버린 후 로직 수행
			st = new StringTokenizer(br.readLine());

			for (int i = 0; i < N; i += 1) {
				decks[i] = st.nextToken();
			}

			shuffleCard(decks);
		}

		bw.write(sb.toString());
		bw.flush();
		bw.close();

	}

}

import java.util.*;
import java.io.*;

public class 퍼펙트셔플 {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        int T = Integer.parseInt(br.readLine());
        for (int tc = 1; tc <= T; tc++) {
            // 출력 형식 맞추기
            sb.append("#").append(tc).append(" ");

            int N = Integer.parseInt(br.readLine());
            String[] cards = new String[N+1];
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < N; i++) {
                cards[i] = st.nextToken();
            }
            // 투 포인터로 범위 나눠서 번갈아가면서 넣어서 출력하기
            int p1 = 0;
            int p2;

            // 카드 하나면 빠르게 처리
            if (N == 1) {
                sb.append(cards[0]).append(" ");
                continue;
            }
            // N이 짝수면 p1: 0~N/2-1 | p2: N/2 ~ N-1
            else if (N % 2 == 0) {
                p2 = N/2;
                while (p2 <= N - 1) {
                    sb.append(cards[p1++]).append(" ");
                    sb.append(cards[p2++]).append(" ");
                }
            } else { // N이 홀수면 p1: 0~N/2 | p2: N/2+1 ~ N-1
                p2 = N/2 + 1;
                while (p1 <= N/2) {
                    if (p2 != N-1) {
                        sb.append(cards[p1++]).append(" ");                     
                        sb.append(cards[p2++]).append(" ");     
                    } else {
                        sb.append(cards[p1++]).append(" ");
                        sb.append(cards[p2++]).append(" ").append(cards[p1++]).append(" ");
                    }
                }
            }
            sb.append("\n");
        }
