/*
 * split(" ")로 잘라서 배열에 집어넣기
 * 배열의 특정 구간을 복사해서 leftArr, rightArr를 생성해서 집어넣기
 * 		leftArr : 0부터 절반까지 (홀수일 경우 절반+1까지)
 * 		rightArr : 절반 이후부터 끝까지
 * 
 * leftArr와 rightArr를 번갈아 출력
 * 홀수일 경우 leftArr의 마지막 값 출력
 * 
 * */
import java.util.*;
import java.io.*;

class Solution {
	// if 조건문 안에 작성해야 해서 전역변수로 지정
	static String[] leftArr;
	static String[] rightArr;

	public static void main(String args[]) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine());
		for (int tc = 1; tc <= T; tc++) {
			sb.append("#").append(tc).append(" ");

			int N = Integer.parseInt(br.readLine()); // 카드 개수

			String cards = br.readLine(); // N개의 카드 이름(" "로 구분)

			// " "를 기준으로 잘라서 cardArr에 넣기
			String[] cardsArr = cards.split(" "); // ["JACK", "QUEEN", "KING", "ACE"]

			// 정확히 절반 나누기
			// 카드의 개수가 짝수 홀수에 따라 범위가 달라져 if-else 조건문으로 분기
			if (N % 2 == 0) {
				leftArr = Arrays.copyOfRange(cardsArr, 0, N / 2);
				rightArr = Arrays.copyOfRange(cardsArr, N / 2, N);
			} else {
				leftArr = Arrays.copyOfRange(cardsArr, 0, N / 2 + 1);
				rightArr = Arrays.copyOfRange(cardsArr, N / 2 + 1, N);
			}

			for (int i = 0; i < rightArr.length; i++) {
				sb.append(leftArr[i]).append(" ").append(rightArr[i]).append(" ");
			}

			// N이 홀수일 경우 leftArr에 카드가 하나 더 있음
			if (leftArr.length > rightArr.length) {
				sb.append(leftArr[leftArr.length - 1]).append(" ");
			}

			sb.append("\n");
		}

		System.out.print(sb);
	}
}

