import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Solution {
	/*
	 * 구현 문제 같은데, 짝수일때와 홀수일때의 경우가 달라
	 * 
	 * 반으로 갈라서 끼워넣어야 하는데, 뒤에있는 애들이 앞에있는거에 들어가는 방식, stack, 또는 큐 두개써서 하면 될듯
	 */
	public static void main(String args[]) throws Exception {
		// input 받기
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st;
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {
			int N = Integer.parseInt(br.readLine());
			st = new StringTokenizer(br.readLine());
			sb.append("#").append(tc).append(" ");


			Queue<String> first = new ArrayDeque<>();
			Queue<String> second = new ArrayDeque<>();


			int center = (N / 2) + 1;
			// 짝수
			if (N % 2 == 0)
				center = (N / 2);

			// 홀수
			for (int i = 0; i < N; i++) {
				if (i < center) {
					first.add(st.nextToken());
				} else {
					second.add(st.nextToken());
				}

			}

			// 셔플
			if (N % 2 == 0) {
				for (int i = 0; i < N; i += 2) {
					sb.append(first.poll()).append(" ");
					sb.append(second.poll()).append(" ");
				}
			} else {
				for (int i = 0; i < N-1; i += 2) {
					sb.append(first.poll()).append(" ");
					sb.append(second.poll()).append(" ");
				}
				sb.append(first.poll());
			}

			sb.append("\n");


		}
		System.out.println(sb);
	}
}

