/*
 * 전략:
 * 1. list로 원본 받기 (for loop)
 * 2. 명령어 포멧 정리 하기 -> 3가지의 List 생성하기 (시작 인덱스, 커맨드 갯수, 커맨드 리스트)
 * 3. 명령어 만큼 for loop 돌리기 
 * */

public class swea1228 {

	public static void main(String[] args) throws NumberFormatException, IOException {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); 
		StringBuilder sb = new StringBuilder(); 

		// 테케수 = 10으로 지정
		for (int tc = 1; tc <= 10; tc++) {

			// N = 원본 암호문의 길이 
			int N = Integer.parseInt(br.readLine());

			// String 으로 받아서 토크나이저로 빼오기 
			String originalLine = br.readLine(); 
			StringTokenizer st = new StringTokenizer(originalLine); 

			// 1. List로 원본 받기 
			List<Integer> original = new ArrayList<>(); 
			for (int i = 0; i < N; i++) {
				original.add(Integer.parseInt(st.nextToken())); 
			}

			// M = 명령어의 수 
			int M = Integer.parseInt(br.readLine()); 

			// 2. 명령어 포멧 정리하기 

			// 3개의 리스트 -> 시작, 갯수, 명령어들 
			List<Integer> startIndexes = new ArrayList<>(); 
			List<Integer> numCommands = new ArrayList<>();
			List<List<Integer>> commands = new ArrayList<>(); 

			// String 으로 받아서 토크나이저로 빼오기 
			String line = br.readLine(); 
			st = new StringTokenizer(line); 

			for (int i = 0; i < M; i++) {
				// "|"
				st.nextToken(); 

				// startIndex 
				int startIndex = Integer.parseInt(st.nextToken());
				// numCommands
				int numCommand = Integer.parseInt(st.nextToken());

				// commands 
				List<Integer> command = new ArrayList<>(); 
				for (int c = 0; c < numCommand; c++) {
					command.add(Integer.parseInt(st.nextToken())); 
				}

				startIndexes.add(startIndex);
				numCommands.add(numCommand);
				commands.add(command);
			}

			// 3. 명령어 만큼 for문 반복 
			for (int i = 0; i < M; i++) {
				int startIndex = startIndexes.get(i); 
				int cmdNums = numCommands.get(i); 
				List<Integer> cmds = commands.get(i); 

				original.addAll(startIndex, cmds);
			}
			// sb 
			sb.append("#").append(tc); 

			// [ ] 없애기 & 10개만 답에 넣게 
			for (int n = 0; n < 10; n++) {
				int currNum = original.get(n); 
				sb.append(" ").append(currNum); 
			}

			sb.append("\n"); 
		}
		System.out.println(sb);
	}
}

import java.io.*;
import java.util.*;

public class SWEA1228 {
	static int[] next;
	static int[] prev;
	static List<Integer> numList;
	static int first = 0;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		next = new int[220]; // 최대 길이 220(초기 20 + 명령어10 * 20)
		prev = new int[220];
		numList = new ArrayList<>();

		for(int t = 1; t <= 10; t++) {
			Arrays.fill(next, -1);
			Arrays.fill(prev, -1);
			numList.clear();
			first = 0; // 가장 앞에 있는 숫자의 idx

			// 원본 암호문 입력
			int N = Integer.parseInt(br.readLine());
			StringTokenizer st = new StringTokenizer(br.readLine());
			for(int i = 0; i < N; i++) {
				numList.add(Integer.parseInt(st.nextToken()));
				next[i] = i + 1;
				prev[i] = i - 1;
			}
			next[N - 1] = -1;

			// 명령 입력
			int C = Integer.parseInt(br.readLine());
			st = new StringTokenizer(br.readLine());
			List<Integer> addList = new ArrayList<>();

			for(int c = 0; c < C; c++) {
				st.nextToken(); // I 제거
				int idx = Integer.parseInt(st.nextToken());
				int M = Integer.parseInt(st.nextToken());

				for(int i = 0; i < M; i++) {
					addList.add(Integer.parseInt(st.nextToken()));
				}

				for(int num : addList) {
					add(idx++, num);
				}

				addList.clear();
			}
			sb.append("#").append(t).append(" ");
			getResult(sb);
		}
		System.out.print(sb);
	}

	private static void add(int idx, int num) {
		int prevIdx, currIdx;

		// 맨 앞에 삽입하는 경우 앞 숫자가 없음
	    if (idx == 0) {
	        prevIdx = -1;
	        currIdx = first;
	    // 그 외에는 앞 숫자의 인덱스를 찾음
	    } else {
	        prevIdx = first;
	        for (int i = 0; i < idx - 1; i++) {
	            prevIdx = next[prevIdx];
	            if (prevIdx == -1) return;
	        }
	        currIdx = next[prevIdx];
	    }

	    numList.add(num);
	    int numIdx = numList.size() - 1;

	    // 현재 숫자의 포인터들을 자리에 맞게 적용
	    prev[numIdx] = prevIdx;
	    next[numIdx] = currIdx;

	    // 기존 숫자들의 포인터를 numIdx를 가리키게 함
	    // 맨 앞에 삽입하는 경우는 포인터 갱신 대신 first 갱신
	    if (currIdx != -1) prev[currIdx] = numIdx;
	    if (prevIdx != -1) {
	        next[prevIdx] = numIdx;
	    } else {
	        first = numIdx;
	    }
	}

	private static void getResult(StringBuilder sb) {
		int pointer = first;

		for(int i = 0; i < 10; i++) {
			sb.append(numList.get(pointer)).append(" ");
			pointer = next[pointer];
		}
		sb.append("\n");
	}
}

