public class SWEA1228 {

	static class Node {
		int val;
		Node next;

		Node(int val) {
			this.val = val;
		}
	}

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st;

		for (int tc = 1; tc <= 10; tc++) {
			int n = Integer.parseInt(br.readLine().trim());
			st = new StringTokenizer(br.readLine().trim());
			Node root = new Node(Integer.parseInt(st.nextToken()))	;
			Node prev = root;
			for (int i = 1; i < n; i++) {
				Node curr = new Node(Integer.parseInt(st.nextToken()));
				prev.next = curr;
				prev = curr;
			}

			//

			int commandSize = Integer.parseInt(br.readLine().trim());
			String[] commands = br.readLine().trim().split(" ");
			int p = 0;
			while (p < commands.length) {
				if (commands[p].equals("I")) {
					int idx = Integer.parseInt(commands[++p]);
					if (idx == 0) {
						// 루트에 넣기
						int size = Integer.parseInt(commands[++p]);
						Node next = root;
						for (int i = 0; i < size; i++) {
							if (i == 0) {
								root = new Node(Integer.parseInt(commands[++p]));
								prev = root;
								continue;
							}
							Node curr = new Node(Integer.parseInt(commands[++p]));
							prev.next = curr;
							prev = curr;
						}
						prev.next = next;
					} else {

						int size = Integer.parseInt(commands[++p]);
						prev = findNode(root, idx);
						Node next = prev.next;
						for (int i = 0; i < size; i++) {
							Node curr = new Node(Integer.parseInt(commands[++p]));
							prev.next = curr;
							prev = curr;
						}
						prev.next = next;
					}

				}
				p++;
			}

			StringBuilder sb = new StringBuilder();
			sb.append("#").append(tc).append(" ");
			int i = 1;
			Node node = root;
			while (i <= 10) {
				sb.append(node.val).append(" ");
				node = node.next;
				i++;
			}

			System.out.println(sb);


		}
	}

	static Node findNode(Node root, int idx) {
		int i = 1;
		Node curr = root;
		while (i < idx) {
			curr = curr.next;
			i++;
		}
		return curr;
	}
}

