import java.io.*;
import java.util.*;

public class SWEA1229 {
	static int[] next;
	static int[] prev;
	static List<Integer> numList;
	static int first = 0;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		next = new int[4200]; // 최대 길이 4200(초기 200 + 명령어200 * 20)
		prev = new int[4200];
		numList = new ArrayList<>();

		for(int t = 1; t <= 10; t++) {
			Arrays.fill(next, -1);
			Arrays.fill(prev, -1);
			numList.clear();
			first = 0; // 가장 앞에 있는 숫자의 idx

			// 원본 암호문 입력
			int N = Integer.parseInt(br.readLine());
			StringTokenizer st = new StringTokenizer(br.readLine());
			for(int i = 0; i < N; i++) {
				numList.add(Integer.parseInt(st.nextToken()));
				next[i] = i + 1;
				prev[i] = i - 1;
			}
			next[N - 1] = -1;

			// 명령 입력
			int C = Integer.parseInt(br.readLine());
			st = new StringTokenizer(br.readLine());
			List<Integer> addList = new ArrayList<>();

			for(int c = 0; c < C; c++) {
				String command = st.nextToken();
				int idx = Integer.parseInt(st.nextToken());
				int M = Integer.parseInt(st.nextToken());

				switch(command) {
					case "I":
						for(int i = 0; i < M; i++) {
							addList.add(Integer.parseInt(st.nextToken()));
						}

						for(int num : addList) {
							add(idx++, num);
						}

						addList.clear();
						break;
					case "D":
						for(int i = 0; i < M; i++) {
							delete(idx);
						}		
				}
			}
			sb.append("#").append(t).append(" ");
			getResult(sb);
		}
		System.out.print(sb);
	}

	private static void add(int idx, int num) {
		int prevIdx, currIdx;

		// 맨 앞에 삽입하는 경우 앞 숫자가 없음
	    if (idx == 0) {
	        prevIdx = -1;
	        currIdx = first;
	    // 그 외에는 앞 숫자의 인덱스를 찾음
	    } else {
	        prevIdx = first;
	        for (int i = 0; i < idx - 1; i++) {
	            prevIdx = next[prevIdx];
	            if (prevIdx == -1) return;
	        }
	        currIdx = next[prevIdx];
	    }

	    numList.add(num);
	    int numIdx = numList.size() - 1;

	    // 현재 숫자의 포인터들을 자리에 맞게 적용
	    prev[numIdx] = prevIdx;
	    next[numIdx] = currIdx;

	    // 기존 숫자들의 포인터를 numIdx를 가리키게 함
	    // 맨 앞에 삽입하는 경우는 포인터 갱신 대신 first 갱신
	    if (currIdx != -1) prev[currIdx] = numIdx;
	    if (prevIdx != -1) {
	        next[prevIdx] = numIdx;
	    } else {
	        first = numIdx;
	    }
	}

	private static void delete(int idx) {
		int prevIdx, currIdx, nextIdx;

		if(idx == 0) {
			prevIdx = -1;
			currIdx = first;
			nextIdx = next[first];
		}
		else {
			prevIdx = first;
			currIdx = first;
	        for (int i = 0; i < idx; i++) {
	        	prevIdx = currIdx;
	            currIdx = next[currIdx];
	            if (currIdx == -1) return;
	        }
	        nextIdx = next[currIdx];
		}

		// 현재 idx의 링크 해제
		prev[currIdx] = -1;
		next[currIdx] = -1;

		// 이전 값과 다음 값을 서로 연결
		if(prevIdx != -1) next[prevIdx] = nextIdx;
		else first = next[first]; // prevIdx가 -1이었으면 first 갱신
		if(nextIdx != -1) prev[nextIdx] = prevIdx;
	}

	private static void getResult(StringBuilder sb) {
		int pointer = first;

		for(int i = 0; i < 10; i++) {
			sb.append(numList.get(pointer)).append(" ");
			pointer = next[pointer];
		}
		sb.append("\n");
	}
}

