                    int x = Integer.parseInt(cst.nextToken()); //삭제할 위치
                    int y = Integer.parseInt(cst.nextToken()); //삭제할 갯수
                    for (int k = 0; k < y;  k++) {
                        cipherText.remove(x);//제거
                    }
