                    int x = Integer.parseInt(cst.nextToken()); //삽입할 위치
                    int y = Integer.parseInt(cst.nextToken()); //삽입할 갯수

                    for (int l = 0; l < y; l++) {
                        cipherText.add(x++, Integer.parseInt(cst.nextToken())); //원문에 삽입
