public class 암호문2 {

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		for (int tc = 1; tc <= 10; tc++) {
			sb.append("#").append(tc).append(" ");
			int N = Integer.parseInt(br.readLine());
			// 암호문 리스트
			List<String> list = new LinkedList<>();

			// 연결 리스트로 암호문 구성
			st = new StringTokenizer(br.readLine());
			for (int i = 0; i < N; i++) {
				list.add(i, st.nextToken());
			}

			// 명령문 개수
			int numInst = Integer.parseInt(br.readLine());

			// 명령문을 입력 받아서 객체로 생성하고 배열에 저장
			st = new StringTokenizer(br.readLine());
			for (int i = 0; i < numInst; i++) {
				// 삽입일 경우 데이터도 객체에 같이 넣어서 배열에 삽입
				char type = st.nextToken().charAt(0);
				// 삽입 or 삭제 실행할 위치
				int x = Integer.parseInt(st.nextToken());
				// 데이터 개수
				int y = Integer.parseInt(st.nextToken());
				if (type == 'I') {					
					// 삽입 명령 실행
					for (int j = 0; j < y; j++) {
						list.add(x + j, st.nextToken());						
					}
				}
				// 삭제 타입 명령어일 경우 data는 따로 만들지 않고 배열에 삽입
				else if (type == 'D'){
					for (int j = 0; j < y; j++) {
						list.remove(x);
					}
				}
			}
			// 명령 실행 후 암호문을 sb에 저장(앞의 10개 항만 출력하므로 10개만 넣으면 됨)
			for (int i = 0; i < 10; i++) {
				sb.append(list.get(i)).append(" ");				
			}
			sb.append("\n");
		} // tc end
		System.out.print(sb);
	} // main end
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;

import java.util.StringTokenizer;

public class Solution {
	/*
	 * 원본 암호문의 길이가 좀 길어졌음, 20개의 정수로 넣는다고 할때, 200*200 = 40000 안정권임. 200*200*200도 8000000안정권임
	 * */
	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st; 

		for(int tc =1 ; tc<=10 ;tc++ ) {
			sb.append("#").append(tc).append(" ");

			//origin받기
			ArrayList<Integer> origins = new ArrayList<>();

			int OL = Integer.parseInt(br.readLine());

			st = new StringTokenizer(br.readLine());
			for(int i = 0 ; i < OL ; i++) {
				origins.add(Integer.parseInt(st.nextToken()));
			}

			int CL = Integer.parseInt(br.readLine());

			st = new StringTokenizer(br.readLine());



			for(int i = 0 ; i < CL ; i++) {
				char c = st.nextToken().charAt(0);
				int idx = Integer.parseInt(st.nextToken());
				int count = Integer.parseInt(st.nextToken());

				ArrayList<Integer> temps = new ArrayList<>();

				if(c == 'I') {
					for(int j = 0 ; j <count ;j++) {
						temps.add(Integer.parseInt(st.nextToken()));
					}
					origins.addAll(idx ,temps);
				}else {
					for(int j = count ; j > 0; j--) {
						origins.remove(idx +j -1);
					}
				}	
			}
			for(int i = 0 ; i < 10 ; i++) {
				sb.append(origins.get(i)).append(" ");	
			}
			sb.append("\n");
		}
		System.out.println(sb);
	}
}

// SWEA 암호문 2
/*
 * "I"일 경우 삽입할 암호문들을 배열로 만든 후 cipherText에 삽입
 * "D"일 경 count만큼 remove
 * */

import java.util.*;
import java.io.*;

public class SWEA_1229 {
	static int N, C; // N: 암호문의 길이, C: 명령어 개수

	static ArrayList<Integer> cipherText; // 원본 암호문

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		for (int tc = 1; tc <= 10; tc++) {
			N = Integer.parseInt(br.readLine()); // 원본 암호문 길이 입력

			// 원본 암호문 입력
			cipherText = new ArrayList<>();

			StringTokenizer st = new StringTokenizer(br.readLine());
			for (int i = 0; i < N; i++) {
				cipherText.add(Integer.parseInt(st.nextToken()));
			}

			C = Integer.parseInt(br.readLine()); // 명령어 개수 입력
			st = new StringTokenizer(br.readLine()); // 명령어 전체 입력

			for (int i = 0; i < C; i++) {
				String command = st.nextToken(); // 삽입 명령어
				int start = Integer.parseInt(st.nextToken()); // 시작 위치
				int count = Integer.parseInt(st.nextToken()); // 삽입/삭제 숫자 개수

				// 삽입할 암호문 입력
				ArrayList<Integer> insertNum = new ArrayList<>();

				// start 위치에 암호문들 삽입
				if (command.equals("I")) {
					for (int j = 0; j < count; j++) {
						insertNum.add(Integer.parseInt(st.nextToken()));
					}

					cipherText.addAll(start, insertNum);
				}

				// start 위치부터 숫자 삭제
				if (command.equals("D")) {
					for (int a = 0; a < count; a++) {
						// 삭제하면 인덱스가 앞으로 당겨지기 때문에
						// 같은 위치에서 계속 삭제
						cipherText.remove(start);
					}
				}
			}

			sb.append("#").append(tc).append(" ");
			for (int i = 0; i < 10; i++) {
				sb.append(cipherText.get(i)).append(" ");
			}
			sb.append("\n");
		}

		System.out.print(sb);
	}
}

