	public static int[]	dy = {0, 1, 0, -1};

	public static boolean[][] visited;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		for (int tc = 1; tc <= 10; tc++) {
			int t = Integer.parseInt(br.readLine().trim());
			int[][] board = new int[16][16];
			int[] start = new int[2];
			int[] dest = new int[2];
			deq = new ArrayDeque<>();
			visited = new boolean[16][16];
			for (int i = 0; i < 16; i++) {
				String row = br.readLine().trim();
				for (int j = 0; j < 16; j++) {
					board[i][j] = row.charAt(j) - '0';
					if (board[i][j] == 2) {
						start[0] = i;
						start[1] = j;
					} else if (board[i][j] == 3) {
						dest[0] = i;
						dest[1] = j;
					}
				}
			}

			deq.offerLast(start);

			int answer = bfs(start, dest, board);

			System.out.println("#" + t + " " + answer);

		}


	}

	public static int bfs(int[] start, int[] dest,int[][] board) {

		while (!deq.isEmpty()) {
			int[] candidate = deq.pollFirst();
			visited[candidate[0]][candidate[1]] = true;
			if (candidate[0] == dest[0] && candidate[1] == dest[1]) {
				return 1;
			}
			for (int i = 0; i < 4; i++) {
				int nx = candidate[0] + dx[i];
				int ny = candidate[1] + dy[i];
				if (!inRange(nx,ny)) continue;
				if (board[nx][ny] == 1) continue;
				if (visited[nx][ny]) continue;
				deq.offerLast(new int[] {nx,ny});
			}

		}

		return 0;

	}

	public static boolean inRange(int x, int y) {
		return (x >= 0 && x < 16 && y >= 0 && y < 16);
	}
