            	String str = br.readLine();
            	for(int j=0; j<16; j++) {
            		graph[i][j] = Integer.parseInt(String.valueOf(str.charAt(j)));
            	}
            }

            for(int i=0; i<16; i++) {
            	for(int j=0; j<16; j++) {
            		if(graph[i][j] == 2) {
            			answer = 0;
            			bfs(i, j);
            		}
            	}
            }
            sb.append("#").append(test_case).append(" ").append(answer).append("\n");
        }
        System.out.print(sb);
    }
    static void bfs(int x, int y) {
