    		for(int dir=0; dir<4; dir++) {
    			int nx = cur[0] + dx[dir];
    			int ny = cur[1] + dy[dir];
    			if(nx < 0 || nx >= 16 || ny < 0 || ny >= 16) continue;
    			if(!vis[nx][ny] && graph[nx][ny] == 0) {
    				vis[nx][ny] = true;
    				q.offer(new int[]{nx, ny});
    			}
    			if(!vis[nx][ny] && graph[nx][ny] == 3) {
    				flag = true;
    				answer = 1;
    				break;
    			}
    		}
    		if(flag) break;
    	}
    }
