			visited[1][1] = 1; // check;

			boolean result = bfs(1,1);

			sb.append(result? 1 : 0).append("\n");

		}
		System.out.println(sb);
	}

	static Boolean bfs(int r, int c) {
		// 큐돌려~
		ArrayDeque<int[]> q = new ArrayDeque<>();

		q.offer(new int[] { r, c }); // 시작점 넣기


		while (!q.isEmpty()) {

			int[] current = q.poll();

			int cr = current[0];
			int cc = current[1];


			if(map[cr][cc] == 3 ) return true;


			for (int d = 0; d < 4; d++) {
				int nr = cr + dr[d];
				int nc = cc + dc[d];

				//범위 계산
				if(nr < 0 || nr >= N || nc < 0 || nc >= N ) continue;
				if(map[nr][nc]==1 ||visited[nr][nc] ==1 ) continue;

				q.offer(new int[] {nr,nc});
				visited[nr][nc] = 1;

			}
		}

		return false;
	}
}

