		StringTokenizer st ;
		for(int tc = 1 ; tc <= 10 ; tc++) {
			sb.append("#").append(tc);
			//번호 버리기
			st = new StringTokenizer(br.readLine());

			//감소한 숫자가 0이 되어 맨 뒤로 갈 경우

			int[] code = new int[N];

			st = new StringTokenizer(br.readLine());
			for(int i = 0 ; i < N ; i++) {
				code[i] = Integer.parseInt(st.nextToken());
			}
			int cnt = 0;

			while(code[N-1] != 0) {
				int tempFirst = code[0] - ((cnt % 5)+1);

				for(int i = 1 ; i < N ;i++) {
					code[i-1] = code[i]; 
				}

				code[N-1] = (tempFirst <=0 )? 0 : tempFirst;
				cnt++;
			}

			String s = "";
			for(int i = 0 ; i < N ;i++) {
				s +=" "+code[i];
			}
			sb.append(s).append("\n");

		}
		System.out.println(sb);
	}
