import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class SWEA_1233 {
    static int[] num;    // 피연산자(숫자)를 저장할 배열
    static int ss[];     // 노드의 상태를 기록할 배열 (0: 연산자, 1: 숫자)
    static char c[];     // 연산자(+, -, *, /)를 저장할 배열
    static boolean K;    // 해당 테스트 케이스의 식이 유효한지 여부를 체크하는 플래그 (true: 유효, false: 유효하지 않음)

    public static void main(String[] args) throws IOException {
        // 빠른 입력을 위해 BufferedReader 사용
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // 총 10개의 테스트 케이스가 주어짐
        for (int test_case = 1; test_case < 11; test_case++) {
            int N = Integer.parseInt(br.readLine()); // 트리를 구성하는 노드의 총 개수

            // 배열 크기를 노드의 개수(N)에 맞게 초기화 (0번 인덱스부터 사용하기 위해 N 크기로 지정)
            num = new int[N];
            c = new char[N];
            ss = new int[N];
            K = true; // 각 테스트 케이스 시작 시 유효성 플래그를 true로 초기화

            // N개의 줄에 걸쳐 각 노드의 정보가 입력됨
            for (int i = 0; i < N; i++) {
                st = new StringTokenizer(br.readLine());

                // [경우 1] 입력된 토큰(단어)의 개수가 4개인 경우 -> 자식 노드가 2개 있는 '내부 노드'
                // 형태: "노드번호 연산자 왼쪽자식번호 오른쪽자식번호"
                if (st.countTokens() == 4) {
                    int idx = Integer.parseInt(st.nextToken()) - 1; // 노드 번호 (0번 인덱스 기준으로 맞춰줌)
                    char k = st.nextToken().charAt(0);              // 해당 노드의 문자(연산자 혹은 숫자)

                    // 내부 노드인데 사칙연산자(+, -, *, /)가 아니라면 잘못된 트리구조임
                    if (k != '+' && k != '-' && k != '*' && k != '/') {
                        K = false; // 유효성 검사 실패
                    } else {
                        c[idx] = k;    // 연산자 배열에 저장
                        ss[idx] = 0;   // 0: 연산자 노드임을 표시
                    }
                } 
                // [경우 2] 입력된 토큰의 개수가 4개가 아닌 경우 (보통 리프 노드이거나 입력 구조가 다른 경우)
                // 형태: "노드번호 숫자" (자식이 없는 리프 노드)
                else {
                    int idx = Integer.parseInt(st.nextToken()) - 1; // 노드 번호 (0번 인덱스 기준)
                    char k = st.nextToken().charAt(0);              // 해당 노드의 문자

                    // 리프 노드(말단 노드)인데 숫자가 아니라 연산자가 오면 잘못된 트리구조임
                    if (k == '+' || k == '-' || k == '*' || k == '/') {
                        K = false; // 유효성 검사 실패
                    } else {
                        num[idx] = k - '0'; // 문자 형태의 숫자를 정수형으로 변환하여 저장
                        ss[idx] = 1;        // 1: 숫자(피연산자) 노드임을 표시
                    }
                }
            }

            // 모든 노드를 확인한 후 유효성 결과(K)에 따라 출력 결정
            if (K) {
                // 식 계산이 가능하면 1 출력
                System.out.println("#" + test_case + " " + 1);
            } else {
                // 계산이 불가능한 부적절한 식이면 0 출력
                System.out.println("#" + test_case + " " + 0);
            }
        }
    }
}

