/*
프로그램은 총 10개의 테스트 케이스를 수행
각 테스트 케이스에서 노드의 수를 입력받은 후, 각 노드에 대한 정보를 파싱
[계산 가능 규칙]
	노드 정보에는 노드 번호, 노드 값(연산자/숫자), 자식 노드 번호가 포함
	노드 값이 연산자인 경우 반드시 자식 노드가 있어야 함
    숫자인 경우 자식 노드가 있으면 안 됨
규칙을 위반하는 경우 해당 테스트 케이스의 결과는 0(유효하지 않음), 그렇지 않은 경우는 1(유효)로 설정한다.
*/
class Solution {
	public static void main(String args[]) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

		for(int tc = 1; tc <= 10; tc++) {
            int n = Integer.parseInt(br.readLine());
            int answer = 1; // 유효성 검사(0: 계산 불가능, 1: 계산 가능)

            for(int i = 0; i < n; i++) {
 				String[] node = br.readLine().split(" "); // 0: 노드 번호, 1: 노드 값(연산자/숫자), 2: left, 3: right

                String value = node[1];
                boolean operator = false; // 연산자인지 숫자인지 확인
                if(value.equals("+") || value.equals("-") || value.equals("*") || value.equals("/")) {
                    operator = true;
                }

                // 연산자인데 자식 노드가 2개가 아닌 경우(노드 정보는 총 4개 있어야 함)
                if(operator) {
                	if(node.length != 4) {
                        answer = 0; // 계산 불가능
                    }
                } 
                // 숫자인데 자식 노드가 존재하는 경우
                else {
                    if(node.length != 2) {
                    	answer = 0;
                    }
                }
            }
            sb.append("#").append(tc).append(" ").append(answer).append("\n");
		}
        System.out.print(sb);
	}
}

