public class SWEA1233 {
	/*
	 * 입력 처리
	 * 입력 중에 숫자가 자식 노드가 있으면 0
	 * 재귀 구성
	 * 1번 노드에서 시작
	 * 값이 숫자면 true
	 * 연산자면 재귀결과와 함께 연산
	 * 재귀 결과가 숫자가 아니면, false return
	 * 값이 존재하면, 
	 */

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		for (int i = 1; i <= 10; i++) {
			int N = Integer.parseInt(br.readLine().trim());
			char[] tree = new char[N+1];

			for (int j = 0; j < N; j++) {
				String[] s = br.readLine().split(" ");
				int idx = Integer.parseInt(s[0]);
				char var = s[1].charAt(0);
				tree[idx] = var;
			}

			boolean result = recursive(1, tree);

			StringBuilder sb = new StringBuilder();
			sb.append("#").append(i).append(" ");
			if (result) {
				sb.append(1);
			} else {
				sb.append(0);
			}
			System.out.println(sb);
		}
	}

	static boolean recursive(int i, char[] tree) {
		if (tree[i] >= '0' && tree[i] <= '9') {
			if (i*2 >= tree.length) return true;
			else return false;
		}

		else {
			if (recursive(i*2, tree) && recursive(i*2+1, tree)) {
				return true;
			} else {
				return false;
			}
		}
	}
}

