import java.io.*;
import java.util.*;

public class Swea_1233 {
	static int N;
	static String[] trie;
	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
		StringTokenizer st;
		StringBuilder sb = new StringBuilder();
//		리프노드에 무조건 피연산자가 있어야하며, 중위순회를 통해 LVR을 방문하도록 함. 자식이 있는 노드는 무조건 연산자, 자식이 없는 노드는 피연산자

//		테스트케이스 10회 반복
		for (int tc = 1; tc <= 10; tc += 1) {
//			출력형식 지정
			sb.append('#').append(tc).append(' ');

//			노드의 수에 맞게 트리 초기화
			N = Integer.parseInt(br.readLine());
			trie = new String[N];

//			입력 순서에 맞게 트리 배열에 Vertex에 해당하는 값을 저장
			for (int i = 0; i < N; i += 1) {
				st = new StringTokenizer(br.readLine());
				int v = Integer.parseInt(st.nextToken());
				trie[v - 1] = st.nextToken();
			}

//			트리를 순회하며 말단노드(리프노드 일 경우 operator가 들어가지 않고, 자식노드가 있을 경우 operand가 들어가는지 체크)
			boolean isValid = true;
			for (int i = 0; i < N; i += 1) {
				if (!checkValid(i)) {
					isValid = false;
					break;
				}
			}
//			유효한 트리일경우 1을 아닐경우 0을 출력
			sb.append(isValid ? '1' : '0').append('\n');
		}
		bw.write(sb.toString());
		bw.flush();
		bw.close();
	}

//	현재 노드 V가 유효한지 체크 (자식노드가 있을 경우[현재 인덱스의 * 2 + 1 < N] operand인지 operator인지 체크하여 true | false 반환)
//	완전이진트리이므로 우측노드만 없는 경우는 없음.
	static boolean checkValid(int i) {
		if (i * 2 + 1 < N) {
			return checkOpr(trie[i]);
		}
		else {
			return !checkOpr(trie[i]);
		}
	}

	static boolean checkOpr(String e) {
		return e.equals("+") || e.equals("-") || e.equals("*") || e.equals("/");
	}

}

