public class SERA_9229 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int T = Integer.parseInt(br.readLine());

        for (int test_case = 1; test_case < T + 1; test_case++) {

            // 공백을 기준으로 N(과자 봉지 개수)과 M(무게 제한)을 분리하여 입력
            st = new StringTokenizer(br.readLine());
            int N = Integer.parseInt(st.nextToken());
            int M = Integer.parseInt(st.nextToken());

            // 과자 봉지들의 무게를 저장할 배열을 생성
            int[] snacks = new int[N];

            // 다음 줄에서 N개의 과자 무게를 입력받아 배열에 저장
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < N; i++) {
                snacks[i] = Integer.parseInt(st.nextToken());
            }

            // 결과를 저장할 변수 / 방법이 없는 경우 -1을 출력해야 하므로 초기값은 -1
            int maxWeight = -1;

            // 정확히 M과 일치하는 최적의 조합을 찾았을 때, 반복문을 조기 탈출하기 위한 플래그 변수
            boolean flag = false;

            // 2개의 과자를 고르는 모든 조합을 확인하는 이중 반복문
            // i는 첫 번째 과자의 인덱스 (0부터 N-2까지)
            for (int i = 0; i < N - 1 && !flag; i++) {
                // j는 두 번째 과자의 인덱스 (i+1부터 N-1까지로, i와 중복되지 않게 선택)
                for (int j = i + 1; j < N && !flag; j++) {

                    // 두 과자의 무게 합
                    int k = snacks[i] + snacks[j];

                    // 만약 무게 합이 정확히 제한 무게 M과 같다면 가장 이상적인 결과
                    if (k == M) {
                        maxWeight = k;  // 최댓값을 M으로 갱신
                        flag = true;    // 더 이상 찾을 필요가 없으므로 플래그를 true로 변경하여 반복문 탈출 유도
                    }

                    // 무게 합이 제한 무게 M 이하인 경우에만 최댓값을 비교하여 갱신
                    if (k <= M) {
                        maxWeight = Math.max(maxWeight, k);
                    }
                }
            }

            // 문제에서 요구하는 출력 형식인 "#테스트케이스번호 결과값" 형태로 출력
            System.out.println("#" + test_case + " " + maxWeight);
        }
    }
}

