public class swea9229 {

	public static void main(String[] args) throws Exception {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); 
		StringBuilder sb = new StringBuilder(); 

		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {

			StringTokenizer st = new StringTokenizer(br.readLine()); 

			int N = Integer.parseInt(st.nextToken());
			int M = Integer.parseInt(st.nextToken()); 

			// two pointer 사용하기 -> 과자 무게를 리스트로 만들어주기 (인덱싱 위해) 
			int[] weights = new int[N];
			st = new StringTokenizer(br.readLine());
			for (int i = 0; i < N; i++) {
				int nextNum = Integer.parseInt(st.nextToken());
				weights[i] = nextNum; 
			}

			// 무게 오름차순 정렬 
			Arrays.sort(weights);

			// pointer 1: 시작 인덱스 
			int a = 0; 
			// pointer 2: 끝 인덱스 
			int b = N - 1; 
			// 방법 없으면 -1 출력 
			int answer = -1; 
			while(a < b) {
				int num1 = weights[a];
				int num2 = weights[b]; 

				int sum = num1 + num2; 
				// sum이 주어진것보다 더 크면 끝 인덱스를 줄이기 
				if (sum > M) {
					b--; 
				} else {
					answer = Math.max(answer, sum); // sum이 주어진것보다 작거나 같으면 후보로 두고 
					a++; // 시작 인덱스를 키워서 더 큰 수가 될 수 있는지 탐험 
				}
			}

			// sb
			sb.append("#").append(" ").append(answer).append("\n"); 
		}
		// print 
		System.out.print(sb);
	}
}

