public class Solution {
	// 과자봉지의 합을 구하기위해
	// 이분탐색 또는 양쪽에 정렬해서 탐색할 것 같다.
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine());
		for (int tc = 1; tc <= T; tc++) {
			sb.append("#").append(tc).append(" ");

			st = new StringTokenizer(br.readLine());

			int N = Integer.parseInt(st.nextToken());
			int M = Integer.parseInt(st.nextToken());
			st = new StringTokenizer(br.readLine());

			int[] arr = new int[N];

			for (int i = 0; i < N; i++) {
				arr[i] = Integer.parseInt(st.nextToken());
			}

			Arrays.sort(arr);

			int start = 0;
			int end = arr.length - 1;

			int max = -1;

			while (start < end) {

				// 들 수 없는 경우
				if (arr[start] + arr[end] > M) {
					end--;
					continue;
				}

				// 들 수 있는 경우
				if (arr[start] + arr[end] <= M) {
					max = Math.max(arr[start] + arr[end], max);
					start++;
				}

			}

			sb.append(max).append("\n");

		}
		System.out.println(sb);
	}
}

import java.util.*;
import java.io.*;

class Solution {
	static int N, M, sum; // N: 과자 개수, M: 과자 두 봉지의 최대 무게, sum: 과자 두 봉지의 무게 합산
	static int answer;
	static int[] weigh;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine());
		for (int tc = 1; tc <= T; tc++) {
			StringTokenizer st = new StringTokenizer(br.readLine());
			N = Integer.parseInt(st.nextToken());
			M = Integer.parseInt(st.nextToken());

			// 과자 봉지 무게 입력
			weigh = new int[N];
			st = new StringTokenizer(br.readLine());
			for (int i = 0; i < N; i++) {
				weigh[i] = Integer.parseInt(st.nextToken());
			}

			Arrays.sort(weigh); // 오름차순

			// 투 포인터
			int start = 0;
			int end = N - 1;
			answer = Integer.MIN_VALUE;
			sum = 0;
			// 5 10 10 16 M=20
			while (start < end) { // 인덱스가 서로 같거나 start가 end 값이 더 큰 경우에는 while문 수행 X
				sum = weigh[start] + weigh[end];

				if (sum > M) {
					end--; // sum 값이 감소되어야 하기 때문에 큰 값에서 작은 값으로 이동
				}

				else if (sum < M) {
					answer = Math.max(answer, sum); // 최댓값 갱신
					start++; // 더 탐색하기 위해 start 값 이동
				}

				else {
					answer = M;
					break;
				}
			}

			// 작은 경우에만 answer가 갱신
			// 갱신이 안됐다는 건 모든 sum 값이 M보다 컸다는 의미
			if (answer == Integer.MIN_VALUE) {
				answer = -1;
			}

			sb.append("#").append(tc).append(" ").append(answer).append("\n");
		}

		System.out.print(sb);
	}
}

