			int answer = -1;
			int left = 0;
			int right = n-1;
			while(left < right)
			{
				if(arr[left] + arr[right] <=m)
				{
					answer = Math.max(answer, arr[left]+arr[right]);
					left++;
				}

				else if(arr[left] + arr[right] > m)
				{
					right--;
				}


			}

			sb.append("#").append(tc).append(" ").append(answer).append("\n");
		}

		System.out.println(sb);
	}

}

