import java.io.*;
import java.util.*;

public class SWEA8275 {
    static int N, X, M;
    static int[][] count;
    static int[] hamsters;
    static int[] bestHamsters;
    static int maxCnt;
    static boolean flag;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int T = Integer.parseInt(br.readLine().trim());

        for(int t = 1; t <= T; t++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            N = Integer.parseInt(st.nextToken());
            X = Integer.parseInt(st.nextToken());
            M = Integer.parseInt(st.nextToken());

            count = new int[M][3];
            for(int i = 0; i < M; i++) {
                st = new StringTokenizer(br.readLine());
                count[i][0] = Integer.parseInt(st.nextToken());
                count[i][1] = Integer.parseInt(st.nextToken());
                count[i][2] = Integer.parseInt(st.nextToken());
            }

            hamsters = new int[N];
            bestHamsters = new int[N];
            maxCnt = -1;
            flag = false;

            dfs(0, 0);

            sb.append("#").append(t).append(" ");
            if(!flag) {
                sb.append(-1);
            } else {
                for(int i = 0; i < N; i++) {
                    sb.append(bestHamsters[i]).append(" ");
                }
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }

    private static void dfs(int depth, int currentSum) {
        if(depth == N) { // 마지막 우리까지 채웠으면 종료
            if(isOK()) { // 기록 충족하는지 검사
                if(currentSum > maxCnt) { // 가장 큰 햄스터 수인지 검사
                    maxCnt = currentSum;
                    flag = true;
                    for(int i = 0; i < N; i++) {
                        bestHamsters[i] = hamsters[i];
                    }
                }
            }
            return;
        }

        for(int i = 0; i <= X; i++) {
            hamsters[depth] = i;
            dfs(depth + 1, currentSum + i);
        }
    }

    private static boolean isOK() {
        for(int i = 0; i < M; i++) {
            int sum = 0;
            for(int j = count[i][0] - 1; j <= count[i][1] - 1; j++) {
                sum += hamsters[j];
            }

            if(sum != count[i][2]) {
                return false;
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class SWEA_8275 {
	// 전역 변수 설정: 재귀(dfs) 및 조건 검사(checkResearch)에서 공유하기 위함
	static int[] cage;      // 각 우리의 햄스터 마리 수를 담을 배열
	static int N;           // 햄스터 우리의 개수
	static int X;           // 한 우리에 넣을 수 있는 최대 햄스터 마리 수
	static int[][] research;// M개의 기록을 담을 배열
	static boolean K;       // 최적의 정답을 찾았는지 여부 (찾으면 즉시 모든 재귀 종료)

	public static void main(String[] args) throws IOException {
		// 빠른 입력을 위한 BufferedReader 및 StringTokenizer 설정
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine()); // 총 테스트 케이스 개수 입력

		for (int test_case = 1; test_case < T + 1; test_case++) {
			st = new StringTokenizer(br.readLine());

			// int를 제거하여 전역 변수 N, X에 값을 정확히 할당 (Shadowing 버그 해결)
			N = Integer.parseInt(st.nextToken());
			X = Integer.parseInt(st.nextToken());
			int M = Integer.parseInt(st.nextToken());

			// M개의 연구 기록 데이터 입력 처리
			research = new int[M][3];
			for (int i = 0; i < M; i++) {
				st = new StringTokenizer(br.readLine());
				research[i][0] = Integer.parseInt(st.nextToken()); // 시작 우리 번호 (1-indexed)
				research[i][1] = Integer.parseInt(st.nextToken()); // 끝 우리 번호 (1-indexed)
				research[i][2] = Integer.parseInt(st.nextToken()); // 두 우리 사이의 햄스터 합
			}

			cage = new int[N]; // 햄스터 우리 배열 공간 할당
			K = false;         // 플래그 초기화

			// 전략적 핵심: 맨 뒤쪽 우리(N-1)부터 거꾸로 채워나가는 DFS 시작
			dfs(N-1);

			// SWEA 출력 규격에 맞춘 결과 출력
			System.out.print("#" + test_case + " ");
			if (K) {
				// 역순 탐색의 특성상 K가 true가 된 순간 cage 배열 원본이 곧 최종 정답 상태입니다.
				for (int n : cage) {
					System.out.print(n + " ");
				}
				System.out.println();
			} else {
				// 만족하는 조건을 전혀 찾지 못했을 경우 -1 출력
				System.out.print(-1);
				System.out.println();
			}

		}

	}

	/**
	 * 중복 순열을 통해 햄스터를 배치하는 백트래킹 DFS 메서드
	 * @param cageNum 현재 햄스터를 배치할 우리의 인덱스
	 */
	public static void dfs(int cageNum) {
		// 기저 조건: 0번 우리까지 모두 할당을 마쳤을 때 (인덱스가 0 미만이 됨)
		if (cageNum < 0) {
			// 현재 배치 상태가 모든 연구 기록(조건)을 충족하는지 검사
			if (checkResearch()) {
				K = true;      // 찾았으므로 탈출 플래그 ON
			}
			return;
		}

		// 그리디 탐색 순서 전략: 최대 마리 수(X)부터 0마리까지 '거꾸로' 대입합니다.
		// 이로 인해 [햄스터 총합이 최대]이면서 [사전 순으로 가장 늦은] 최적 해가 무조건 '첫 번째'로 걸려들게 됩니다.
		for (int i = X; i >= 0; i--) {
			// 이미 다른 깊이의 재귀 스택에서 최적 정답을 찾았다면, 남은 루프는 전부 패스하고 종료(가지치기)
			if (K) {
				break;
			}
			cage[cageNum] = i;  // 현재 우리에 햄스터 배치
			dfs(cageNum - 1);   // 다음 앞쪽 우리를 채우러 이동

		}

	}

	/**
	 * 현재 배치된 cage 상태가 모든 연구 조건을 만족하는지 확인하는 메서드
	 * @return 모든 조건을 만족하면 true, 하나라도 틀리면 false
	 */
	public static boolean checkResearch() {
		for (int[] r : research) {
			int sum = 0;
			// 문제의 1-indexed 범위를 0-indexed로 변환하여 햄스터 수 누적
			for (int i = r[0] - 1; i < r[1]; i++) {
				sum += cage[i];
			}
			// 누적 합이 기록된 햄스터 수와 다르면 유효하지 않은 배치로 판정
			if (sum != r[2]) {
				return false;
			}

		}

		return true; // 모든 조건을 통과하면 유효한 배치
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class SWEA8275 {

	static int[][] record;
	static int[] cases;
	static int answer;
	static int caseNum;
	static int caseMaxNum;
	static int recordNum;
	static int[] answerCase;

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(in.readLine().trim());
		for (int t = 0; t < T; t++) {
			StringTokenizer st = new StringTokenizer(in.readLine().trim());

			caseNum = Integer.parseInt(st.nextToken());
			caseMaxNum = Integer.parseInt(st.nextToken());
			recordNum = Integer.parseInt(st.nextToken());

			record = new int[recordNum][3];

			for (int i = 0; i < recordNum; i++) {
				st = new StringTokenizer(in.readLine().trim());
				record[i] = new int[] { Integer.parseInt(st.nextToken()), Integer.parseInt(st.nextToken()),
						Integer.parseInt(st.nextToken()) };
			}

			cases = new int[caseNum];
			answerCase = new int[caseNum];

			for (int i = 0; i < caseNum; i++) {
				cases[i] = -1;
			}

			answer = -1;

			dfs(0);

			sb.append("#").append(t+1).append(" ");
			if(answer == -1) {
				sb.append(answer);
			} else {
				for(int i=0; i<caseNum; i++) {
					sb.append(answerCase[i]).append(" ");
				}
			}

			sb.append("\n");
		}
		System.out.println(sb);
	}

	static void dfs(int depth) {
		if(depth == caseNum) {
			// 조건 충족하는지 검사
			if(check()) {
				int newHamsterNum = 0;

				for(int i=0; i<caseNum; i++) {
					newHamsterNum += cases[i];
				}

				if(newHamsterNum > answer) {
					answer = newHamsterNum;
					for(int i=0; i<caseNum; i++) {
						answerCase[i] = cases[i];
					}
				}
			} 
			return;
		}

		for(int i=0; i<=caseMaxNum; i++) {
			cases[depth] = i;
			dfs(depth+1);
		}
	}

	static boolean check() {
		boolean isCheck = true;
		for(int[] r : record) {

			int hamsterNum = 0;

			for(int i = r[0]-1; i<r[1]; i++) {
				hamsterNum += cases[i];
			}

			if(hamsterNum != r[2]) {
				isCheck = false;
				break;
			}
		}
		return isCheck;
	}
}

import java.io.*;
import java.util.*;



public class SWEA_8275 {
	public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in)
        );

        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {

            StringTokenizer st = new StringTokenizer(br.readLine());

            int n = Integer.parseInt(st.nextToken());
            int x = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            int[][] cmd = new int[m][3];

            for (int i = 0; i < m; i++) {

                st = new StringTokenizer(br.readLine());

                cmd[i][0] = Integer.parseInt(st.nextToken()) - 1;
                cmd[i][1] = Integer.parseInt(st.nextToken()) - 1;
                cmd[i][2] = Integer.parseInt(st.nextToken());
            }

            // 각 우리가 0~X 
            int base = x + 1;

            // 전체 경우의 수 = (X+1)^N
            int totalCase = 1;

            for (int i = 0; i < n; i++) {
                totalCase *= base;
            }

            int maxSum = -1;
            int[] answer = null;

            // 0 ~ (X+1)^N - 1
            for (int state = 0; state < totalCase; state++) {

                int tmp = state;

                int[] hamster = new int[n];


                for (int i = n - 1; i >= 0; i--) {

                    hamster[i] = tmp % base;
                    tmp /= base;
                }

                // 누적합
                int[] prefix = new int[n + 1];

                for (int i = 0; i < n; i++) {
                    prefix[i + 1] = prefix[i] + hamster[i];
                }

                boolean ok = true;

                // 모든 기록 검사
                for (int[] c : cmd) {

                    int l = c[0];
                    int r = c[1];
                    int s = c[2];

                    // l ~ r 구간 합
                    int sum = prefix[r + 1] - prefix[l];

                    if (sum != s) {
                        ok = false;
                        break;
                    }
                }

                if (!ok)
                    continue;

                // 전체 햄스터 수
                int sum = prefix[n];

                /*
                 * 더 많은 햄스터가 있는 경우만 갱신
                 *
                 * sum == maxSum이면 갱신하지 않음.
                 * state를 증가시키면서 사전순으로 탐색하기 때문에
                 * 먼저 찾은 답이 사전순으로 더 앞서기 때문.
                 */
                if (sum > maxSum) {

                    maxSum = sum;
                    answer = hamster.clone();
                }
            }

            sb.append("#").append(tc).append(" ");

            if (answer == null) {
                sb.append(-1);
            } else {

                for (int v : answer) {
                    sb.append(v).append(" ");
                }
            }

            sb.append("\n");
        }

        System.out.print(sb);
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class 햄스터 {
	static int N;
	static int X;
	static int M;
	static int[][] constraints;
	static int[] cages;
	static int answer;
	static int[] answerArray;
	// 제약조건에 걸리지 않으면 최대값으로 넣을 boolean배열
	static boolean[] isConstraints;
	static boolean found;

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine());
		for (int tc = 1; tc <= T; tc++) {
			StringTokenizer st = new StringTokenizer(br.readLine());
			N = Integer.parseInt(st.nextToken());
			X = Integer.parseInt(st.nextToken());
			M = Integer.parseInt(st.nextToken());

			found = false;
			constraints = new int[M][3];
			cages = new int[N + 1];
			isConstraints = new boolean[N + 1];
			answerArray = new int[N + 1];
			answer = Integer.MIN_VALUE;

			for (int i = 0; i < M; i++) {
				st = new StringTokenizer(br.readLine());
				// 왼쪽 인덱스
				constraints[i][0] = Integer.parseInt(st.nextToken());
				// 오른쪽
				constraints[i][1] = Integer.parseInt(st.nextToken());
				// 합
				constraints[i][2] = Integer.parseInt(st.nextToken());
			}
			for (int i = 0; i < M; i++) {
				int left = constraints[i][0];
				int right = constraints[i][1];
				for (int j = left; j <= right; j++) {
					isConstraints[j] = true;
				}
			}
			// 제약조건에 걸리지 않은 우리에는 X넣기
			for (int i = 0; i < cages.length; i++) {
				if (!isConstraints[i])
					cages[i] = X;
			}
			dfs(1);
			sb.append("#").append(tc).append(" ");
			if (!found) {
				sb.append(-1);
			} else {
				for (int i = 1; i <= N; i++) {
					sb.append(answerArray[i]).append(" ");
				}
			}
			sb.append("\n");
		}
		System.out.println(sb);

	}

	// 조합으로 각 우리의 햄스터 마리수 구하기
	static void dfs(int cageNum) {

		if (cageNum == N + 1) {
			// 제약조건 전부 통과하는지 테스트
			if (checkConstraints()) {
				// 답 찾았는지 체크
				found = true;
				// 햄스터 최댓값 구하기
				int sum = 0;
				for (int i = 1; i <= N; i++) {
					sum += cages[i];
				}
				if (answer < sum) {
					answer = sum;
					for (int i = 1; i <= N; i++) {
						// 답 저장
						answerArray[i] = cages[i];
					}
				}
			}
			return;
		}

		// 제약조건에 없는 우리에는 이미 X를 넣었기 때문에 다음으로
		if (!isConstraints[cageNum]) {
			dfs(cageNum + 1);
			return;
		}

		for (int i = 0; i <= X; i++) {
			cages[cageNum] = i;
			dfs(cageNum + 1);
		}

	}

	static boolean checkConstraints() {
		for (int i = 0; i < M; i++) {
			int left = constraints[i][0];
			int right = constraints[i][1];
			int combi = constraints[i][2];

			int sum = 0;
			for (int j = left; j <= right; j++) {
				sum += cages[j];
			}

			if (sum != combi) {
				return false;
			}
		}
		return true;
	}

}

import java.io.*;
