public class SWEA5215 {
	static int[][] ings;
	static int result;
	static int L;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		int T = Integer.parseInt(br.readLine().trim());
		for(int t = 1; t <= T; t++) {
			StringTokenizer st = new StringTokenizer(br.readLine());
            int N = Integer.parseInt(st.nextToken());
            L = Integer.parseInt(st.nextToken());

            ings = new int[N][2];
            result = 0;

            for(int i = 0; i < N; i++) {
            	st = new StringTokenizer(br.readLine());
            	ings[i][0] = Integer.parseInt(st.nextToken());
            	ings[i][1] = Integer.parseInt(st.nextToken());
            }

            for(int i = 0; i < N; i++) {
            	dfs(ings[i][0], ings[i][1], i);
            }

            sb.append("#").append(t).append(" ").append(result).append("\n");			
		}
		System.out.print(sb);
	}

	private static void dfs(int score, int cal, int index) {
		 if(cal <= L) {
			 result = (result < score) ? score : result;
		 }
		 else {
			 return;
		 }

		 for(int i = index + 1; i < ings.length; i++) {
			 dfs(score + ings[i][0], cal + ings[i][1], i);
		 }
	}
}

