public class 규영이와_인영이의_카드게임 {
	static int[] gyuYoung;
	static int[] inYoung;
	static boolean[] visited;

	static int win;
	static int lose;

	public static void main(String[] args) throws IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(in.readLine());

		for (int testCase = 1; testCase <= T; testCase++) {
			gyuYoung = new int[9];
			inYoung = new int[9];

			StringTokenizer st = new StringTokenizer(in.readLine());

			// 카드 선택한지 확인하는 배열
			boolean[] selected = new boolean[19];

			// 규영이 카드 입력
			for (int i = 0; i < 9; i++) {
				gyuYoung[i] = Integer.parseInt(st.nextToken());
				selected[gyuYoung[i]] = true;
			}

			int idx = 0;
			// 인영이 카드 입력
			for (int i = 1; i <= 18; i++) {
				if (!selected[i]) {
					inYoung[idx++] = i;
				}
			}

			// 인영이의 카드 사용 여부 확인하는 배열
			visited = new boolean[9];

			win = 0;
			lose = 0;

			dfs(0, 0, 0);

			sb.append("#").append(testCase).append(" ").append(win).append(" ").append(lose).append("\n");

		}
		System.out.println(sb);
	}

	static void dfs(int gyuScore, int inScore, int depth) {
		// 9라운드 모두 진행하면 결과 갱신
		if (depth == 9) {
			// 규영이가 이김 -> win++
			if (gyuScore > inScore) {
				win++;
			}
			// 인영이가 이김 -> lose++
			else {
				lose++;
			}
			return;
		}

		for (int i = 0; i < 9; i++) {
			if (visited[i]) {
				continue;
			}

			visited[i] = true;

			int gyuCard = gyuYoung[depth];
			int inCard = inYoung[i];

			if (gyuCard > inCard) {
				dfs(gyuScore + gyuCard + inCard, inScore, depth+1);
			} else {
				dfs(gyuScore, inScore + gyuCard + inCard, depth+1);
			}

			visited[i] = false;
		}

	}
}

import java.util.*;
import java.io.*;

class SWEA_6808
{
    static int [] gyuCards;
    static int [] inCards;
    static boolean [] visited;
    static boolean [] isSelected;
    static int winCount;
    static int loseCount;


    public static void main(String args[]) throws Exception
    {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine());

        for(int test_case = 1; test_case <= T; test_case++)
        {
            StringBuilder sb = new StringBuilder();

            gyuCards = new int [9];
            inCards = new int [9];

            isSelected = new boolean[19];
            visited = new boolean[9];


            StringTokenizer st = new StringTokenizer(br.readLine());
            for(int i = 0; i < 9; i++){
                gyuCards[i] = Integer.parseInt(st.nextToken());
                isSelected[gyuCards[i]] = true;
            }

            int idx = 0;

            for(int i = 1; i <= 18; i++){
                if(!isSelected[i]){
                    inCards[idx] = i;
                    idx ++;
                }
            }

            winCount = 0;
            loseCount = 0;

            dfs(0,0,0);

            sb.append('#').append(test_case).append(' ').append(winCount).append(' ').append(loseCount);

            System.out.println(sb);


        }
    }
    private static void dfs(int depth, int gyuScore, int inScore){

        int gyuCard = 0;
        int inCard = 0;
        int sum = 0;

        if(depth == 9){
            if(gyuScore > inScore){
                winCount ++;
            }else if(gyuScore < inScore){
                loseCount ++;
            }
            return;
        }

        for(int i = 0; i < 9; i++){
            if(visited[i]){
                continue;
            }

            gyuCard = gyuCards[depth];
            inCard = inCards[i];

            sum = gyuCard + inCard;

            visited[i] = true;

            if(gyuCard > inCard){
                dfs(depth + 1, gyuScore + sum, inScore);
            }else{
                dfs(depth + 1, gyuScore, inScore + sum);
            }
            visited[i] = false;

        }

    }
}

import java.util.*;
import java.lang.*;
import java.io.*;
/*
 * 규영이와 인영이가 9장씩 카드를 나눠갖는다.
 * 둘의 카드를 비교하며 더 높은 사람이 두카드의 합 만큼 점수를 얻는다
 * 
 * 규영이가 이기는 경우와 지는 경우 몇 가지 인지 구하시오
 * 
 * 알고리즘: 순열 DFS, 백트래킹
 */
class 규영이와_인영이의_카드게임 {
	static List<Integer> number;
	static int[] ky;
	static int[] iy;
	static int[] iiy;
	static boolean[] vis;
	static int kyWin, iyWin;
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        int t = Integer.parseInt(br.readLine());

        for(int test_case=1; test_case<=t; test_case++) {        	       	
        	ky = new int[9];
        	iy = new int[9];
        	vis = new boolean[9];
        	iiy = new int[9];
        	number = new ArrayList<>();
        	for(int i=1; i<=18; i++) {
        		number.add(i);
        	}

        	st = new StringTokenizer(br.readLine());
        	for(int i=0; i<9; i++) {
        		int n = Integer.parseInt(st.nextToken());
        		ky[i] = n;
        		number.remove(Integer.valueOf(n));
        	}

        	for(int i=0; i<number.size(); i++) {
        		iy[i] = number.get(i);
        	}

        	kyWin = 0;
        	iyWin = 0;
        	dfs(0);

        	sb.append("#").append(test_case).append(" ").append(kyWin).append(" ").append(iyWin).append("\n");
        }
        System.out.print(sb);
    }

    static void dfs(int depth) {
    	if(depth >= 9) {
    		int kyScore = 0;
    		int iyScore = 0;
    		for(int i=0; i<iiy.length; i++) {
    			if(ky[i] > iiy[i]) {
    				kyScore += ky[i] + iiy[i];
    			} else if (ky[i] < iiy[i]) {
    				iyScore += ky[i] + iiy[i];
    			}
    		}

    		if(kyScore > iyScore) {
    			kyWin++;
    		} else if (kyScore < iyScore) {
    			iyWin++;
    		}
    		return;
    	}

    	for(int i=0; i<9; i++) {
    		if(vis[i]) continue;
    		vis[i] = true;
    		iiy[depth] = iy[i];
    		dfs(depth+1);
    		vis[i] = false;
    	}
    }
}

import java.io.*;
import java.util.*;

class Solution {

    static int[] gyu = new int[9];
    static boolean[] used = new boolean[19];
    static int win;

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {

            Arrays.fill(used, false);

            StringTokenizer st = new StringTokenizer(br.readLine());

            for (int i = 0; i < 9; i++) {
                gyu[i] = Integer.parseInt(st.nextToken());
                used[gyu[i]] = true;
            }

            win = 0;

            solve(0, 0, 0);

            int total = 1;
            for (int i = 1; i <= 9; i++) {
                total *= i;
            }

            sb.append("#")
              .append(tc)
              .append(" ")
              .append(win)
              .append(" ")
              .append(total - win)
              .append("\n");
        }

        System.out.print(sb);
    }

    static void solve(int cur, int gyuScore, int inScore) {

        if (cur == 9) {
            if (gyuScore > inScore) {
                win++;
            }
            return;
        }

        for (int card = 1; card <= 18; card++) {

            if (used[card])
                continue;

            used[card] = true;

            if (gyu[cur] > card) {
                solve(
                    cur + 1,
                    gyuScore + gyu[cur] + card,
                    inScore
                );
            } else {
                solve(
                    cur + 1,
                    gyuScore,
                    inScore + gyu[cur] + card
                );
            }

            used[card] = false;
        }
    }
}

import java.util.*;
import java.io.*;

class Solution {
	static int gyuWin, gyuLose;
	static int[] gyuCard; // 규영이가 갖고 있는 카드
	static int[] inCard; // 인영이가 갖고 있는 카드
	static boolean[] isVisited;

	public static void main(String args[]) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {
			StringTokenizer st = new StringTokenizer(br.readLine());

			gyuWin = 0;
			gyuLose = 0;
			isVisited = new boolean[9];
			boolean[] used = new boolean[19]; // 1부터 18까지 들어가야 하기 때문

			// 규영이가 갖고 있는 카드
			gyuCard = new int[9];
			for (int i = 0; i < 9; i++) {
				gyuCard[i] = Integer.parseInt(st.nextToken());
				used[gyuCard[i]] = true;
			}

			// 규영이 카드를 이용해서 인영이가 갖고 있는 카드 구하기
			int idx = 0;
			inCard = new int[9];
			for (int c = 1; c <= 18; c++) {
				if (!used[c]) {
					inCard[idx] = c;
					idx++;
				}
			}

			match(0, 0, 0);

			sb.append("#").append(tc).append(" ").append(gyuWin).append(" ").append(gyuLose).append("\n");
		}

		System.out.print(sb);
	}

	// gyuScore: 규영이가 낸 카드 숫자, inScore: 인영이가 낸 카드 숫자
	static void match(int gyuScore, int inScore, int round) {
		if (round == 9) {
			if (gyuScore > inScore)
				gyuWin++;
			else
				gyuLose++;

			return;
		}

		for (int i = 0; i < 9; i++) {
			if (!isVisited[i]) {
				isVisited[i] = true; // 인영이의 카드를 재사용하는 걸 방지
				int inYoung = inCard[i];
				int gyuYoung = gyuCard[round];

				// 재귀 호출
				if (gyuYoung > inYoung) {
					match(gyuScore + gyuYoung + inYoung, inScore, round + 1);
				} else {
					match(gyuScore, inScore + gyuYoung + inYoung, round + 1);
				}

				isVisited[i] = false;
			}
		}
	}
}

import java.io.*;
import java.util.*;

public class Swea_6808 {

    //  총 9장의 카드
    private static int DECK_SIZE = 9;
    // 규영이의 카드
    private static int[] deck1;
    // 인영이의 카드
    private static int[] deck2;
    // 방문 여부 체크
    private static boolean[] visited;

    private static int wins, loses;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;
        // 9장의 카드 순서가 주어질 경우 이기는 경우와 지는 경우에 대한 계산

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc += 1) {
            // 이긴 횟수와 진 횟수를 초기화
            wins = 0;
            loses = 0;

            // 규영이의 카드 저장 및 방문여부 체크
            deck1 = new int[DECK_SIZE];
            visited = new boolean[DECK_SIZE];
            st = new StringTokenizer(br.readLine());

            for (int i = 0; i < DECK_SIZE; i += 1) {
                deck1[i] = Integer.parseInt(st.nextToken());
                visited[i] = false;
            }

            // 인영이의 카드 저장
            createDeck();
            // dfs를 통해 승리와 패배를 결정
            dfs(0, 0, 0);

            // 결과 출력부
            sb.append('#').append(tc).append(' ').append(wins).append(' ').append(loses).append('\n');
        }
        bw.write(sb.toString());
        bw.flush();
        bw.close();
    }

    // 규영이에게 없는 카드를 인영이에게 전달함.
    static void createDeck() {
        deck2 = new int[DECK_SIZE];

        int num = 1;
        int size = 0;
        while (size < DECK_SIZE) {
            boolean isMatched = false;
            for (int j = 0; j < DECK_SIZE; j += 1) {
                if (deck1[j] == num) {
                    isMatched = true;
                    break;
                }
            }
            // 현재 규영이의 덱에 없는 카드라면 인영이의 카드에 저장
            if (!isMatched) {
                deck2[size] = num;
                size += 1;
            }
            num += 1;
        }
    }

    static void dfs(int idx, int score1, int score2) {
        if (idx == DECK_SIZE) {
            if (score1 > score2) {
                wins += 1;
                return;
            }
            if (score1 < score2) {
                loses += 1;
                return;
            }
            return;
        }
        int card1 = deck1[idx];

        for (int i = 0; i < DECK_SIZE; i += 1) {
            if (!visited[i]) {
                visited[i] = true;
                int card2 = deck2[i];
                if (card1 > card2) {
                    dfs(idx + 1, score1 + card1 + card2, score2);
                } else {
                    dfs(idx + 1, score1, score2 + card1 + card2);
                }
                visited[i] = false;
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class SWEA1873 {
	static final int[] dx = {0, 1, 0, -1};
	static final int[] dy = {1, 0, -1, 0};
	static final List<Character> tankChar = new ArrayList<>(Arrays.asList('>', 'v', '<', '^')); 

	static char[][] board;
	static Tank tank;
	static int H, W;

	static class Tank{
		int h, w, dir;

		Tank(int h, int w, int dir){
			this.h = h;
			this.w = w;
			this.dir = dir;
		}

		void move(int dir) {
			tank.dir = dir;

			int nh = h + dx[dir];
			int nw = w + dy[dir];

			if(!inRange(nh, nw) || board[nh][nw] != '.') {
				board[h][w] = tankChar.get(dir);
				return;
			}

			board[h][w] = '.';
			board[nh][nw] = tankChar.get(dir);

			h = nh;
			w = nw;
		}

		void shoot() {
			for(int i = 1; i <= 20; i++) {
				int nh = h + dx[dir] * i;
				int nw = w + dy[dir] * i;

				if(!inRange(nh, nw) || board[nh][nw] == '#') return;

				if(board[nh][nw] == '*') {
					board[nh][nw] = '.';
					return;
				}
			}
		}
	}

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		int T = Integer.parseInt(br.readLine().trim());
		for(int t = 1; t <= T; t++) {
			StringTokenizer st = new StringTokenizer(br.readLine());
			H = Integer.parseInt(st.nextToken());
			W = Integer.parseInt(st.nextToken());
			board = new char[H][W];
			tank = null;

			// board 입력
			for(int i = 0; i < H; i++) {
				char[] line = br.readLine().trim().toCharArray();
				for(int j = 0; j < W; j++){
					board[i][j] = line[j];

					if(tank == null && tankChar.contains(board[i][j])) {
						tank = new Tank(i, j, tankChar.indexOf(board[i][j]));
					}
				}
			}

			br.readLine(); // 명령어 길이 입력 제거
			String commands = br.readLine().trim();

			for(int i = 0; i < commands.length(); i++) {
				char command = commands.charAt(i);

				switch(command) {
				case 'U':
					tank.move(3);
					break;
				case 'D':
					tank.move(1);
					break;
				case 'L':
					tank.move(2);
					break;
				case 'R':
					tank.move(0);
					break;
				case 'S':
					tank.shoot();
					break;
				}
			}

			sb.append("#").append(t).append(" ");

			for(int i = 0; i < H; i++) {
				for(int j = 0; j < W; j++) {
					sb.append(board[i][j]);
				}
				sb.append("\n");
			}
		}
		System.out.print(sb);
	}

	private static boolean inRange(int h, int w) {
		return (h >= 0 && h < H && w >= 0 && w < W);
	}
}

