import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class SWEA_1873 {
	// 전역 변수 설정: 전차의 현재 좌표(Y, X), 맵 크기(H, W), 맵 정보(area)
	static int Y = 0;
	static int X = 0;
	static char[][] area;
	static int H;
	static int W;
	// 상(0), 하(1), 좌(2), 우(3) 방향 벡터 정의
	static int[] dy = { -1, 1, 0, 0 };
	static int[] dx = { 0, 0, -1, 1 };

	public static void main(String[] args) throws IOException {
		// 빠른 입력을 위한 BufferedReader 및 StringTokenizer 설정
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st;
		int T = Integer.parseInt(br.readLine()); // 총 테스트 케이스 개수 입력

		for (int test_case = 1; test_case < T + 1; test_case++) {
			st = new StringTokenizer(br.readLine());
			H = Integer.parseInt(st.nextToken()); // 맵의 높이(행)
			W = Integer.parseInt(st.nextToken()); // 맵의 너비(열)

			area = new char[H][W]; // 맵 공간 할당
			String str;

			// 맵 정보 입력 받기 및 전차의 초기 위치 파악
			for (int i = 0; i < H; i++) {
				str = br.readLine();
				for (int j = 0; j < W; j++) {
					area[i][j] = str.charAt(j);
					// 네 가지 방향 중 하나라면 전차의 현재 위치(Y, X)로 저장
					if (area[i][j] == '<' || area[i][j] == '>' || area[i][j] == '^' || area[i][j] == 'v') {
						Y = i;
						X = j;
					}
				}
			}

			int N = Integer.parseInt(br.readLine()); // 명령어 개수
			str = br.readLine(); // 명령어 문자열 (예: "SULURD")

			// 명령어 하나씩 순서대로 실행
			for (int i = 0; i < N; i++) {
				battleField(str.charAt(i));
			}

			// 결과 출력: 문제 요건에 맞춰 한 줄에 공백 없이 맵 상태 출력
			System.out.print("#" + test_case + " ");
			for (int i = 0; i < H; i++) {
				for (int j = 0; j < W; j++) {
					System.out.print(area[i][j]);
				}
				System.out.println(); // 한 행이 끝나면 줄바꿈
			}

		}

	}

	/**
	 * 전차의 이동 및 발사 명령을 처리하는 메서드
	 * @param command 'U', 'D', 'L', 'R' (이동) 또는 'S' (발사)
	 */
	public static void battleField(char command) {
		switch (command) {
		case 'U': // 위쪽 이동 명령어
			area[Y][X] = '^'; // 먼저 전차의 방향을 위쪽으로 전환
			// 맵 밖으로 나가거나 벽(*, #) 또는 물(-)이 있으면 이동하지 않고 종료
			if (Y - 1 < 0 || area[Y - 1][X] == '*' || area[Y - 1][X] == '#' || area[Y - 1][X] == '-') {
				break;
			}
			area[Y - 1][X] = area[Y][X]; // 다음 칸으로 전차 이동
			area[Y][X] = '.';            // 기존 칸은 평지('.')로 변경
			Y--;                         // 전차 Y좌표 갱신
			break;

		case 'D': // 아래쪽 이동 명령어
			area[Y][X] = 'v'; // 전차의 방향을 아래쪽으로 전환
			if (Y + 1 == H || area[Y + 1][X] == '*' || area[Y + 1][X] == '#' || area[Y + 1][X] == '-') {
				break;
			}
			area[Y + 1][X] = area[Y][X];
			area[Y][X] = '.';
			Y++; // 전차 Y좌표 갱신
			break;

		case 'L': // 왼쪽 이동 명령어
			area[Y][X] = '<'; // 전차의 방향을 왼쪽으로 전환
			if (X - 1 < 0 || area[Y][X - 1] == '*' || area[Y][X - 1] == '#' || area[Y][X - 1] == '-') {
				break;
			}
			area[Y][X - 1] = area[Y][X];
			area[Y][X] = '.';
			X--; // 전차 X좌표 갱신
			break;

		case 'R': // 오른쪽 이동 명령어
			area[Y][X] = '>'; // 전차의 방향을 오른쪽으로 전환
			if (X + 1 == W || area[Y][X + 1] == '*' || area[Y][X + 1] == '#' || area[Y][X + 1] == '-') {
				break;
			}
			area[Y][X + 1] = area[Y][X];
			area[Y][X] = '.';
			X++; // 전차 X좌표 갱신
			break;

		default: // 'S' (포탄 발사 명령어)
			int step;
			// 현재 전차가 바라보고 있는 방향에 따라 벡터 인덱스(step) 결정
			if (area[Y][X] == '^') {
				step = 0; // 상
			} else if (area[Y][X] == 'v') {
				step = 1; // 하
			} else if (area[Y][X] == '<') {
				step = 2; // 좌
			} else {
				step = 3; // 우
			}

			// 포탄의 시작 위치 계산 (전차 바로 앞 칸)
			int ny = Y + dy[step];
			int nx = X + dx[step];

			// 포탄이 맵 안에 있고 강철벽('#')을 만나기 전까지 직진 탐색
			while (ny >= 0 && ny < H && nx >= 0 && nx < W && area[ny][nx] != '#') {
				// 벽돌벽('*')을 만나면 벽을 무너뜨려 평지('.')로 만들고 포탄은 소멸(break)
				if (area[ny][nx] == '*') {
					area[ny][nx] = '.';
					break;
				}

				// 평지('.')나 물('-')을 만나면 아무 영향 없이 통과하므로 다음 칸으로 전진
				ny += dy[step];
				nx += dx[step];
			}

		}
	}

}

import java.util.*;
import java.io.*;

public class swea1873 {

	// 글로벌 variables 
	static int carR;
	static int carC; 

	// shoot 헬퍼 펑션 
	static void shoot(char[][] map) {

		char direction = map[carR][carC]; 

		// Up
		if (direction == '^') {
			for (int r = carR - 1; r >= 0; r--) {

				// 강철 (#)이면 더이상 못감 
				if (map[r][carC] == '#') {
					break; 
				}
				// 벽돌 (*) 이면 부시고 평지(.) 로 업데이트 
				if (map[r][carC] == '*') {
					map[r][carC] = '.'; 
					break; 
				}
			}
		}
		// Down
		if (direction == 'v') {
			for (int r = carR + 1; r < map.length; r++) {

				// 강철 (#)이면 더이상 못감 
				if (map[r][carC] == '#') {
					break; 
				}
				// 벽돌 (*) 이면 부시고 평지(.) 로 업데이트 
				if (map[r][carC] == '*') {
					map[r][carC] = '.'; 
					break; 
				}
			}
		}
        // Left 
        else if (direction == '<') {

            for (int c = carC - 1; c >= 0; c--) {

                if (map[carR][c] == '#') {
                    break;
                }

                if (map[carR][c] == '*') {
                    map[carR][c] = '.';
                    break;
                }
            }
        }
        // Right 
        else if (direction == '>') {

            for (int c = carC + 1; c < map[0].length; c++) {

                if (map[carR][c] == '#') {
                    break;
                }

                if (map[carR][c] == '*') {
                    map[carR][c] = '.';
                    break;
                }
            }
        }
	}

	public static void main(String[] args) throws Exception {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder(); 

		// 테케 
		int T = Integer.parseInt(br.readLine()); 

		for (int tc = 1; tc <= T; tc++) {
			StringTokenizer st = new StringTokenizer(br.readLine()); 

			// 게임 맵의 높이, 너비 
			int H = Integer.parseInt(st.nextToken()); 
			int W = Integer.parseInt(st.nextToken()); 

			// 게임 맵 정보 받기 
			// -> 차 위치 저장도 같이 하기 
			char[][] map = new char[H][W]; 

			for (int h = 0; h < H; h++) {
				String line = br.readLine(); 
				for (int w = 0; w < W; w++) {
					map[h][w] = line.charAt(w); 
					if (map[h][w] == '^' || map[h][w] == 'v' || map[h][w] == '<' || map[h][w] == '>') {
						carR = h;
						carC = w; 
					}
				}
			}

			// 입력 개수 N 
			int N = Integer.parseInt(br.readLine()); 

			// 길이가 N인 문자열 -> 명령어 받기 
			String commands = br.readLine();

			// 명령어 길이 만큼 돌기 
			for (int i = 0; i < N; i++) {
				char currCommand = commands.charAt(i); 

				// Up : 전차가 바라보는 방향을 위쪽으로 바꾸고, 한 칸 위의 칸이 평지라면 위 그 칸으로 이동한다.
				if (currCommand == 'U') {
					// 한 칸 위 좌표 
					int newR = carR - 1;
					int newC = carC; 

					// 방향은 이동 여부와 상관없이 먼저 갱신 
					map[carR][carC] = '^'; 

					// 한 칸 위가 지표 안에 있는지 확인
					if (newR < 0 || newR >= H) {
						continue; 
					} else {
						if (map[newR][newC] == '.') { // 평지여야만 위로 이동 
							map[newR][newC] = '^';
							map[carR][carC] = '.'; 
							// 차 위치 업데이트 
							carR = newR; 
							carC = newC; 
						}
					}

				} 
				// Down : 전차가 바라보는 방향을 아래쪽으로 바꾸고, 한 칸 아래의 칸이 평지라면 그 칸으로 이동한다.
				else if (currCommand == 'D') { 
					// 한 칸 아래 좌표 
					int newR = carR + 1;
					int newC = carC; 

					// 방향은 이동 여부와 상관없이 먼저 갱신 
					map[carR][carC] = 'v'; 

					// 한 칸 위가 지표 안에 있는지 확인 
					if (newR < 0 || newR >= H) {
						continue; 
					} else {
						if (map[newR][newC] == '.') { // 평지여야만 위로 이동 
							map[newR][newC] = 'v'; 
							map[carR][carC] = '.'; 
							// 차 위치 업데이트 
							carR = newR; 
							carC = newC; 
						}
					}

				} 
				// Left : 전차가 바라보는 방향을 왼쪽으로 바꾸고, 한 칸 왼쪽의 칸이 평지라면 그 칸으로 이동한다.
				else if (currCommand == 'L') {
					// 한 칸 왼쪽 좌표 
					int newR = carR; 
					int newC = carC - 1;

					// 방향은 이동 여부와 상관없이 먼저 갱신 
					map[carR][carC] = '<'; 

					// 한 칸 왼쪽이 지표 안에 있는지 확인 
					if (newC < 0 || newC >= W) {
						continue; 
					} else {
						if (map[newR][newC] == '.') { // 평지여야만 left로 이동 
							map[newR][newC] = '<'; 
							map[carR][carC] = '.'; 
							// 차 위치 업데이트 
							carR = newR; 
							carC = newC;
						}
					}

				} 
				// Right : 전차가 바라보는 방향을 오른쪽으로 바꾸고, 한 칸 오른쪽의 칸이 평지라면 그 칸으로 이동한다.
				else if (currCommand == 'R') {
					// 한 칸 오른쪽 좌표 
					int newR = carR;
					int newC = carC + 1;

					// 방향은 이동 여부와 상관없이 먼저 갱신 
					map[carR][carC] = '>'; 

					// 한 칸 오른쪽이 지표 안에 있는지 확인 
					if (newC < 0 || newC >= W) {
						continue; 
					} else {
						if (map[newR][newC] == '.') { // 평지여야만 right로 이동 
							map[newR][newC] = '>'; 
							map[carR][carC] = '.'; 
							// 차 위치 업데이트 
							carR = newR; 
							carC = newC; 
						}
					}

				} 
				// Shoot : 전차가 현재 바라보고 있는 방향으로 포탄을 발사한다.
				else {
					shoot(map); 
				}
			}
			// sb
			sb.append("#").append(tc).append(" ");
			for (int h = 0; h < H; h++) {
				for (int w = 0; w < W; w++) {
					sb.append(map[h][w]); 
				}
				sb.append("\n"); 
			}
		}
		// print 
		System.out.print(sb);
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class SWEA1873 {

	static char[][] map;
	static char[] command;
	// 상하좌우
	static int[] dx = {-1, 1, 0, 0};
	static int[] dy = {0, 0, -1, 1};

	static int mapR;
	static int mapC;

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(in.readLine().trim());
		for(int t=0; t<T; t++) {
			StringTokenizer st = new StringTokenizer(in.readLine().trim());

			mapR = Integer.parseInt(st.nextToken());
			mapC = Integer.parseInt(st.nextToken());

			map = new char[mapR][mapC];

			int startR = 0;
			int startC = 0;

			for(int i=0; i<mapR; i++) {
				String line = in.readLine().trim();
				for(int j=0; j<mapC; j++) {
					map[i][j] = line.charAt(j);
					if(map[i][j] == '<' || map[i][j] == '^' || map[i][j] == 'v' || map[i][j] == '>') {
						startR = i; 
						startC = j;
					}
				}
			}

			int dir = 0;

			if(map[startR][startC] == '^') {
				dir = 0;
			} else if(map[startR][startC] == 'v') {
				dir = 1;
			} else if(map[startR][startC] == '<') {
				dir = 2;
			} else if(map[startR][startC] == '>') {
				dir = 3;
			}

			int inputNum = Integer.parseInt(in.readLine().trim());

			command = new char[inputNum];

			String inputCommand = in.readLine().trim();
			for(int i=0; i<inputNum; i++) {
				command[i] = inputCommand.charAt(i);
			}

			startGame(startR, startC, dir);

			sb.append("#").append(t+1).append(" ");
			for(int i=0; i<mapR; i++) {
				for(int j=0; j<mapC; j++) {
					sb.append(map[i][j]);
				}
				sb.append("\n");
			}
		}
		System.out.println(sb);
	}

	static public void startGame(int r, int c, int dir) {
		int locationR = r;
		int locationC = c;
		int d = dir;

		for(char cm : command) {
			if(cm == 'S') { // 슈팅
				int sR = locationR;
				int sC = locationC;
				while(true) {
					sR += dx[d];
					sC += dy[d];

					if(!inRange(sR, sC)) break;
					if(map[sR][sC] == '#')break;
					if(map[sR][sC] == '*') {
						map[sR][sC] = '.';
						break;
					}
				}
			} else if(cm == 'U') { // 상
				d = 0;
				int[] location = move(locationR, locationC, d);
				locationR = location[0];
				locationC = location[1];
			} else if(cm == 'D') { // 하
				d = 1;
				int[] location = move(locationR, locationC, d);
				locationR = location[0];
				locationC = location[1];
			} else if(cm == 'L') { // 좌
				d = 2;
				int[] location = move(locationR, locationC, d);
				locationR = location[0];
				locationC = location[1];
			} else if(cm == 'R') { // 우
				d = 3;
				int[] location = move(locationR, locationC, d);
				locationR = location[0];
				locationC = location[1];
			}
		}

		if(d == 0) {
			map[locationR][locationC] = '^';
		} else if(d == 1) {
			map[locationR][locationC] = 'v';
		} else if(d == 2) {
			map[locationR][locationC] = '<';
		} else if(d == 3) {
			map[locationR][locationC] = '>';
		}
	}

	static int[] move(int r, int c, int dir) {
		int nx = r + dx[dir];
		int ny = c + dy[dir];

		if(!inRange(nx,ny)) return new int[] {r,c};

		if(map[nx][ny] == '.') {
			map[r][c] = '.';
			return new int[] {nx, ny};
		} else {
			return new int[] {r,c};
		}
	}

	static boolean inRange(int r, int c) {
		return (r>=0 && r<mapR && c>=0 && c<mapC);
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class 상호의_배틀필드 {

	// 전차 방향. 상 하 좌 우
	static int[] dr = { -1, 1, 0, 0 };
	static int[] dc = { 0, 0, -1, 1 };
	static char[] tanks = { '^', 'v', '<', '>' };

	static char[][] map;

	static int H;
	static int W;

	static int tankR;
	static int tankC;

	public static void main(String[] args) throws IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(in.readLine());

		for (int testCase = 1; testCase <= T; testCase++) {
			StringTokenizer st = new StringTokenizer(in.readLine());
			// 게임 맵 높이, 너비
			H = Integer.parseInt(st.nextToken());
			W = Integer.parseInt(st.nextToken());

			map = new char[H][W];

			// 맵 입력받음
			for (int i = 0; i < H; i++) {
				String stream = in.readLine();
				for (int j = 0; j < W; j++) {
					map[i][j] = stream.charAt(j);
					if (map[i][j] == '^' || map[i][j] == 'v' || map[i][j] == '<' || map[i][j] == '>') {
						tankR = i;
						tankC = j;
					}
				}
			}

			// 명령어 입력 N
			int N = Integer.parseInt(in.readLine());

			String orderStream = in.readLine();
			for (int i = 0; i < N; i++) {
				char order = orderStream.charAt(i);

				switch (order) {
				case 'S':
					shoot();
					break;
				case 'U':
					move(0);
					break;
				case 'D':
					move(1);
					break;
				case 'L':
					move(2);
					break;
				case 'R':
					move(3);
					break;

				}

			}
			sb.append("#").append(testCase).append(" ");

			for(int i=0 ; i<H ; i++) {
				for(int j=0 ; j<W ; j++) {
					sb.append(map[i][j]);
				}
				sb.append("\n");
			}

		}
		System.out.println(sb);
	}

	// 전차 움직이는 메서드
	static void move(int dir) {
		// 전차 방향 변경
		map[tankR][tankC] = tanks[dir];

		// 전차 이동 위치. 1칸 옮기니 dr, dc 그대로 사용
		int nextR = tankR + dr[dir];
		int nextC = tankC + dc[dir];

		// 범위 검사. 범위 밖이면 움직이지 않음. return
		if (nextR < 0 || nextR >= H || nextC < 0 || nextC >= W) {
			return;
		}

		// 평지 검사. 평지가 아니면 움직이지 않음. return
		if (map[nextR][nextC] != '.') {
			return;
		}

		// 기존 위치 평지 변환
		map[tankR][tankC] = '.';

		// 전차 위치 갱신
		map[nextR][nextC] = tanks[dir];
		tankR = nextR;
		tankC = nextC;

	}

	// 포탄 발사
	static void shoot() {
		// 현재 전차 방향 idx
		int dir = 0;
		// 현재 전차 방향 찾기
		for (int d = 0; d < 4; d++) {
			if (map[tankR][tankC] == tanks[d]) {
				dir = d;
				break;
			}
		}

		// 포탄 위치
		int nextR = tankR + dr[dir];
		int nextC = tankC + dc[dir];

		while (nextR >= 0 && nextR < H && nextC >= 0 && nextC < W) {
			// 벽돌 벽 만남. 파괴
			if (map[nextR][nextC] == '*') {
				map[nextR][nextC] = '.';
				break;
			}

			// 강철 벽 만남. 포탄 소멸
			if (map[nextR][nextC] == '#') {
				break;
			}

			nextR += dr[dir];
			nextC += dc[dir];
		}
	}

}

import java.io.*;
import java.util.*;

class Solution {

    static int H, W;

    static char[][] board;

    // 전차 위치와 방향
    static int x, y, dir;

    // 0: 상, 1: 우, 2: 하, 3: 좌
    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, 1, 0, -1};

    static char[] tank = {'^', '>', 'v', '<'};

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in)
        );

        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {

            StringTokenizer st = new StringTokenizer(br.readLine());

            H = Integer.parseInt(st.nextToken());
            W = Integer.parseInt(st.nextToken());

            board = new char[H][W];

            // 맵 입력 + 전차 위치 탐색
            for (int i = 0; i < H; i++) {

                board[i] = br.readLine().toCharArray();

                for (int j = 0; j < W; j++) {

                    if (board[i][j] == '^') {
                        x = i;
                        y = j;
                        dir = 0;
                    }
                    else if (board[i][j] == '>') {
                        x = i;
                        y = j;
                        dir = 1;
                    }
                    else if (board[i][j] == 'v') {
                        x = i;
                        y = j;
                        dir = 2;
                    }
                    else if (board[i][j] == '<') {
                        x = i;
                        y = j;
                        dir = 3;
                    }
                }
            }

            int N = Integer.parseInt(br.readLine());
            String cmd = br.readLine();

            for (int i = 0; i < N; i++) {

                char c = cmd.charAt(i);

                if (c == 'U') {
                    moveTank(0);
                }
                else if (c == 'R') {
                    moveTank(1);
                }
                else if (c == 'D') {
                    moveTank(2);
                }
                else if (c == 'L') {
                    moveTank(3);
                }
                else { // S
                    shoot();
                }
            }

            sb.append("#").append(tc).append(" ");

            for (int i = 0; i < H; i++) {
                sb.append(board[i]).append('\n');
            }
        }

        System.out.print(sb);
    }

    // 범위를 벗어났는지 검사
    static boolean OOB(int nx, int ny) {
        return nx < 0 || nx >= H || ny < 0 || ny >= W;
    }

    static void moveTank(int ndir) {

        // 1. 방향은 무조건 변경
        dir = ndir;
        board[x][y] = tank[dir];

        // 2. 한 칸 앞 위치
        int nx = x + dx[dir];
        int ny = y + dy[dir];

        // 맵 밖이면 이동 X
        if (OOB(nx, ny))
            return;

        // 평지가 아니면 이동 X
        if (board[nx][ny] != '.')
            return;

        // 3. 이동
        board[x][y] = '.';

        x = nx;
        y = ny;

        board[x][y] = tank[dir];
    }

    static void shoot() {

        int nx = x + dx[dir];
        int ny = y + dy[dir];

        // 현재 방향으로 계속 진행
        while (!OOB(nx, ny)) {

            // 벽돌벽 → 파괴 후 포탄 소멸
            if (board[nx][ny] == '*') {
                board[nx][ny] = '.';
                return;
            }

            // 강철벽 → 아무 일 없이 포탄 소멸
            if (board[nx][ny] == '#') {
                return;
            }

            // '.', '-', 전차 아래 평지 등은 통과
            nx += dx[dir];
            ny += dy[dir];
        }
    }
}

import java.io.*;
import java.util.*;

public class 상호의배틀필드 {

	static char[][] map;
	static int H;
	static int W;

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine().trim());

		for (int tc = 1; tc <= T; tc++) {
			sb.append("#").append(tc).append(" ");

			StringTokenizer st = new StringTokenizer(br.readLine());
			H = Integer.parseInt(st.nextToken());
			W = Integer.parseInt(st.nextToken());

			map = new char[H][W];
			int x = 0; 
			int y = 0;

			for (int i = 0; i < H; i++) {
				String line = br.readLine().trim();
				for (int j = 0; j < W; j++) {
					map[i][j] = line.charAt(j);
					// 전차 위치 확인(탐색 시작점)
					if (map[i][j] == '^' || map[i][j] == '<' || map[i][j] == '>' || map[i][j] == 'v') {
						x = i;
						y = j;
					}
				} // for j end
			} // for i end

			int N = Integer.parseInt(br.readLine());
			String command = br.readLine();

			// 탐색은 command 길이만큼 하면 됨, map을 직접 수정해서 전부 출력해야 됨
			// dr, dc 이용하여 탐색
			// S면 해당 방향 전부 확인해서 벽돌 벽은 부수고 강철은 변화x
			// U D L R 이면 해당 방향으로 전차 변경하고 위치 이동 '.' 인지 체크하고 이동
			for (int i = 0; i < N; i++) {
				if (command.charAt(i) == 'S') { // s면 shoot
					shoot(x, y, map[x][y]);
				} else { // 이동
					switch (command.charAt(i)) {
					case 'U': // 위로 가야된다면
						map[x][y] = '^'; // 방향 변경
						if (x - 1 >= 0) { // inRange(x - 1, y)
							if (map[x - 1][y] == '.') {// 평지여야 이동 가능
								map[x][y] = '.';
								map[--x][y] = '^';
							}
						}
						break;
					case 'D': // 현재 전차 방향 체크
						map[x][y] = 'v'; // 방향 변경
						if (x + 1 < H) { // inRange(x + 1, y)
							if (map[x + 1][y] == '.') {// 평지여야 이동 가능
								map[x][y] = '.';
								map[++x][y] = 'v';
							}
						}
						break;
					case 'L': // 현재 전차 방향 체크
						map[x][y] = '<'; // 방향 변경
						if (y - 1 >= 0) { // inRange(x, y - 1)
							if (map[x][y - 1] == '.') {// 평지여야 이동 가능
								map[x][y] = '.';
								map[x][--y] = '<';
							}
						}
						break;
					case 'R': // 현재 전차 방향 체크
						map[x][y] = '>'; // 방향 변경
						if (y + 1 < W) { // inRange(x, y + 1)
							if (map[x][y + 1] == '.') {// 평지여야 이동 가능
								map[x][y] = '.';
								map[x][++y] = '>';
							}
						}
						break;
					} // switch end
				} // else end

			} // for i end

			for (int i = 0; i < H; i++) {
				for (int j = 0; j < W; j++) {
					sb.append(map[i][j]);
				}
				sb.append("\n");
			}

		} // tc end
		System.out.print(sb);
	} // main end

	// 커맨드 S를 만나면
	// 방향에 따라 전차 다음 위치부터 맵 끝까지 포탄 날아감
	// 벽돌을 만나면 벽을 평지로 바꿈
	static void shoot(int x, int y, char direction) {
		switch (direction) {
		case '^': // 위쪽방향이면
			if (x - 1 >= 0) {
				for (int i = x - 1; i >= 0; i--) {
					if (map[i][y] == '*') {
						map[i][y] = '.';
						break;
					} else if (map[i][y] == '#') {
						break;
					}
				}
			}
			break;
		case 'v': // 아래쪽 방향이면
			if (x + 1 < H) {
				for (int i = x + 1; i < H; i++) {
					if (map[i][y] == '*') {
						map[i][y] = '.';
						break;
					} else if (map[i][y] == '#') {
						break;
					}
				}
			}
			break;
		case '<':
			if (y - 1 >= 0) {
				for (int i = y - 1; i >= 0; i--) {
					if (map[x][i] == '*') {
						map[x][i] = '.';
						break;
					} else if (map[x][i] == '#') {
						break;
					}
				}
			}
			break;
		case '>':
			if (y + 1 < W) {
				for (int i = y + 1; i < W; i++) {
					if (map[x][i] == '*') {
						map[x][i] = '.';
						break;
					} else if (map[x][i] == '#') {
						break;
					}
				}
			}
			break;
		}
	} // shoot end

} // class end

import java.io.*;
import java.util.*;

public class Swea_1873 {

    static int[] dr = { -1, 0, 1, 0 };
    static int[] dc = { 0, 1, 0, -1 };
    static char[] tank = { '^', '>', 'v', '<' };
    static int d;
    static int r;
    static int c;
    static int w;
    static int h;

    static char[][] map;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        final int T = Integer.parseInt(br.readLine());
        // 제약사항 평지 . | 물 - | 벽돌 *(파괴가능) | 강철 #
        // 입력 U D L R S

        for (int tc = 1; tc <= T; tc += 1) {
            st = new StringTokenizer(br.readLine());
            h = Integer.parseInt(st.nextToken());
            w = Integer.parseInt(st.nextToken());

            map = new char[h][w];

            for (int i = 0; i < h; i += 1) {
                String s = br.readLine();
                for (int j = 0; j < w; j += 1) {
                    map[i][j] = s.charAt(j);
                    checkPosition(map[i][j], i, j);
                }
            }

            int numberOfCommand = Integer.parseInt(br.readLine());
            String s = br.readLine();
            for (int i = 0; i < numberOfCommand; i++) {
                char c = s.charAt(i);
                if (c == 'S') {
                    fireShell();
                    continue;
                }

                moveTank(c);
            }

            sb.append('#').append(tc).append(' ');

            for (char[] row : map) {
                for (char c : row) {
                    sb.append(c);
                }
                sb.append('\n');
            }
        }
        bw.write(sb.toString());
        bw.flush();
        bw.close();
    }

    static void moveTank(char dir) {
        d = "URDL".indexOf(dir);

        int nr = dr[d] + r;
        int nc = dc[d] + c;

        if (0 <= nr && nr < h && 0 <= nc && nc < w && map[nr][nc] == '.') {
            map[r][c] = '.';
            map[nr][nc] = tank[d];
            r = nr;
            c = nc;
        } else {
            map[r][c] = tank[d];
        }
    }

    static void fireShell() {
        int nr = dr[d] + r;
        int nc = dc[d] + c;

        while (nr >= 0 && nr < h && nc >= 0 && nc < w) {
            if (map[nr][nc] == '*') {
                map[nr][nc] = '.';
                return;
            }

            if (map[nr][nc] == '#') {
                return;
            }
            nr += dr[d];
            nc += dc[d];
        }
    }

    static void checkPosition(char command, int i, int j) {
        // 스위치문 대체 방향 찾기 (어차피 상 0 | 우 1 | 하 2 | 좌 3 이기때문)
        int direction = "^>v<".indexOf(command);

        if (direction != -1) {
            d = direction;
            r = i;
            c = j;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class SWEA_3421 {
	static int N;              // 재료의 총 개수
	static int M;              // 서로 어울리지 않는 재료 쌍의 개수
	static int[][] ingredient; // 인접 행렬: 같이 넣으면 안 되는 재료 관계 저장 (1이면 궁합이 안 맞음)
	static int[] hamburger;    // 현재 만들고 있는 햄버거에 포함된 재료 상태 (1: 포함, 0: 미포함)

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine()); // 테스트 케이스 개수

		for (int test_case = 1; test_case < T + 1; test_case++) {
			st = new StringTokenizer(br.readLine());

			N = Integer.parseInt(st.nextToken());
			M = Integer.parseInt(st.nextToken());

			// 재료 번호가 1부터 N까지이므로 N+1 크기로 선언
			ingredient = new int[N + 1][N + 1];

			// 서로 궁합이 맞지 않는 재료 쌍 입력 처리
			for (int i = 0; i < M; i++) {
				st = new StringTokenizer(br.readLine());
				int a = Integer.parseInt(st.nextToken());
				int b = Integer.parseInt(st.nextToken());

				// 무향(양방향) 그래프 형태로 안 맞는 관계를 표시
				// (현재 1로 저장하여 직관성을 높이거나, 기존처럼 b와 a를 넣어도 동작합니다)
				ingredient[a][b] = 1; 
				ingredient[b][a] = 1;
			}

			hamburger = new int[N + 1]; // 햄버거 재료 선택 여부 배열 초기화

			// 1번 재료부터 탐색을 시작하여 가능한 햄버거 조합의 총 개수 출력
			System.out.println("#" + test_case + " " + dfs(1));
		}
	}

	/**
	 * 모든 재료에 대해 선택/미선택의 경우의 수를 완전 탐색하는 DFS 함수
	 * @param step 현재 고려하고 있는 재료 번호
	 * @return 가능한 햄버거 조합의 경우의 수
	 */
	public static int dfs(int step) {
		// [기저 조건] 모든 재료(1~N)에 대한 결정을 마쳤다면, 유효한 햄버거 1개를 완성한 것임
		if (step == N + 1) {
			return 1;
		}

		int totalCount = 0;

		// [선택지 1] 현재 재료(step)를 햄버거에 넣는 경우
		// (단, 기존에 고른 재료들과 궁합이 맞는지 check 함수로 검사해야 함)
		if (check(step)) {
			hamburger[step] = 1;          // 현재 재료 포함 처리
			totalCount += dfs(step + 1);  // 다음 재료 단계로 진행 및 결과 누적
			hamburger[step] = 0;          // 백트래킹: 다른 경우의 수를 위해 선택 취소 (원상복구)
		}

		// [선택지 2] 현재 재료(step)를 햄버거에 넣지 않고 넘어가는 경우
		// (이 경우는 제약 조건이 없으므로 항상 탐색이 가능함)
		totalCount += dfs(step + 1);      // 다음 재료 단계로 진행 및 결과 누적

		return totalCount; // 두 선택지에서 나온 총 경우의 수를 반환
	}

	/**
	 * 현재 재료(step)를 햄버거에 추가해도 괜찮은지 확인하는 검증 함수
	 * @param step 검사할 재료 번호
	 * @return 추가 가능하면 true, 궁합이 안 맞는 재료가 이미 들어있다면 false
	 */
	public static boolean check(int step) {
		// 1번부터 N번 재료까지 순회하며 현재 재료(step)와 맞지 않는 재료가 있는지 확인
		for (int i = 1; i <= N; i++) {
			// ingredient[step][i]가 1이고(서로 안 맞고) + i번 재료가 이미 햄버거에 들어있다면(1)
			if (ingredient[step][i] == 1 && hamburger[i] == 1) {
				return false; // 이 재료는 넣을 수 없음
			}
		}
		return true; // 아무런 문제가 없다면 넣어도 안전함
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class SWEA3421 {

	static int N;
	static int M;
	static int answer;
	static boolean[][] isUnsuitable;
	static boolean[] selected;

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(in.readLine().trim());
		for(int t=0; t<T; t++) {
			StringTokenizer st = new StringTokenizer(in.readLine().trim());
			N = Integer.parseInt(st.nextToken());
			M = Integer.parseInt(st.nextToken());

			isUnsuitable = new boolean[N+1][N+1];

			for(int i=0; i<M; i++) {
				st = new StringTokenizer(in.readLine().trim());
				int i1 = Integer.parseInt(st.nextToken());
				int i2 = Integer.parseInt(st.nextToken());
				isUnsuitable[i1][i2] = true;
				isUnsuitable[i2][i1] = true;
			}


			answer = 0;
			selected = new boolean[N+1];

			dfs(1);

			answer++;

			sb.append("#").append(t+1).append(" ").append(answer).append("\n");
		}
		System.out.println(sb);
	}

	static public void dfs(int start) {
		for(int i=start; i<=N; i++) {

			boolean possible = true;

			for(int j=1; j< i; j++) {
				if(selected[j] && isUnsuitable[j][i]) {
					possible = false;
					break;
				}
			}

			if(possible) {
				answer++;

				selected[i] = true;
				dfs(i+1);
				selected[i] = false;
			}

		}
	}

}

import java.io.*;
import java.util.*;


public class SWEA_3421 {


	static  int n,m,ans;
	static  int [][] cond ;
	public static void main(String args[]) throws Exception
	{

		Scanner sc = new Scanner(System.in);
		int T;
		T=sc.nextInt();
		StringBuilder sb =new StringBuilder();

		/*
		   여러 개의 테스트 케이스가 주어지므로, 각각을 처리합니다.
		*/

		for(int test_case = 1; test_case <= T; test_case++)
		{

			/////////////////////////////////////////////////////////////////////////////////////////////
			/*
				 이 부분에 여러분의 알고리즘 구현이 들어갑니다.

				 부분집합를 생성하고 조건 통과하면 정답 업

				 현재 원소를 부분집합에 넣을지 결정하는 함수

				 베이스 조건
				 	현재 집합이 조건 통과 안되면 종료
				 	탐색원소가 다 탐색하면 종료

				 현재 집합이 조건 통과하면 정답업
				 안되면 종료




			 */


			n =sc.nextInt();
			m  = sc.nextInt();
			ans=0;
			cond = new int[m][];
			for(int i=0; i<m; i++) {
				cond[i] = new int[2];
				cond[i][0] = sc.nextInt()-1;
				cond[i][1] = sc.nextInt()-1;
			}

			//집합 생성후 체크
			solve(0,0);
			sb.append("#").append(test_case).append(" ").append(ans).append("\n");
			/////////////////////////////////////////////////////////////////////////////////////////////

		}
		System.out.println(sb);
	}

	// 현재 탐색 원소 비트 cur, 선택 비트 flag
	static void solve(int cur, int flag) {
		if(cur == n) {
			if(makeHam(flag)) {
				ans++;

			}


			return ;
		}
		solve(cur+1,flag);
		solve(cur+1,flag | (1<<cur));

	}


	static boolean makeHam(int flag) {
		for(int i=0; i<m; i++) {

			if(((flag & (1<<cond[i][0]))!=0) && ((flag & (1<<cond[i][1]))!=0))
				return false;
		}
		return true;
	}
}

import java.util.*;
import java.io.*;

public class swea3421 {

	// 글로벌 
	static int N;
	static int M; 
	static int answer; 
	static boolean[][] conflict;

	// dfs
	// index -> 현 재료 숫자 
	static void dfs(int index, boolean[] selected) {
		if (index > N) {
			// 빈 집합 포함 OR 유효한 조합 하나 발견 
			answer++;
			return; 
		}

		// index번 재료를 제외하는 경우 
		dfs(index + 1, selected); 

		// index번 재료를 "포함"하는 경우 -> 이미 선택된 재료들과 궁합 확인 
		boolean ok = true; 
		for (int j = 1; j < index; j++) {
			if (selected[j] && conflict[index][j]) {
				ok = false; 
				break; 
			}
		}
		if (ok) {
			selected[index] = true; 
			dfs(index + 1, selected); 
			selected[index] = false; 
		}
	}

	public static void main(String[] args) throws Exception {

		BufferedReader br  = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder(); 

		// 테케 수 
		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {
			// N, M 
			// N = 재료 수 
			// M = 궁합 안맍는 페어 수 
			StringTokenizer st = new StringTokenizer(br.readLine()); 

			N = Integer.parseInt(st.nextToken()); 
			M = Integer.parseInt(st.nextToken()); 

			// conflict -> 궁합 안맞는 것들 
			// N + 1 -> 재료 실제 숫자로 받을거라 이렇게 됨 
			conflict = new boolean[N + 1][N + 1]; 

			// 페어 하나씩 읽어드리며 conflict table 만들기 
			for (int m = 0; m < M; m++) {
				st = new StringTokenizer(br.readLine()); 

				// i, j 
				int i = Integer.parseInt(st.nextToken());
				int j = Integer.parseInt(st.nextToken()); 

				conflict[i][j] = true;
				conflict[j][i] = true; 
			}

			answer =0; 
			// dfs(index, boolean[] selected) 
			dfs(1, new boolean[N+1]); 

			// sb 
			sb.append("#").append(tc).append(" ").append(answer).append("\n"); 
		}
		// print 
		System.out.print(sb);
	}
}

