public class 수제_버거_장인 {

	static int N, M;

	static boolean[][] cantMake;

	static boolean[] visited;

	static int count;

	public static void main(String[] args) throws IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(in.readLine());

		for (int testCase = 1; testCase <= T; testCase++) {
			StringTokenizer st = new StringTokenizer(in.readLine());
			N = Integer.parseInt(st.nextToken());
			M = Integer.parseInt(st.nextToken());

			visited = new boolean[N + 1];
			cantMake = new boolean[N + 1][N + 1];

			for (int i = 0; i < M; i++) {
				st = new StringTokenizer(in.readLine());
				int a = Integer.parseInt(st.nextToken());
				int b = Integer.parseInt(st.nextToken());

				cantMake[a][b] = true;
				cantMake[b][a] = true;
			}

			count = 0;
			dfs(1);

			sb.append("#").append(testCase).append(" ").append(count).append("\n");
		}
		System.out.println(sb);
	}

	static void dfs(int materialIdx) {
		// 모든 재료를 확인해서 조합 완성
		if (materialIdx > N) {
			count++;
			return;
		}

		// 1. 현재 재료를 선택 X. 다음 재료 선택
		dfs(materialIdx + 1);

		// 2. 현재 재료 선택
		boolean canSelect = true;

		for (int i = 1; i <= N; i++) {
			// 궁합이 맞는지 확인. 이미 선택한 재료거나 궁합 안맞으면 만들 수 X
			if (visited[i] && cantMake[materialIdx][i]) {
				canSelect = false;
				break;
			}
		}

		// 이 재료로 만들 수 있다면
		if (canSelect) {
			visited[materialIdx] = true;
			dfs(materialIdx + 1);
			// 백트래킹
			visited[materialIdx] = false;
		}

	}

}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map.Entry;
import java.util.StringTokenizer;

public class Solution {
	/*
	 * 수제버거 장인 사용하는 재료는 1~N번까지 (1 based) 어울리지 않는 재료들은 포함하지 않고 버거 만들기 입력은 어울리지 않는
	 * 재료조합 + 버거가 정확하게 같은 버거라면 같은 버거로 본다 (set?) 제약조건을 만족하며 만들 수 있는 버거의 가짓수 N: 사용할 수
	 * 있는 버거재료 M : 버거 조합 수
	 * 
	 * N은 1부터 20 , M은 400 + {} 과같은 재료를 아무것도 안넣는 조합도 가능
	 * 
	 * step1 : map또는 이차원 배열을 이용한 재료배열 초기화 step2 : 조합을 만드는데, [1,3,2] . [1,2,3]을 같은
	 * 케이스로 본다. step3 : 최대 조합수는 NC1, NC2, NC3,... (재료를 두개만 고르는듯)
	 */
	static int[] ham;
	static HashMap<Integer, ArrayList<Integer>> map;
	static int N;
	static boolean[] isSelected;
	static int total;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine());
		for (int tc = 1; tc <= T; tc++) {
			sb.append("#").append(tc).append(" ");
			st = new StringTokenizer(br.readLine());
			N = Integer.parseInt(st.nextToken());
			isSelected = new boolean[N + 1];
			int M = Integer.parseInt(st.nextToken());
			total = 0;

			ham = new int[N];
			map = new HashMap<>();

			for (int i = 0; i < M; i++) {
				st = new StringTokenizer(br.readLine());
				int a = Integer.parseInt(st.nextToken());
				int b = Integer.parseInt(st.nextToken());

				if (!map.containsKey(a))
					map.put(a, new ArrayList<>());
				if (!map.containsKey(b))
					map.put(b, new ArrayList<>());

				map.get(a).add(b);
				map.get(b).add(a);

			}

			// for문을 통해 가능한 만큼 combination을 얻어낸다.
			// 공집합은 마지막에 한번 더해주기
			for (int i = 1; i <= N; i++) {
				combination(0, i, 1);
			}

			// 결과에 1(공집합을 더한다)
			// set에 넣는다.
			sb.append(total + 1).append("\n");
		}

		System.out.println(sb);
	}

	// 중복을 허용하지 않는 조합을 만드는 함수
	// 개수를 만족하면 조건을 검사하고 만족하면 set에 추가
	static void combination(int cnt, int target, int start) {
		// base 조건,
		if (cnt == target) { // 검사하기
			// 햄버거 재료만큼 돌기
			total += 1;
			return;
		}

		// 햄버거에 재료 추가하기
		for (int i = start; i <= N; i++) {
			if(!isOk(i)) continue;
			ham[cnt] = i;
			isSelected[i] = true;
			combination(cnt + 1, target, i + 1);
			isSelected[i] = false;
		}
	}

	static boolean isOk(int tomato) {

		if (!map.containsKey(tomato)) return true;

		// 재료를 돌면서 궁합 안맞는게 있나 탐색
		for (int m : map.get(tomato)) {
			if (isSelected[m])
				return false;
		}
		return true;
	}
}

import java.io.*;
import java.util.*;

public class SWEA3421 {
	static int N, M;
	static List<Integer>[] bans;
	static List<Integer> curr;
	static int result;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		int T = Integer.parseInt(br.readLine().trim());
		for(int t = 1; t <= T; t++) {
			StringTokenizer st = new StringTokenizer(br.readLine().trim());
			N = Integer.parseInt(st.nextToken());
			M = Integer.parseInt(st.nextToken());
			result = 0;
			curr = new ArrayList<>();

			bans = new List[N + 1];
			for(int i = 1; i <= N; i++) {
				bans[i] = new ArrayList<>();
			}
			for(int i = 0; i < M; i++) {
				st = new StringTokenizer(br.readLine().trim());
				int a = Integer.parseInt(st.nextToken());
				int b = Integer.parseInt(st.nextToken());

				bans[a].add(b);
				bans[b].add(a);
			}

			dfs(1);

			sb.append("#").append(t).append(" ").append(result).append("\n");
		}
		System.out.print(sb);
	}

	private static void dfs(int idx) {
		if(idx == N + 1) {
			result++;
			return;
		}

		boolean flag = false;
		for(int b : bans[idx]) {
			if(curr.contains(b)) {
				flag = true;
				break;
			}
		}

		// 다음 재료와 어울리지 않는 재료가 이미 포함되어 있으면 스킵
		if(flag) {
			dfs(idx + 1);
		}
		else {
			dfs(idx + 1); 
			// 다음 재료 넣고 재귀호출		
			curr.add(idx);
			dfs(idx + 1);
			curr.remove(curr.size() - 1);
		}
	}
}

/*
 * 1번부터 N번까지의 재료들이 있는데 서로 어울리는 재료들만이 햄버거를 만들 수 있다.
 * 궁합이 맞지 않는 재료들로 M개쌍에 대한 정보가 주어졌을 때 만들 수 있는 버거의 종류를 출력
 * -----------------------------------------------------------------
 * 궁합이 맞는 여부를 2차원 배열로 생성하여 맞은 경우 False, 맞지 않은 경우 True로 설정
 * 
 * comb[][] 배열에 재료 간 궁합 여부를 저장
 * 	a와 b는 같이 사용하면 안되기 때문에 [a][b]와 [b][a]에 false 저장
 * 1번부터 N번 재료까지 선택/미선택으로 나눠 dfs 진행
 * 	선택할 경우, 선택 여부와 조합 여부 검사
 * 	아직 선택하지 않고, 맞은 조합일 경우 dfs(makeHam) 호출
 * 
 * */

import java.util.*;
import java.io.*;

class Solution {
	static int N, M; // N: 재료 수, M: 궁합이 맞지 않는 재료 조합 수
	static int ans; // 만들 수 있는 버거의 가짓수

	static boolean[] visited; // 선택된 재료 여부
	static boolean[][] comb; // 궁합 여부(False: 맞지 않음, True: 맞음)

	public static void main(String args[]) throws Exception {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {
			StringTokenizer st = new StringTokenizer(br.readLine());
			N = Integer.parseInt(st.nextToken());
			M = Integer.parseInt(st.nextToken());
			ans = 0;
			visited = new boolean[N + 1];

			// 모든 재료의 궁합은 맞는 것으로 초기화
			comb = new boolean[N + 1][N + 1];
			for (int i = 0; i <= N; i++) {
				Arrays.fill(comb[i], true);
			}

			// 궁합이 맞지 않는 재료 쌍 입력
			for (int i = 0; i < M; i++) {
				st = new StringTokenizer(br.readLine());

				int a = Integer.parseInt(st.nextToken());
				int b = Integer.parseInt(st.nextToken());

				comb[a][b] = false; // 궁합이 맞지 않음 표시
				comb[b][a] = false; // 중복된 재료 조합도 false 표시
			}

			// 1번부터 재료 탐색
			makeHam(1);

			sb.append("#").append(tc).append(" ").append(ans).append("\n");
		}

		System.out.print(sb);
	}

	// 1번 재료부터 출발해 다음 재료를 고를 때
	static void makeHam(int idx) {
		if (idx > N) {
			ans++;
			return;
		}

		// idx번 재료를 선택하지 않는 경우
		makeHam(idx + 1);

		// idx번 재료를 선택하는 경우
		boolean select = true;

		for (int i = 1; i < idx; i++) {
			// i번 재료가 이미 선택되어 있고 idx번 재료와 궁합이 맞지 않는 경우
			if (visited[i] && !comb[idx][i]) {
				select = false;
				break;
			}
		}

		if (select) {
			visited[idx] = true; // 현재 재료 선택
			makeHam(idx + 1); // 다음 재료 선택
			visited[idx] = false; // 다음 탐색을 위해 복구
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class swea3421 {
	static int n,m;
	static int [][]m_list = new int[400][2];
	static boolean [] is_used = new boolean[21];
	static int answer = 0;

	public static void main(String[] args) throws IOException{
		// TODO Auto-generated method stub
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;
		int t = Integer.parseInt(br.readLine());
		for(int tc = 1; tc<=t; tc++)
		{
			Arrays.fill(is_used, false);
			answer = 0;
			st = new StringTokenizer(br.readLine());
			n = Integer.parseInt(st.nextToken());
			m = Integer.parseInt(st.nextToken());
			for(int i=0;i<m;i++)
			{
				st = new StringTokenizer(br.readLine());
				m_list[i][0] = Integer.parseInt(st.nextToken());
				m_list[i][1] = Integer.parseInt(st.nextToken());
			}

			solution(0,false);
			sb.append("#").append(tc).append(" ").append(answer).append("\n");
		}
		System.out.println(sb);
	}

	static void solution(int k, boolean flag)
	{
		if(flag && !check())
			return;
		if(k==n)
		{
			answer++;
			return;
		}

		is_used[k+1] = true;
		solution(k+1,true);
		is_used[k+1] = false;
		solution(k+1,false);
	}

	static boolean check()
	{
		for(int i=0;i<m;i++)
		{
			int [] arr = m_list[i];
			if(is_used[arr[0]] && is_used[arr[1]])
			{
				return false;
			}
		}
		return true;
	}

}

