//  메모리: 30,924 kb / 실행 시간: 99 ms
	private static void dfs(int start, int cantSelect) {
	    answer++;

	    for (int i = start; i <= N; i++) {
	        // 이번 숫자를 고를 수 없으면 패스
	        if ((cantSelect & (1 << i)) != 0) continue;


	        int nextCant = cantSelect;
	        for (int cant : graph[i]) {
	            nextCant |= (1 << cant);
	        }

	        dfs(i + 1, nextCant);
	    }
	}

