public class Swea_3421 {

    static int[][] badIngredient;
    static boolean[] selected;
    static int n;
    static int m;
    static int res;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        final int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc += 1) {
            st = new StringTokenizer(br.readLine());
            res = 0;
            n = Integer.parseInt(st.nextToken());
            m = Integer.parseInt(st.nextToken());
            selected = new boolean[n];

            badIngredient = new int[m][2];
            for (int i = 0; i < m; i += 1) {
                st = new StringTokenizer(br.readLine());
                for (int j = 0; j < 2; j += 1) {
                    badIngredient[i][j] = Integer.parseInt(st.nextToken());
                }
            }
            dfs(0);
            sb.append('#').append(tc).append(' ').append(res).append('\n');
        }
        bw.write(sb.toString());
        bw.flush();
        bw.close();
    }

    static void dfs(int idx) {
        if (idx == n) {
            for (int[] bads : badIngredient) {
                if (selected[bads[0] - 1] && selected[bads[1] - 1]) {
                    return;
                }
            }

            res += 1;
            return;
        }

        selected[idx] = false;
        dfs(idx + 1);

        selected[idx] = true;
        dfs(idx + 1);
    }
}

import java.io.*;
import java.util.*;

public class SWEA1767 {
	static int[] dx = {-1, 1, 0, 0};
	static int[] dy = {0, 0, -1, 1};
	static int[][] board;
	static int result;
	static int lineCnt;
	static int completeResult;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine());

		for(int t = 1; t <= T; t++) {
			int N = Integer.parseInt(br.readLine());
			board = new int[N][N];
			result = Integer.MAX_VALUE;
			completeResult = 0; // 전선 수가 result였을 때 연결 완료된 코어의 개수
			lineCnt = 0; // 현재 전선 수
			List<int[]> cores = new ArrayList<>();

			for(int i = 0; i < N; i++) {
				StringTokenizer st = new StringTokenizer(br.readLine());
				for(int j = 0; j < N; j++) {
					board[i][j] = Integer.parseInt(st.nextToken());

					if(board[i][j] == 1) {
						// 코어가 가장자리에 있으면 cores에 아예 추가하지 않음
						// 가장자리의 코어는 장애물 역할 말고는 아예 영향 없음
						if(i == 0 && i == N - 1 && j == 0 && j == N - 1) continue;
						cores.add(new int[] {i, j});
					}
				}
			}

			backtrack(0, cores, 0);

			sb.append("#").append(t).append(" ").append(result).append("\n");
		}

		System.out.print(sb);
	}

	// 현재 {x, y} 에서 direction 방향으로 뻗었을 때 전력이 연결될 수 있는지 여부를 반환
	private static boolean canConnect(int x, int y, int direction) {
		boolean result = true;

		for(int i = 1; i < board.length; i++) {
			int nx = x + dx[direction] * i;
			int ny = y + dy[direction] * i;

			if(nx < 0 || nx >= board.length || ny < 0 || ny >= board.length) {
				break;
			}

			if(board[nx][ny] != 0) {
				result = false;
				break;
			}
		}

		return result;
	}

	// canConnect가 true면 해당 입력대로 실제로 board를 수정
	private static int connect(int x, int y, int direction) {
		int count = 0;

		for(int i = 1; i < board.length; i++) {
			int nx = x + dx[direction] * i;
			int ny = y + dy[direction] * i;

			if(nx < 0 || nx >= board.length || ny < 0 || ny >= board.length) {
				break;
			}

			board[nx][ny] = 2;
			count++;
		}

		return count;
	}

	// 백트래킹 depth 1 추가 이후 원상태로 되돌리기
	private static void unconnect(int x, int y, int direction, int length) {
		for(int i = 1; i <= length; i++) {
			int nx = x + dx[direction] * i;
			int ny = y + dy[direction] * i;

			board[nx][ny] = 0;
		}
	}

	private static void backtrack(int i, List<int[]> cores, int completeCnt) {
		// 종료 조건 : 마지막 코어까지 다 방문 완료
		if(i == cores.size()) {
			// 전원 연결된 코어 개수가 더 많으면 전선 수와 상관없이 갱신
			if(completeResult < completeCnt) {
				completeResult = completeCnt;
				result = lineCnt;
			}
			// 전원 연결된 코어 개수가 같으면 전선 수가 더 작은 쪽으로 갱신
			else if(completeResult == completeCnt) {
				result = Math.min(result, lineCnt);
			}
			return;
		}

		int[] core = cores.get(i);
		int x = core[0];
		int y = core[1];

		if(x == 0 || y == 0 || x == board.length - 1 || y == board.length - 1) {
			backtrack(i + 1, cores, completeCnt + 1);
			return;
		}

		// 현재 코어에서 4방향 탐사
		for(int j = 0; j < 4; j++) {
			// 만약 해당 방향으로 전선 뻗었을 때 전원 연결이 가능하면
			if(canConnect(x, y, j)) {
				// 전원 연결하고 전선 개수만큼 lineCnt 증가
				int len = connect(x, y, j);
				lineCnt += len;

				// 백트래킹 깊이 1 더 들어가기
				backtrack(i + 1, cores, completeCnt + 1);

				// 연결했던 전선을 다시 0으로 돌리고 lineCnt 감소
				lineCnt -= len;
				unconnect(x, y, j, len);
			}
		}

		// * 연결하지 않고 넘어가기 로직 추가
		backtrack(i + 1, cores, completeCnt);
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class SWEA_1767 {
	static int N;                         // 멕시노스 칩의 크기 (N x N)
	static ArrayList<int[]> processor;    // 전선 연결이 필요한 코어(1)들의 좌표를 담을 리스트
	static int[][] area;                  // 멕시노스 칩의 상태를 저장할 2차원 배열 (0: 빈칸, 1: 코어, 2: 전선)
	static int[] dy = { 1, -1, 0, 0 };    // 하, 상, 우, 좌 방향 탐색을 위한 y축 변화량
	static int[] dx = { 0, 0, 1, -1 };    // 하, 상, 우, 좌 방향 탐색을 위한 x축 변화량
	static int minLength;                 // 코어들을 최대로 연결했을 때의 최소 전선 길이 합
	static int maxConnect;                // 최대한으로 연결한 코어의 개수

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine()); // 총 테스트 케이스 개수 입력

		for (int test_case = 1; test_case < T + 1; test_case++) {

			N = Integer.parseInt(br.readLine());
			area = new int[N][N];
			processor = new ArrayList();
			minLength = Integer.MAX_VALUE; // 최소 길이를 구해야 하므로 가장 큰 값으로 초기화
			maxConnect = 0;                // 최대 연결 개수를 구해야 하므로 0으로 초기화

			// 멕시노스 칩 초기 상태 입력받기
			for (int i = 0; i < N; i++) {
				st = new StringTokenizer(br.readLine());
				for (int j = 0; j < N; j++) {
					int n = Integer.parseInt(st.nextToken());
					area[i][j] = n;

					// 코어(1) 발견 시 처리
					if (n == 1) {
						// 가장자리(벽)에 이미 붙어있는 코어는 전선 연결이 필요 없으므로 제외
						if (!(i == 0 || i == N - 1 || j == 0 || j == N - 1)) {
							processor.add(new int[] { i, j }); // 전선 연결이 필요한 코어만 리스트에 추가
						}
					}
				}
			}

			// DFS 탐색 시작 (현재 전선 길이: 0, 확인할 코어 인덱스: 0, 연결된 코어 개수: 0)
			dfs(0, 0, 0);

			// 결과 출력
			System.out.println("#" + test_case + " " + minLength);
		}

	}

	/**
	 * 백트래킹을 이용한 전선 연결 완전탐색 (DFS)
	 * @param minSize           현재까지 설치된 총 전선의 길이
	 * @param coreIndex         현재 탐색 중인 코어의 인덱스
	 * @param connectCoreCount  현재까지 연결에 성공한 코어의 개수
	 */
	public static void dfs(int minSize, int coreIndex, int connectCoreCount) {

		// 기저 조건: 리스트에 존재하는 모든 코어의 방향 설정을 끝마쳤을 때
		if (coreIndex == processor.size()) {
			// 1. 현재 조합이 기존보다 코어를 더 많이 연결한 경우 -> 최댓값과 전선 길이 갱신
			if (connectCoreCount > maxConnect) {
				maxConnect = connectCoreCount;
				minLength = minSize;
			} 
			// 2. 연결한 코어 수가 기존 최댓값과 같은 경우 -> 전선 길이가 더 짧은 쪽으로 갱신
			else if (connectCoreCount == maxConnect) {
				minLength = Math.min(minLength, minSize);
			}
			return; // 탐색 종료 및 이전 분기로 리턴
		}

		// 현재 확인할 코어의 좌표 가져오기
		int[] core = processor.get(coreIndex);
		int y = core[0];
		int x = core[1];

		int count; // 현재 방향으로 전선을 놓을 때 필요한 전선의 길이를 셀 변수

		// 4방향(하, 상, 우, 좌)으로 전선 연결 시도
		for (int i = 0; i < 4; i++) {
			int ny = y;
			int nx = x;
			count = 0;
			boolean canConnect = true; // 벽까지 무사히 도달할 수 있는지 여부 플래그

			// 선택한 방향으로 벽을 만날 때까지 직진하며 전선 배치
			while (true) {
				ny += dy[i];
				nx += dx[i];

				// 범위를 벗어났다 = 칩의 가장자리(벽)에 무사히 도달했다는 뜻
				if (ny < 0 || ny == N || nx < 0 || nx == N) {
					break;
				}

				// 전선을 놓으려는 길에 다른 코어(1)나 이미 설치된 전선(2)이 있으면 연결 불가
				if (area[ny][nx] == 2 || area[ny][nx] == 1) {
					canConnect = false; // 연결 불가 플래그 설정
					break;
				}

				// 전선을 놓을 수 있는 빈칸(0)인 경우
				count++;            // 전선 길이 증가
				area[ny][nx] = 2;   // 칩에 전선(2) 표시하기

			}

			// 벽까지 가로막는 것 없이 무사히 연결된 경우에만 다음 코어로 진행
			if (canConnect) {
				// 전선 길이 추가, 다음 코어 인덱스, 연결된 코어 수 + 1
				dfs(minSize + count, coreIndex + 1, connectCoreCount + 1);
			}

			// 백트래킹(원상복구): 이번 방향으로 시도하며 설치했던 전선들을 다시 빈칸(0)으로 되돌림
			// (연결에 성공했든 실패했든 다음 방향이나 다른 코어 조합을 시험하기 위해 칩을 깨끗하게 복원해야 함)
			for (int k = 0; k < count; k++) {
				ny -= dy[i];
				nx -= dx[i];
				area[ny][nx] = 0;
			}

		}

		// [선택지 추가] 현재 코어를 사방 어디로도 연결하지 않고 그냥 패스하는 경우
		// (다른 코어들의 연결을 위해 현재 코어를 포기하는 것이 이득일 수 있으므로 이 분기도 탐색해야 함)
		dfs(minSize, coreIndex + 1, connectCoreCount);

	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class SWEA1767 {

	static int N;
	static int[][] map;
	static boolean[][] visited;
	static int answer;
	static List<Core> cores;
	static int maxLinkedCore;

	// 우 하 좌 상
	static int[] dx = { 0, 1, 0, -1 };
	static int[] dy = { 1, 0, -1, 0 };

	static class Core {
		int r;
		int c;

		public Core(int r, int c) {
			this.r = r;
			this.c = c;
		}
	}

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(in.readLine().trim());
		for (int t = 0; t < T; t++) {
			N = Integer.parseInt(in.readLine().trim());

			map = new int[N][N];
			visited = new boolean[N][N];
			cores = new ArrayList<>();
			maxLinkedCore = 0;
			answer = 0;

			StringTokenizer st;

			for (int i = 0; i < N; i++) {
				st = new StringTokenizer(in.readLine().trim());
				for (int j = 0; j < N; j++) {
					map[i][j] = Integer.parseInt(st.nextToken());
					if (i > 0 && i < N - 1 && j > 0 && j < N - 1) {
						if (map[i][j] == 1) {
							cores.add(new Core(i, j));
						}
					}
				}
			}

			dfs(0, 0, 0);

			sb.append("#").append(t + 1).append(" ").append(answer).append("\n");
		}
		System.out.println(sb);
	}

	static public void dfs(int depth, int linkedNum, int wire) {

		if (depth == cores.size()) {
			if (maxLinkedCore < linkedNum) {
				maxLinkedCore = linkedNum;
				answer = wire;
			} else if (maxLinkedCore == linkedNum) {
				if (answer > wire)
					answer = wire;
			}
			return;
		}

		Core core = cores.get(depth);

		dfs(depth + 1, linkedNum, wire);

		for (int j = 0; j < 4; j++) {
			int nr = core.r;
			int nc = core.c;
			boolean isConnected = false;
			int wireNum = 0;
			while (true) {
				nr += dx[j];
				nc += dy[j];

				if (!inRange(nr, nc)) {
					isConnected = true;
					break;
				}

				if (visited[nr][nc])
					break;

				if (map[nr][nc] == 1)
					break;

				visited[nr][nc] = true;

				wireNum++;
			}

			if (isConnected) {
				dfs(depth + 1, linkedNum + 1, wire + wireNum);
			}

			int rr = core.r;
			int rc = core.c;
			for(int k=0; k<wireNum; k++) {
				rr += dx[j];
				rc += dy[j];

				visited[rr][rc] = false;
			}
		}

	}

	static public boolean inRange(int r, int c) {
		return (r >= 0 && r < N && c >= 0 && c < N);
	}
}

import java.io.*;
import java.util.*;

public class Solution {

    static int N;
    static int coreCnt;

    static int[][] board;

    static int[] dx = {1, 0, -1, 0};
    static int[] dy = {0, 1, 0, -1};

    // 연결된 코어의 최대 개수
    static int maxCore;

    // maxCore일 때 최소 전선 길이
    static int minWire;

    static List<int[]> cores = new ArrayList<>();

    /*
     * 현재 코어에서 d 방향으로 전선을 연결할 수 있는지 확인
     */
    static boolean isConnectable(int x, int y, int d) {

        int nx = x + dx[d];
        int ny = y + dy[d];

        while (nx >= 0 && nx < N && ny >= 0 && ny < N) {

            // 코어(1) 또는 이미 설치된 전선(2)이 존재
            if (board[nx][ny] != 0) {
                return false;
            }

            nx += dx[d];
            ny += dy[d];
        }

        return true;
    }

    /*
     * 실제 전선 설치
     * 설치한 전선 길이를 반환
     */
    static int connect(int x, int y, int d) {

        int cnt = 0;

        int nx = x + dx[d];
        int ny = y + dy[d];

        while (nx >= 0 && nx < N && ny >= 0 && ny < N) {

            board[nx][ny] = 2;
            cnt++;

            nx += dx[d];
            ny += dy[d];
        }

        return cnt;
    }

    /*
     * 설치했던 전선 제거
     */
    static void disconnect(int x, int y, int d) {

        int nx = x + dx[d];
        int ny = y + dy[d];

        while (nx >= 0 && nx < N && ny >= 0 && ny < N) {

            board[nx][ny] = 0;

            nx += dx[d];
            ny += dy[d];
        }
    }

    /*
     * idx     : 현재 결정할 코어 번호
     * cntCore : 지금까지 전원에 연결한 코어 개수
     * wireLen : 지금까지 사용한 전선 길이
     */
    static void solve(int idx, int cntCore, int wireLen) {

        // 모든 코어에 대해 선택 완료
        if (idx == coreCnt) {

            if (cntCore > maxCore) {
                maxCore = cntCore;
                minWire = wireLen;
            } else if (cntCore == maxCore) {
                minWire = Math.min(minWire, wireLen);
            }

            return;
        }

        int x = cores.get(idx)[0];
        int y = cores.get(idx)[1];

        /*
         * 현재 코어를 4방향 중 하나로 연결
         */
        for (int d = 0; d < 4; d++) {

            if (!isConnectable(x, y, d)) {
                continue;
            }

            int curWire = connect(x, y, d);

            solve(
                idx + 1,
                cntCore + 1,
                wireLen + curWire
            );

            // 백트래킹
            disconnect(x, y, d);
        }

        /*
         * 현재 코어를 연결하지 않는 경우
         */
        solve(idx + 1, cntCore, wireLen);
    }

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(
            new InputStreamReader(System.in)
        );

        StringTokenizer st;

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {

            N = Integer.parseInt(br.readLine());

            board = new int[N][N];
            cores.clear();

            for (int i = 0; i < N; i++) {

                st = new StringTokenizer(br.readLine());

                for (int j = 0; j < N; j++) {

                    board[i][j] = Integer.parseInt(st.nextToken());

                    if (board[i][j] == 1) {

                        // 가장자리 코어는 이미 전원에 연결되어 있으므로
                        // 백트래킹 대상에서 제외
                        if (
                            i == 0 ||
                            j == 0 ||
                            i == N - 1 ||
                            j == N - 1
                        ) {
                            continue;
                        }

                        cores.add(new int[]{i, j});
                    }
                }
            }

            coreCnt = cores.size();

            maxCore = 0;
            minWire = Integer.MAX_VALUE;

            solve(0, 0, 0);

            System.out.println("#" + tc + " " + minWire);
        }
    }
}

import java.util.*;
import java.io.*;

public class 프로세서연결하기 {

	static class Core {
		int r; // 행 좌표
		int c; // 열 좌표

		Core(int r, int c) {
			this.r = r;
			this.c = c;
		}
	}

	static final int[] dr = {0, 1, 0, -1};
	static final int[] dc = {1, 0, -1, 0};

	static int maxConnected; // 연결한 core 수
	static int minLength; // 전선 길이의 합(연결 코어 수 같다면 최소가 되어야함)
	static int N; // map 크기
	static int[][] map;
	static List<Core> cores; // 코어들을 담을 리스트

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {
			N = Integer.parseInt(br.readLine());

			maxConnected = 0;
			minLength = 145; // 최대 map 크기인 12x12 = 144 고려하여 초기값 설정
			map = new int[N][N];
			cores = new ArrayList<>();
			for (int i = 0; i < N; i++) {
				st = new StringTokenizer(br.readLine());
				for (int j = 0; j < N; j++) {
					map[i][j] = Integer.parseInt(st.nextToken());

					// 가장자리 코어는 이미 연결된 상태이므로 count하고 탐색은 하지 않는다.
					if (map[i][j] == 1) {
						// 가장자리 아닌 노드들만 저장
						if (i != 0 && j != 0 && i != N - 1 && j != N - 1) {
							cores.add(new Core(i, j));
						}
					} // if end

				} // for j end
			} // for i end

			dfs(0, 0, 0);
			sb.append('#').append(tc).append(' ').append(minLength).append('\n');
		} // tc end
		System.out.print(sb);
	} // main end

	// 탐색한 코어 수, 연결한 코어 수, 전선 길이 합
	static void dfs(int depth, int cntConnected, int lengthSum) {

		// 가지치기: 남은 코어 수만큼 연결 여부 결정해도 이전에 했던 결정의 코어 연결 수를 넘지 못하면 더이상 볼필요 없음
		// 남은 코어 수: cores.size() - depth
		if (cntConnected + cores.size() - depth < maxConnected) {
			return;
		}

		// 모든 코어 전선 연결 여부 확인했다면 갱신
		if (depth == cores.size()) { // 최대한 많은 코어 연결해야 하므로 maxConnected
			if (maxConnected < cntConnected) { // 코어 연결 수가 더 많다면 그걸로 갱신
				maxConnected = cntConnected;
				minLength = lengthSum;
			} else if (maxConnected == cntConnected) {
				if (minLength > lengthSum) minLength = lengthSum;
			}

			return;
		}

		// cores에서 하나씩 빼면서 확인하기
		Core cur = cores.get(depth);

		// 각 방향마다 범위가 다르므로 모듈화하여 관리
		// 전선 연결 => 범위 저장해서 해당 범위 내에 들어오는 행 or 열이면 교차므로 return;

		for (int dir = 0; dir < 4; dir++) {
			// 좌, 우, 상, 하 방향 전선 연결 가능한지 확인
			if (canConnect(cur, dir)) {
				// 연결 가능하면 전선 길이 구하기
				int len = setWire(cur, dir, 1);
				dfs(depth+1, cntConnected+1, lengthSum + len);
				setWire(cur, dir, 0); // 경우의 수 상태 원복
			}
		}

		// 아무것도 연결x
		dfs(depth+1, cntConnected, lengthSum);

	} // dfs end

	// 전선 연결 가능여부 확인
	static boolean canConnect(Core core, int dir) {
		int nr = core.r + dr[dir];
		int nc = core.c + dc[dir];

		while (inRange(nr, nc)) {
			if (map[nr][nc] != 0) { // 가는 경로에 이미 전선이 깔려있다면 깔지 못하므로 가지치기
				return false;
			}
			nr += dr[dir];
			nc += dc[dir];
		}

		return true;
	}

	// 전선 상태 변경
	static int setWire(Core core, int dir, int value) {

		int length = 0;
		int nr = core.r + dr[dir];
		int nc = core.c + dc[dir];

		// dr, dc 정의했으므로 방향별 순차 탐색
		while (inRange(nr, nc)) {
			map[nr][nc] = value;
			length++;

			nr += dr[dir];
			nc += dc[dir];
		}

		return length;

	} // setWire end

	// 가능한 범위인지 반환
	static boolean inRange(int nr, int nc) {
		return (0 <= nr && nr < N && 0 <= nc && nc < N);
	}

} // class end

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.*;

public class Solution {
	/*
	 * 요약 : 최대한 core에 많은 전원을 연결 할 수 있는 전선길이의 최소 값 N은 7부터 12까지 재귀 12*12 백트래킹 조합문제 특징:
	 * 1. 전선은 교차 불가 2. 가장자리는 전기가 들어옴
	 * 
	 * to do: 1. core에 전기 연결된 녀석들 찾기 2. 코어 a가 왼쪽연결시의 코어 b의 연결의 왼쪽연결시 ... etc 3. 같은
	 * 백트래킹
	 * 
	 * 모르겠다 : 재귀 시간복잡도 계산이 어려움 한 코어당 (최대 12개) 4방향이니까 4^12승 즉 2의 24승정도 2의 10는은 1024 *
	 * 1024 = 10^6<= 10^8보다 작다고 예상 가지치기 하면 더 작아질듯
	 * 
	 * 가지치기 : 1. 방문처리 visited가 되있다면 cancle 2. 남은 코어수 + 연결된 코어수가 현재 최대코어수 미만이면 return
	 * 3. 코어수 똑같은데 전선길이가 더 긴 루트면 return
	 */

	static int totalLine;
	static int bestCore;
	static int totalCore;
	static ArrayList<int[]> corePos;
	static int[][] mtrx;
	static int N;
	static int[][] vis;
	static int[] dr = { -1, 1, 0, 0 };
	static int[] dc = { 0, 0, -1, 1 };

	public static void main(String[] args) throws Exception {
		// input
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {
			sb.append("#").append(tc).append(" ");

			N = Integer.parseInt(br.readLine());
			mtrx = new int[N][N];
			vis = new int[N][N];
			corePos = new ArrayList<int[]>();
			totalLine = 12 * 12;
			bestCore = 0;
			totalCore = 0;
			for (int i = 0; i < N; i++) {
				st = new StringTokenizer(br.readLine());
				for (int j = 0; j < N; j++) {
					mtrx[i][j] = Integer.parseInt(st.nextToken());
					if (mtrx[i][j] == 1) {
						vis[i][j] = -1; // core일 경우 갈 수 없음
						if (i == 0 || j == 0 || i == N - 1 || j == N - 1) {
							// 이미 연결된 경우
							bestCore += 1;
						} else {
							corePos.add(new int[] { i, j });
						}
					}
				}
			}
			// for문 돌며 프로세서 위치 탐색
			// 탐색해야할 프로세서 위치 저장한 배열
			// dfs

			dfs(0, bestCore, 0);
			// 현재 인덱스의 프로세서가 가능한지 탐색
			// 그때까지의 전선수 total 전선수에 추가
			sb.append(totalLine).append("\n");
		}
		System.out.println(sb);
	}

	// dfs 들어가야할 코어 인덱스, 지금까지의 전선길이
	static void dfs(int coreIdx, int coreCount, int lineCost) {
		// 마지막 일때 컷(먼저 해도 차이없음)
		if (corePos.size() == coreIdx) {
			if (totalCore < coreCount) {
				totalCore = coreCount;
				totalLine = lineCost;
			} else if (totalCore == coreCount) {
				totalLine = Math.min(totalLine, lineCost);
			}
			return;
		}
		int remain = corePos.size() - coreIdx;

		if (coreCount + remain < bestCore)
			return;

		if (coreCount + remain == bestCore && lineCost >= totalLine)
		    return;
		// visited 검사로 연결될 수 있는지 4방향 탐색
		// > 벽에 못닿으면 continue
		// > 닿으면 최대 프로세서 +1

		int core[] = corePos.get(coreIdx);
		int r = core[0];
		int c = core[1];

		// 4방향 탐색을 하면서, 각각의 방향의 좌표일때의 경우의수를 구한다.
		// vis배열이 복사되어야 할 것 같은데.. 복사하기 싫으면 ?
		// 1. 되돌리기
		int d = -1;

		while (d + 1 < 4) {
			d += 1;

			// 커넥트 할 수 있을때만
			// 와이어를 놓는다.. < 그럼 복구안해도돼
			if (!isOn(r, c, d))
				continue;

			int cost = setWire(r, c, d, 0);
			dfs(coreIdx + 1, coreCount + 1, lineCost + cost);

			setWire(r, c, d, 1);
		}

		dfs(coreIdx + 1, coreCount, lineCost);

	}

	// isOn 탐색
	// 해당좌표에서 벽에닿는지 검사
	static boolean isOn(int r, int c, int dir) {
		// 다음 좌표부터 시작되는 라인이
		// 종료조건은 i와 j가 0 또는 n-1이될때까지 접촉
		// 못닿으면 (가는도중 vis가 1이면 return)
		int nr = r + dr[dir];
		int nc = c + dc[dir];

		while (!oob(nr, nc)) {
			if (vis[nr][nc] == -1) {
				return false;
			}

			nr += dr[dir];
			nc += dc[dir];

		}

		return true;

	}

	// isOn 탐색
	// 해당좌표에서 벽에닿는지 검사
	static int setWire(int r, int c, int dir, int isSet) {
		// 다음 좌표부터 시작되는 라인이
		// 종료조건은 i와 j가 0 또는 n-1이될때까지 접촉
		// 못닿으면 (가는도중 vis가 1이면 return)
		int nr = r + dr[dir];
		int nc = c + dc[dir];
		int value = 0;

		if (oob(nr, nc))
			return 0;

		while (!oob(nr, nc)) {

			if (isSet == 0) {
				value += 1;
				vis[nr][nc] = -1;
			} else {
				vis[nr][nc] = 0;
			}
			nr += dr[dir];
			nc += dc[dir];

		}
		return value;

	}

	// oob
	static boolean oob(int r, int c) {
		if (r < 0 || c < 0 || r >= N || c >= N)
			return true;
		return false;
	}
}

import java.io.*;
import java.util.*;

public class Swea_1767 {

    static int n;
    static int[][] map;
    static int maxConn;
    static int minWire;
    static List<int[]> cores;

    static int[] dr = { -1, 0, 1, 0 };
    static int[] dc = { 0, 1, 0, -1 };

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        StringTokenizer st;
        StringBuilder sb = new StringBuilder();

        final int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc += 1) {
            n = Integer.parseInt(br.readLine());
            map = new int[n][n];
            cores = new ArrayList<>();
            maxConn = 0;
            minWire = Integer.MAX_VALUE;

            for (int i = 0; i < n; i += 1) {
                st = new StringTokenizer(br.readLine());
                for (int j = 0; j < n; j += 1) {
                    map[i][j] = Integer.parseInt(st.nextToken());
                    if (i == 0 || i == n - 1 || j == 0 || j == n - 1) continue;

                    if (map[i][j] == 1) {
                        cores.add(new int[] { i, j });
                    }
                }
            }
            dfs(0, 0, 0);

            sb.append('#').append(tc).append(' ').append(minWire).append('\n');
        }
        bw.write(sb.toString());
        bw.flush();
        bw.close();
    }

    static void dfs(int idx, int conn, int wireLen) {
        if (idx == cores.size()) {
            if (conn > maxConn) {
                minWire = wireLen;
                maxConn = conn;
                return;
            }

            if (conn == maxConn) {
                minWire = Math.min(minWire, wireLen);
                return;
            }
            return;
        }

        int[] corePos = cores.get(idx);
        int r = corePos[0];
        int c = corePos[1];

        for (int d = 0; d < 4; d += 1) {
            int len = connect(r, c, d);
            if (len > 0) {
                dfs(idx + 1, conn + 1, wireLen + len);
                disconnect(r, c, d);
            }
        }
        dfs(idx + 1, conn, wireLen);
    }

    static boolean isAvailable(int r, int c, int d) {
        int nr = r + dr[d];
        int nc = c + dc[d];
        while (0 <= nr && nr < n && 0 <= nc && nc < n) {
            int circuit = map[nr][nc];
            if (circuit == 1 || circuit == 2) return false;
            nr += dr[d];
            nc += dc[d];
        }
        return true;
    }

    static int connect(int r, int c, int d) {
        if (!isAvailable(r, c, d)) return -1;

        int nr = r + dr[d];
        int nc = c + dc[d];
        int len = 0;

        while (0 <= nr && nr < n && 0 <= nc && nc < n) {
            map[nr][nc] = 2;
            nr += dr[d];
            nc += dc[d];
            len += 1;
        }

        return len;
    }

    static void disconnect(int r, int c, int d) {
        int nr = r + dr[d];
        int nc = c + dc[d];
        while (0 <= nr && nr < n && 0 <= nc && nc < n) {
            map[nr][nc] = 0;
            nr += dr[d];
            nc += dc[d];
        }
    }
}

import java.io.*;
import java.util.*;

public class SWEA1952{
	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		int T = Integer.parseInt(br.readLine().trim());
		for(int t = 1; t <= T; t++) {
			StringTokenizer st = new StringTokenizer(br.readLine());
			int day = Integer.parseInt(st.nextToken());
			int month = Integer.parseInt(st.nextToken());
			int month3 = Integer.parseInt(st.nextToken());
			int year = Integer.parseInt(st.nextToken());

			st = new StringTokenizer(br.readLine());
			int[] plan = new int[12];
			for(int i = 0; i < 12; i++) {
				plan[i] = Integer.parseInt(st.nextToken());
			}

			int[] moneyPlan = new int[12];

			// 일간 - 월간 비교 후 책정
			for(int i = 0; i < 12; i++) {
				int dayCost = day * plan[i];
				moneyPlan[i] = (dayCost > month) ? month : dayCost;
			}

			// 월간 - 3개월간 비교 후 책정
			// 앞에서부터 비교 후 책정
			int start = 0;
			int frontSum = 0;
			while(start < 12) {
				int monthCost = moneyPlan[start];
				if(start + 1 < 12) monthCost += moneyPlan[start + 1];
				if(start + 2 < 12) monthCost += moneyPlan[start + 2];

				if(monthCost > month3) {
					frontSum += month3;
					start += 3;
				}
				else {
					frontSum += moneyPlan[start];
					start++;	
				}
			}

			// 뒤에서부터 비교 후 책정
			int end = 11;
			int backSum = 0;
			while(end >= 2) {
				int monthCost = moneyPlan[end];
				monthCost += moneyPlan[end - 1];
				monthCost += moneyPlan[end - 2];

				if(monthCost > month3) {
					backSum += month3;
					end -= 3;
				}
				else {
					backSum += moneyPlan[end];
					end--;	
				}
			}
			backSum += moneyPlan[1] + moneyPlan[0];

			// 앞부터랑 뒤부터의 결과를 비교해서 작은쪽으로 책정
			int result = (frontSum < backSum) ? frontSum : backSum;

			// 연간과 최종 비교
			if(result > year) result = year;

			sb.append("#").append(t).append(" ").append(result).append("\n");
		}
		System.out.print(sb);
	}
}

