public class swea1952 {

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {

            // 1일권, 1개월권, 3개월권, 1년권
            int[] table = new int[4];

            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int i = 0; i < 4; i++) {
                table[i] = Integer.parseInt(st.nextToken());
            }

            // 1월 ~ 12월
            int[] board = new int[13];

            st = new StringTokenizer(br.readLine());
            for (int i = 1; i <= 12; i++) {
                board[i] = Integer.parseInt(st.nextToken());
            }

            // dp[i] = 1월 ~ i월까지 이용하기 위한 최소 비용
            int[] dp = new int[13];

            for (int i = 1; i <= 12; i++) {

                // 이번 달을 1일권으로 처리
                int day = dp[i - 1] + board[i] * table[0];

                // 이번 달을 1개월권으로 처리
                int month = dp[i - 1] + table[1];

                // 마지막 3개월을 3개월권으로 처리
                int threeMonth;
                if (i >= 3) {
                    threeMonth = dp[i - 3] + table[2];
                } else {
                    threeMonth = table[2];
                }

                dp[i] = Math.min(day, Math.min(month, threeMonth));
            }

            // 1년권과 비교
            int answer = Math.min(dp[12], table[3]);

            sb.append("#")
              .append(tc)
              .append(" ")
              .append(answer)
              .append("\n");
        }

        System.out.print(sb);
    }
}

