public class SWEA_1486 {
    static int N;       // 점원의 수
    static int B;       // 선반의 높이
    static int[] H;     // 각 점원의 키를 저장하는 배열
    static int minH;    // 선반 높이(B) 이상이면서 가장 작은 탑의 높이

    public static void main(String[] args) throws IOException {
        // 빠른 입출력을 위한 BufferedReader와 StringTokenizer 설정
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // 총 테스트 케이스 개수 입력
        int T = Integer.parseInt(br.readLine());

        // 각 테스트 케이스 처리
        for (int test_case = 1; test_case < T + 1; test_case++) {
            st = new StringTokenizer(br.readLine());
            N = Integer.parseInt(st.nextToken()); // 점원의 수 세팅
            B = Integer.parseInt(st.nextToken()); // 목표 선반 높이 세팅

            H = new int[N]; // 점원들의 키를 저장할 배열 크기 할당
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < N; i++) {
                H[i] = Integer.parseInt(st.nextToken()); // 각 점원의 키 입력
            }

            // 최솟값을 갱신하기 위해 정수의 최댓값으로 초기화
            minH = Integer.MAX_VALUE;

            // 0번째 점원부터, 현재 탑의 높이 0으로 DFS 탐색 시작
            dfs(0, 0);

            // 문제 조건인 (가장 작은 탑의 높이 - 선반의 높이) 차이를 출력
            System.out.println("#" + test_case + " " + (minH - B));
        }
    }

    /**
     * 모든 점원을 탑에 쌓을지 말지 결정하며 완탐하는 DFS 함수
     * @param step   현재 고려하고 있는 점원의 인덱스 (0 ~ N-1)
     * @param curH   현재까지 쌓은 탑의 높이 합
     */
    public static void dfs(int step, int curH) {
        // 백트래킹(가지치기) 최적화 추가 가능 위치: 
        // 만약 이미 curH가 minH 이상이라면 더 유망하지 않으므로 리턴할 수 있습니다.
        if (curH >= minH) return; 

        // 모든 점원에 대해 선택 여부를 결정했을 때 (기저 조건)
        if (step == N) {
            // 탑의 높이가 선반 높이(B) 이상인 경우에만 최솟값 갱신
            if (curH >= B) {
                minH = Math.min(minH, curH);
            }
            return;
        }

        // 분기 1: 현재 점원(H[step])을 탑에 쌓는 경우
        dfs(step + 1, curH + H[step]);

        // 분기 2: 현재 점원(H[step])을 탑에 쌓지 않는 경우
        dfs(step + 1, curH);
    }
}

import java.util.*;
import java.io.*;
/*
 *  1 ~ N개를 선택했을 때, 나오는 조합중에서 탑의 높이가 가장 낮은 것 구하기
 * 
 	알고리즘: 조합 dfs

 	dfs
 	- 1 ~ n개를 선택하는 경우의 수를 모두 구한다.
 	- 선택한 조합을 더했을 때, b보다 높은 것만 구한다.
 	- b보다 높은 것 중에 가장 작은 것을 구한다.
 */
class Main {
	static int[] arr;
	static boolean[] vis;
	static int n, b;
	static int minHeight;
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        int t = Integer.parseInt(br.readLine());

        for(int test_case=1; test_case<=t; test_case++) {
            st = new StringTokenizer(br.readLine());

            n = Integer.parseInt(st.nextToken());
            b = Integer.parseInt(st.nextToken());

            arr = new int[n];
            vis = new boolean[n];

            st = new StringTokenizer(br.readLine());
            for(int i=0; i<n; i++) {
            	arr[i] = Integer.parseInt(st.nextToken());
            }

            minHeight = Integer.MAX_VALUE;
            dfs(0);

            int result = minHeight - b;

            sb.append("#").append(test_case).append(" ").append(result).append("\n");
        }
        System.out.print(sb);
    }
   /*
    * depth: 숫자를 선택한 인덱스 개수
    */
    static void dfs(int depth) {
    	if(depth >= n) {
    		int sum = 0;
    		for(int i=0; i<n; i++) {
    			if(vis[i]) {
    				sum += arr[i];
    			}
    		}
    		if(sum >= b) {
    			minHeight = Math.min(minHeight, sum);
    		}
    		return;
    	}

    	vis[depth] = true;
	    dfs(depth+1);

	    vis[depth] = false;
	    dfs(depth+1);
    }
}

