			m = Integer.parseInt(st.nextToken());
			answer = Integer.MAX_VALUE;
			st = new StringTokenizer(br.readLine());
			for(int i=0;i<n;i++)
			{
				arr[i] = Integer.parseInt(st.nextToken());
			}

			solution(0, 0);

			sb.append("#").append(tc).append(" ").append(answer-m).append("\n");

		}
		System.out.println(sb);
	}

	static void solution(int k, int sum)
	{
		if(sum>=m)
		{
			answer = Math.min(answer, sum);
			return;
		}

		if(k==n)
			return;

		solution(k+1,sum+arr[k]);
		solution(k+1,sum);


	}
}

import java.util.*;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
/*
 * 
 * 1486.장훈이의 높은 선반
 * 문제요약 : 선반위의 놓인 물건을 사용할 수 있는 탑의 높이중의 가장 낮은 탑의 높이 구하기
 * 
 *  범위, S : 점원들의 키의 합 각 점원의 키는 1 ~ 10,000
 *  5 16
 *  1 3 3 5 6
 *  
 *   선반 B와 같거나 큰 탑 중 가장 낮은 값.
 *   조합, 근데 작은방향으로 
 *   
 *   떠오르는 아이디어 : 정렬해서 투포인터 , 조합
 *   정렬해서 다 합친후에, 최소 키부터 빼주면 ○○님? 	
 *   => 응 아냐 투포인터로 풀어야할듯
 * 	 => 투포인터로 풀려고 했으나 키들 사이의 관계가 상관없다. 각각의 키는 독립순서라서 정렬도 필요없고 조합도 필요없다.
 * */

public class Solution {
	static int N;
	static int B;
	static int tower;
	static int[] arr;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {
			sb.append("#").append(tc).append(" ");

			st = new StringTokenizer(br.readLine());
			N = Integer.parseInt(st.nextToken());
			B = Integer.parseInt(st.nextToken());

			tower = Integer.MAX_VALUE;
			arr = new int[N];

			st = new StringTokenizer(br.readLine());

			for (int i = 0; i < N; i++) {
				arr[i] = Integer.parseInt(st.nextToken());
			}

			Arrays.sort(arr);
			dfs(0,0);
			sb.append(tower - B).append("\n");
		}
		System.out.println(sb);
	}

	// dfs 재귀 20 정도 돌면서 가지치기 시도, 재귀 200까지 됐던거 같은데
	// 목적 : 조합을 짜서 키보다 얼마나 큰지 체크
	// 가지치기 : 같아지면 탈출, 이미 존재하는 최소 키보다 크면 탈출
	// 가지치기 : 재귀에 넣기 전부터 최소 키보다 크면 넣지 말자.
	// 파라미터, 목적 타겟 크기,
	static void dfs(int idx, int sum) {
		if (sum >= B && sum < tower) {
			tower = sum;
			return;
		}

		// 돌자
		for (int i = idx; i < N; i++) {
			dfs(i + 1, sum + arr[i]); // 중복 컷
		}

	}
}

import java.io.*;
import java.util.*;

public class Swea_1486 {

    static int n;
    static int b;

    static int[] arr;
    static int minH;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        final int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc += 1) {
            st = new StringTokenizer(br.readLine());
            n = Integer.parseInt(st.nextToken());
            b = Integer.parseInt(st.nextToken());
            minH = Integer.MAX_VALUE;

            arr = new int[n];
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < n; i += 1) {
                arr[i] = Integer.parseInt(st.nextToken());
            }

            dfs(0, 0);

            sb.append('#')
                .append(tc)
                .append(' ')
                .append(Math.abs(b - minH))
                .append('\n');
        }
        bw.write(sb.toString());
        bw.flush();
        bw.close();
    }

    static void dfs(int h, int st) {
        if (h >= b) {
            minH = Math.min(minH, h);
            return;
        }

        for (int i = st; i < n; i += 1) {
            dfs(h + arr[i], i + 1);
        }
    }
}

import java.io.*;
import java.util.*;

public class SWEA2805 {
	static int N;
	static int[][] board;
	static int result;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		int T = Integer.parseInt(br.readLine().trim());
		for(int t = 1; t <= T; t++) {
			N = Integer.parseInt(br.readLine().trim());
			board = new int[N][N];
			result = 0;

			for(int i = 0; i < N; i++) {
				char[] line = br.readLine().trim().toCharArray();
				for(int j = 0; j < N; j++) {
					board[i][j] = line[j] - '0'; 
					if(getDist(i, j, N / 2, N / 2) <= N / 2) {
						result += board[i][j];
					}
				}
			}

			sb.append("#").append(t).append(" ").append(result).append("\n");
		}
		System.out.print(sb);
	}

	private static int getDist(int x1, int y1, int x2, int y2) {
		return (Math.abs(x1 - x2) + Math.abs(y1 - y2));
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class SWEA_2805 {
	static int N;          // 농장의 크기 (N x N, 항상 홀수)
	static int[][] farm;   // 농장 격자 데이터를 저장할 2차원 배열
	static int middle;     // 농장의 중앙 인덱스 (N / 2)

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int T = Integer.parseInt(br.readLine()); // 전체 테스트 케이스 개수 입력
		for (int test_case = 1; test_case < T + 1; test_case++) {
			N = Integer.parseInt(br.readLine()); // 이번 케이스의 농장 크기 N 입력
			middle = N / 2;                      // 정수 나눗셈으로 중앙 위치 계산 (예: 5 -> 2)
			farm = new int[N][N];                // N x N 크기로 배열 초기화

			// 농장 정보 입력 받기 (공백 없이 붙어서 들어오는 문자열 처리)
			for (int i = 0; i < N; i++) {
				String str = br.readLine();
				for (int j = 0; j < N; j++) {
					// 문자 '0'~'9'를 대응하는 정수 0~9로 변환하여 저장
					farm[i][j] = str.charAt(j) - '0'; 
				}
			}

			// 결과 출력 (#테스트케이스 정답)
			System.out.println("#" + test_case + " " + calculate());
		}
	}

	/**
	 * 마름모 형태로 배치된 농작물의 가치 합을 계산하는 메서드
	 */
	public static int calculate() {
		int sum = 0;

		// 1. 중앙 가로줄과 세로줄(십자가 모양)의 농작물 가치를 먼저 합산
		for (int i = 0; i < N; i++) {
			sum += farm[i][middle]; // 정중앙 세로줄 합산
			sum += farm[middle][i]; // 정중앙 가로줄 합산
		}
		// 정중앙 칸(farm[middle][middle])이 가로/세로에서 중복으로 더해졌으므로 1번 차감
		sum -= farm[middle][middle];

		// 2. 마름모의 상단 영역(정중앙 줄 위쪽) 날개 부분 계산
		// (행 인덱스 1부터 middle - 1까지 탐색)
		for (int i = 1; i < middle; i++) {
			// 중앙에서 좌우로 한 칸씩 넓혀가며 더함
			for (int j = 1; j < i + 1; j++) {
				sum += farm[i][middle - j]; // 중앙 기준 왼쪽 날개
				sum += farm[i][middle + j]; // 중앙 기준 오른쪽 날개
			}
		}

		// 3. 마름모의 하단 영역(정중앙 줄 아래쪽) 날개 부분 계산
		// (행 인덱스 middle + 1부터 N - 2까지 탐색)
		for (int i = middle + 1; i < N - 1; i++) {
			// 아래로 갈수록 마름모가 좁아지므로 탐색 범위가 줄어듦
			for (int j = 1; j < N - i; j++) {
				sum += farm[i][middle - j]; // 중앙 기준 왼쪽 날개
				sum += farm[i][middle + j]; // 중앙 기준 오른쪽 날개
			}
		}

		return sum; // 최종 마름모 합산 결과 반환
	}
}

