					arr[i][j] = ch - '0';
				}
			}

			int total = 0;
			for(int i=0; i<n/2; i++) {
				for(int j=n/2-i; j<=n/2+i; j++) {
					total += arr[i][j];
					total += arr[n-i-1][j];
				}
			}

			for(int i=0; i<n; i++) {
				total += arr[n/2][i];
			}

			sb.append("#").append(test_case).append(" ").append(total).append("\n");
		}
		System.out.print(sb);
	}
