import java.util.Scanner;

public class SWEA_4796 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // 테스트 케이스 개수 T 입력
        int T = sc.nextInt();

        for (int test_case = 1; test_case <= T; test_case++) {
            // 산의 봉우리 개수 N 입력
            int N = sc.nextInt();
            int[] mountain = new int[N];

            // 각 봉우리의 높이 데이터 배열에 저장
            for (int i = 0; i < N; i++) {
                mountain[i] = sc.nextInt();
            }

            int totalCount = 0; // 우뚝 선 산 모양의 총 개수
            int up = 0;         // 현재 산에서 오르막길(상승 구간)의 개수
            int down = 0;       // 현재 산에서 내리막길(하강 구간)의 개수

            // 인접한 두 봉우리를 비교하며 한 칸씩 이동 (0번부터 N-2번까지)
            for (int i = 0; i < N - 1; i++) {

                // Case 1: 다음 봉우리가 더 높은 경우 (오르막길)
                if (mountain[i] < mountain[i + 1]) { 

                    // [핵심] 만약 직전까지 내리막길(down > 0)이었다면, 이제 새로운 산이 시작되는 시점입니다.
                    // 따라서 지금까지 세어둔 오르막(up)과 내리막(down)의 조합으로 만들 수 있는 산의 개수를 합산합니다.
                    if (down > 0) {
                        totalCount += up * down; // 조합의 수 = 오르막 개수 * 내리막 개수
                        up = 0;                  // 새로운 산을 측정하기 위해 상승 카운트 리셋
                        down = 0;                // 새로운 산을 측정하기 위해 하강 카운트 리셋
                    }

                    up++; // 오르막길 카운트 1 증가
                } 

                // Case 2: 다음 봉우리가 더 낮은 경우 (내리막길)
                else if (mountain[i] > mountain[i + 1]) { 

                    // 우뚝 선 산은 반드시 먼저 올라간 적(up > 0)이 있어야 성립합니다.
                    // 오르막길 없이 처음부터 내려가는 구간은 카운트하지 않습니다.
                    if (up > 0) {
                        down++; // 내리막길 카운트 1 증가
                    }
                } 

                // Case 3: 두 봉우리의 높이가 같은 경우 (평지)
                else { 
                    // 평지가 나오면 지금까지의 산 구조가 끊어집니다. 
                    // 완성된 산(up > 0, down > 0)이 있다면 개수를 더해줍니다.
                    if (up > 0 && down > 0) {
                        totalCount += up * down;
                    }
                    up = 0;   // 모든 카운트 리셋
                    down = 0;
                }
            }

            // [중요] 루프가 끝난 후, 배열의 맨 마지막 부분에서 완성된 산은 
            // 더 이상 오르막길(Case 1)을 만나지 않아 누적되지 못하고 남아있습니다. 이를 마지막으로 정산합니다.
            if (up > 0 && down > 0) {
                totalCount += up * down;
            }

            // 결과 출력
            System.out.println("#" + test_case + " " + totalCount);
        }
        sc.close();
    }
}

