public class SWEA_7733 {

	// 치즈의 맛 정보를 저장하는 배열
	public static int[][] cheese;

	// 치즈판의 크기
	public static int N;

	// 상, 하, 좌, 우 이동을 위한 방향 배열
	public static int[] dy = { 1, -1, 0, 0 };
	public static int[] dx = { 0, 0, 1, -1 };

	public static void main(String[] args) throws IOException {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st;

		// 테스트 케이스 개수
		int T = Integer.parseInt(br.readLine());

		for (int test_case = 1; test_case < T + 1; test_case++) {

			// 치즈판 크기 입력
			N = Integer.parseInt(br.readLine());

			// 치즈판 생성
			cheese = new int[N][N];

			// 치즈의 최대 맛을 저장
			// 이후 모든 맛을 기준으로 치즈를 제거해보기 위해 사용
			int maxTaste = Integer.MIN_VALUE;

			// 치즈판 입력
			for (int i = 0; i < N; i++) {
				st = new StringTokenizer(br.readLine());

				for (int j = 0; j < N; j++) {
					cheese[i][j] = Integer.parseInt(st.nextToken());

					// 최대 맛 갱신
					maxTaste = Math.max(maxTaste, cheese[i][j]);
				}
			}

			// 날짜별로 치즈를 먹어보고
			// 가장 많은 영역의 개수를 저장
			int maxArea = Integer.MIN_VALUE;

			/*
			 * 0일차부터 최대 맛까지 반복
			 *
			 * eatCheese(i)를 호출하면
			 * 현재 날짜의 맛과 같은 치즈를 제거하고
			 * 남은 치즈 덩어리의 개수를 반환한다.
			 */
			for (int i = 0; i < maxTaste + 1; i++) {
				maxArea = Math.max(maxArea, eatCheese(i));
			}

			// 결과 출력
			System.out.println("#" + test_case + " " + maxArea);
		}
	}

	/*
	 * 현재 날짜에 해당하는 맛의 치즈를 먹는 메서드
	 *
	 * taste와 같은 값을 가진 치즈를 0으로 변경한다.
	 * 여기서 0은 "치즈가 없는 칸"을 의미한다.
	 *
	 * 이후 countArea()를 호출하여
	 * 현재 남아있는 치즈 영역의 개수를 반환한다.
	 */
	public static int eatCheese(int taste) {

		// 전체 치즈판을 확인
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < N; j++) {

				// 현재 날짜의 맛과 같은 치즈라면
				if (cheese[i][j] == taste) {

					// 해당 치즈를 먹어서 0으로 만든다.
					cheese[i][j] = 0;
				}
			}
		}

		// 남아있는 치즈 영역의 개수 반환
		return countArea();
	}

	/*
	 * 현재 남아있는 치즈 영역의 개수를 세는 메서드
	 *
	 * 치즈가 있고 아직 방문하지 않은 칸을 발견하면
	 * 해당 칸을 시작점으로 BFS를 수행한다.
	 *
	 * BFS 한 번 = 하나의 연결된 치즈 영역
	 */
	public static int countArea() {

		// 연결된 치즈 영역의 개수
		int count = 0;

		// 방문 여부를 저장하는 배열
		// 0 : 방문하지 않음
		// -1 : 방문함
		int[][] visited = new int[N][N];

		// 모든 칸을 확인
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < N; j++) {

				/*
				 * 치즈가 존재하고
				 * 아직 방문하지 않은 칸이라면
				 *
				 * 새로운 치즈 영역을 발견한 것이므로
				 * BFS를 수행한다.
				 */
				if (cheese[i][j] != 0 && visited[i][j] == 0) {

					// 연결되어 있는 모든 치즈를 방문
					bfs(i, j, visited);

					// BFS 한 번이 하나의 영역이므로 count 증가
					count++;
				}
			}
		}

		// 현재 치즈 영역의 총 개수 반환
		return count;
	}

	/*
	 * BFS를 이용하여 하나의 연결된 치즈 영역을 모두 방문한다.
	 *
	 * y, x : BFS를 시작할 위치
	 * visited : 방문 여부를 기록하는 배열
	 */
	public static void bfs(int y, int x, int[][] visited) {

		// BFS에 사용할 큐
		Queue<int[]> queue = new ArrayDeque<int[]>();

		// 시작점을 큐에 넣는다.
		queue.offer(new int[] { y, x });

		// 시작점 방문 처리
		visited[y][x] = -1;

		// 큐가 빌 때까지 반복
		while (!queue.isEmpty()) {

			// 현재 탐색할 위치를 꺼낸다.
			int[] q = queue.poll();

			// 현재 위치에서 상, 하, 좌, 우 탐색
			for (int i = 0; i < 4; i++) {

				// 다음 위치 계산
				int ny = q[0] + dy[i];
				int nx = q[1] + dx[i];

				/*
				 * 범위를 벗어나거나
				 * 이미 방문한 칸이면 건너뛴다.
				 */
				if (ny == N || ny < 0 || nx == N || nx < 0
						|| visited[ny][nx] == -1) {
					continue;
				}

				/*
				 * 다음 칸에 치즈가 있고
				 * 아직 방문하지 않았다면
				 * BFS 탐색 대상이 된다.
				 */
				if (cheese[ny][nx] != 0 && visited[ny][nx] == 0) {

					// 다음 칸을 큐에 추가
					queue.offer(new int[] { ny, nx });
				}

				/*
				 * 방문 처리
				 *
				 * 치즈가 없는 칸도 방문 처리되지만,
				 * 이 문제에서는 결과에 영향을 주지 않는다.
				 */
				visited[ny][nx] = -1;
			}
		}
	}
}

