public class swea7733 {
	static int[] dr = {0, 1, 0, -1};
    static int[] dc = {1, 0, -1, 0};
    static int N;
    static int[][] cheese;
    static boolean[][] visited;

	public static void main(String args[]) throws Exception
	{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int T = Integer.parseInt(br.readLine());
        for (int tc = 1; tc <= T; tc++) {
            N = Integer.parseInt(br.readLine());
            cheese = new int[N][N];

            int maxday = 0;
            for (int r = 0; r < N; r++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                for (int c = 0; c < N; c++) {
                    cheese[r][c] = Integer.parseInt(st.nextToken());
                    maxday = Math.max(maxday, cheese[r][c]);
                }
            }
            int maxChunk = 0;

            for (int day = 0; day <=maxday; day++) {
                visited = new boolean[N][N];
                int chunk = 0;
            	for (int r = 0; r < N; r++) {
                	for (int c = 0; c < N;  c++) {
                    	if (cheese[r][c] > day && !visited[r][c]) {
                        	chunk++;
                        	bfs(r, c, day);
                        }
                    }
                }
                maxChunk = Math.max(maxChunk, chunk);
            }
            sb.append("#").append(tc).append(" ").append(maxChunk).append("\n");
        }
        System.out.print(sb);
	}

    static void bfs (int r, int c, int day) {
