		int T = Integer.parseInt(br.readLine()); // 테스트 케이스 개수 입력
		for (int test_case = 1; test_case < T + 1; test_case++) {

			N = Integer.parseInt(br.readLine()); // 지뢰밭 크기 입력
			area = new char[N][N];
			visited = new int[N][N];

			// 지뢰밭 맵 정보 입력 받기
			for (int i = 0; i < N; i++) {
