				area[i] = str.toCharArray();
			}

			// [단계 1] 모든 빈칸에 대해 주변 8방향의 지뢰 개수를 미리 계산 (visited 배열에 저장)
			findMine();

			int result = 0; // 최소 클릭 횟수를 저장할 변수

			// [단계 2] 지뢰찾기 그리디 규칙: 주변 지뢰가 '0'인 칸을 먼저 찾아서 클릭 (연쇄 확장)
			for (int i = 0; i < N; i++) {
				for (int j = 0; j < N; j++) {
					// 지뢰가 아니고, 주변 지뢰 개수가 0이며, 아직 열리지 않은(visited == 0) 칸인 경우
					if (area[i][j] != '*' && visited[i][j] == 0) {
						click(i, j); // 클릭하여 주변 칸들까지 연쇄적으로 열기
						result++;    // 마우스 클릭 횟수 1 증가
					}
				}
			}

			// [단계 3] 연쇄 확장(0 클릭)으로도 열리지 않고 외롭게 남은 '숫자 칸(> 0)'들을 처리
			for (int i = 0; i < N; i++) {
				for (int j = 0; j < N; j++) {
					// 지뢰가 아니고, 앞선 연쇄 작용에 휘말리지 않아 여전히 숫자가 남아있는(visited > 0) 칸인 경우
					if (area[i][j] != '*' && visited[i][j] > 0) {
						result++; // 이 칸들은 연쇄가 안 되므로 각각 개별적으로 1번씩 눌러야 함
					}
				}
			}

			// 최종 정답 출력
			System.out.println("#" + test_case + " " + result);
		}
	}

	/**
	 * 지정된 좌표 (y, x)를 시작으로 주변 8방향을 연쇄적으로 열어주는 BFS 함수
	 */
	public static void click(int y, int x) {
		Queue<int[]> queue = new ArrayDeque<int[]>();

		queue.offer(new int[] { y, x }); // 시작 좌표를 큐에 삽입
		visited[y][x] = -1;              // 시작 칸을 '열림(-1)' 상태로 마킹

		while (!queue.isEmpty()) {
			int[] q = queue.poll(); // 현재 탐색할 칸을 큐에서 꺼냄

			// 현재 칸의 주변 8방향 이웃 칸들을 탐색
			for (int i = 0; i < 8; i++) {
				int ny = q[0] + dy[i];
				int nx = q[1] + dx[i];

				// 맵 범위를 벗어나거나, 이미 열린 칸(-1)이거나, 지뢰(*)인 경우 패스
				if (ny == N || ny < 0 || nx == N || nx < 0 || visited[ny][nx] == -1 || area[ny][nx] == '*')
					continue;

				// [연쇄 조건] 이웃 칸의 주변 지뢰 개수도 '0'인 경우에만 큐에 넣어 탐색을 더 확장함
				if (visited[ny][nx] == 0) {
					queue.offer(new int[] { ny, nx });
				}

				// 지뢰 개수가 0이든 숫자가 있는 칸(> 0)이든 연쇄 작용으로 '열렸음'을 표시하기 위해 -1로 변경
				// (이 처리를 통해 다음 루프들에서 중복 연산되거나 다시 클릭되는 것을 완벽하게 방지)
				visited[ny][nx] = -1;
			}
		}
	}

	/**
	 * 모든 칸을 돌며 안전한 빈칸에 대해 주변 8방향의 지뢰(*) 개수를 세어 visited 배열에 채우는 함수
	 */
	public static void findMine() {
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < N; j++) {

				if (area[i][j] == '*') // 지뢰인 칸은 계산할 필요 없으므로 패스
					continue;

				int count = 0; // 주변 지뢰 개수를 누적할 변수

				// 현재 칸(i, j) 기준 주변 8방향 검사
				for (int k = 0; k < 8; k++) {
					int ny = i + dy[k];
					int nx = j + dx[k];

					if (ny == N || ny < 0 || nx == N || nx < 0) // 범위를 벗어나면 패스
						continue;

					if (area[ny][nx] == '*') { // 지뢰를 발견하면 카운트 증가
						count++;
					}
				}

				// 계산된 주변 지뢰 개수(0 ~ 8)를 visited 배열의 해당 칸에 저장
				visited[i][j] = count;
			}
		}
	}
}

import java.io.*;
import java.util.*;

public class Swea_1868 {

    static int[][] map;
    static boolean[][] visited;
    static int n;

    static int[] d = { 1, 0, -1 };
    static int cnt;
    static PriorityQueue<Node> pq;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        StringBuilder sb = new StringBuilder();

        final int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc += 1) {
            sb.append('#').append(tc).append(' ');

            n = Integer.parseInt(br.readLine());
            map = new int[n][n];
            visited = new boolean[n][n];
            pq = new PriorityQueue<>();
            cnt = 0;

            for (int i = 0; i < n; i += 1) {
                String s = br.readLine();
                for (int j = 0; j < n; j += 1) {
                    char c = s.charAt(j);
                    if (c == '*') {
                        map[i][j] = -1;
                        continue;
                    }

                    map[i][j] = 0;
                }
            }
            // 전체 노드를 순회하며 인접 지뢰 수를 정리
            for (int r = 0; r < n; r += 1) {
                for (int c = 0; c < n; c += 1) {
                    checkNeighbor(r, c);
                }
            }

            // 전체 노드가 순회 될 때 까지 동작
            while (!pq.isEmpty()) {
                Node node = pq.poll();

                if (visited[node.pos[0]][node.pos[1]]) {
                    continue;
                }
                cnt += 1;
                makeVisited(node);
            }

            sb.append(cnt).append('\n');
        }
        bw.write(sb.toString());
        bw.flush();
        bw.close();
    }

    // 현재 노드를 방문처리, 인접노드가 0일경우 재귀를 통한 방문처리
    static void makeVisited(Node node) {
        int r = node.pos[0];
        int c = node.pos[1];
        if (visited[r][c]) return;
        visited[r][c] = true;
        if (node.neighborCount != 0) return;

        for (int i = 0; i < 3; i += 1) {
            int nr = r + d[i];
            for (int j = 0; j < 3; j += 1) {
                if (i == 1 && j == 1) continue;
                int nc = c + d[j];

                if (0 <= nr && nr < n && 0 <= nc && nc < n && !visited[nr][nc]) {
                    makeVisited(new Node(nr, nc, map[nr][nc]));
                }
            }
        }
    }

    // 지도에 인접 지뢰 수를 표시하기 위해 탐색
    static void checkNeighbor(int r, int c) {
        if (map[r][c] == -1) return;

        int bombCount = 0;

        for (int i = 0; i < 3; i += 1) {
            int nr = r + d[i];
            for (int j = 0; j < 3; j += 1) {
                if (i == 1 && j == 1) continue;
                int nc = c + d[j];

                if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                    bombCount += map[nr][nc] == -1 ? 1 : 0;
                }
            }
        }
        map[r][c] = bombCount;
        pq.add(new Node(r, c, bombCount));
    }

    private static class Node implements Comparable<Node> {

        int neighborCount;
        int[] pos;

        public Node(int r, int c, int neighborCount) {
            this.neighborCount = neighborCount;
            pos = new int[] { r, c };
        }

        @Override
        public String toString() {
            return "{ (" + pos[0] + ", " + pos[1] + "), " + neighborCount + "}";
        }

        @Override
        public int compareTo(Node o) {
            return this.neighborCount - o.neighborCount;
        }
    }
}

/*
 지뢰 칸을 제외한 모든 칸의 숫자들이 표시되려면 최소 몇 번의 클릭을 해야되는지 구하는 문제

 현재 칸이 아직 방문하지 않은 '.'이고 주변 8칸에 지뢰가 하나도 없다면
 	클릭 횟수 +1
 	현재 칸 방문 처리
 	BFS/DFS 시작

 	주변 8칸을 확인
 		방문하지 않은 '.'이면 방문 처리

 		그 주변 칸도 주변 지뢰 개수가 0이라면
 			그 칸에서도 다시 8방향 탐색
 		지뢰 개수가 1개라도 있으면 방문 처리는 하되 더 확장하지는 않음(탐색 중단)

 * */

import java.io.*;
import java.util.*;

class Solution {
	static int N, ans;
	static char[][] map; // 지뢰 찾기 표

	static int[] dr = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] dc = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static boolean[][] visited;

	public static void main(String args[]) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		int T = Integer.parseInt(br.readLine()); // 테스트 케이스

		for (int tc = 1; tc <= T; tc++) {
			N = Integer.parseInt(br.readLine()); // 지뢰 찾기 표 크기

			// 지뢰 정보 입력
			map = new char[N][N];
			for (int r = 0; r < N; r++) {
				String line = br.readLine();
				for (int c = 0; c < N; c++) {
					map[r][c] = line.charAt(c);
				}
			}

			ans = 0; // 클릭 횟수
			visited = new boolean[N][N];
			for (int r = 0; r < N; r++) {
				for (int c = 0; c < N; c++) {
					// 아무도 방문하지 않은 지뢰 없는 칸이면서 주변에도 지뢰가 없는 칸인 경우
					if (map[r][c] == '.' && !visited[r][c] && countMine(r, c) == 0) {
						ans++;
						visited[r][c] = true;

						clickMine(r, c);
					}
				}
			}

			// 아직 방문하지 않은 '.'칸 클릭
			for (int r = 0; r < N; r++) {
				for (int c = 0; c < N; c++) {
					if (map[r][c] == '.' && !visited[r][c]) {
						ans++;
					}
				}
			}

			sb.append("#").append(tc).append(" ").append(ans).append("\n");
		}

		System.out.print(sb);
	}

	// 주변 칸에 지뢰가 몇 개 있는지 확인
	static int countMine(int x, int y) {
		int count = 0;

		for (int d = 0; d < 8; d++) {
			int nx = x + dr[d];
			int ny = y + dc[d];

			if (!isRange(nx, ny))
				continue;

			if (map[nx][ny] == '*')
				count++; // 지뢰가 있으면 개수 +1
		}

		return count;
	}

	// 0인 칸을 클릭했을 때 자동으로 열리는 영역을 BFS로 탐색
	static void clickMine(int startX, int startY) {
		Deque<int[]> dq = new ArrayDeque<>();

		dq.offerFirst(new int[] { startX, startY }); // 처음 클릭한 칸을 dq에 삽입

		while (!dq.isEmpty()) {
			int[] cur = dq.poll();
			int x = cur[0];
			int y = cur[1];

			if (countMine(x, y) > 0)
				continue; // 주변에 지뢰가 있으면 더 이상 확장 안함

			// 현재 칸이 0이면 주변 8칸이 자동으로 퍼져서 열림
			for (int d = 0; d < 8; d++) {
				int nx = x + dr[d];
				int ny = y + dc[d];

				// 배열 범위 벗어나면 제외
				if (!isRange(nx, ny))
					continue;

				// 지뢰가 있으면 제외
				if (map[nx][ny] == '*')
					continue;

				// 이미 방문한 칸이면 제외
				if (visited[nx][ny])
					continue;

				// 방문하지 않고 지뢰가 없으면 방문
				visited[nx][ny] = true;

				// 자동으로 열린 칸을 다음 탐색을 위해 dq에 삽입
				dq.offerFirst(new int[] { nx, ny });
			}
		}
	}

	static boolean isRange(int x, int y) {
		if (x >= 0 && x < N && y >= 0 && y < N) {
			return true;
		}

		return false;
	}
}

import java.io.*;
import java.util.*;

public class swea1868 {

    static int n;
    static char[][] board = new char[302][302];
    static int[][] numBoard = new int[302][302];
    static int[][] visited = new int[302][302];

    static int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    static int[] dy = {-1, 1, 0, -1, 1, -1, 1, 0};

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int t = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= t; tc++) {

            int answer = 0;
            n = Integer.parseInt(br.readLine());

            List<int[]> mines = new ArrayList<>();

            for (int i = 0; i < n; i++) {

                String s = br.readLine();

                for (int j = 0; j < n; j++) {

                    visited[i][j] = 0;
                    numBoard[i][j] = 0;
                    board[i][j] = s.charAt(j);

                    if (board[i][j] == '*') {
                        mines.add(new int[]{i, j});
                        numBoard[i][j] = -1;
                    }
                }
            }

            for (int[] mine : mines) {

                for (int dir = 0; dir < 8; dir++) {

                    int nx = mine[0] + dx[dir];
                    int ny = mine[1] + dy[dir];

                    if (nx < 0 || nx >= n || ny < 0 || ny >= n)
                        continue;

                    if (board[nx][ny] == '*')
                        continue;

                    numBoard[nx][ny]++;
                }
            }

            for (int i = 0; i < n; i++) {

                for (int j = 0; j < n; j++) {

                    if (numBoard[i][j] == 0 && visited[i][j] == 0) {

                        answer++;

                        Queue<int[]> q = new ArrayDeque<>();

                        visited[i][j] = 1;
                        q.offer(new int[]{i, j});

                        while (!q.isEmpty()) {

                            int[] cur = q.poll();

                            for (int dir = 0; dir < 8; dir++) {

                                int nx = cur[0] + dx[dir];
                                int ny = cur[1] + dy[dir];

                                if (nx < 0 || nx >= n || ny < 0 || ny >= n)
                                    continue;

                                if (visited[nx][ny] == 1)
                                    continue;

                                visited[nx][ny] = 1;

                                if (numBoard[nx][ny] == 0) {
                                    q.offer(new int[]{nx, ny});
                                }
                            }
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {

                for (int j = 0; j < n; j++) {

                    if (board[i][j] != '*' && visited[i][j] == 0) {

                        answer++;
                        visited[i][j] = 1;
                    }
                }
            }

            sb.append("#")
              .append(tc)
              .append(" ")
              .append(answer)
              .append("\n");
        }

        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class SWEA1868 {
	static final int[] dx = {0, 1, 0, -1, 1, 1, -1, -1};
	static final int[] dy = {1, 0, -1, 0, 1, -1, 1, -1};

	static int N;
	static int[][] board;
	static boolean[][] visited;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		int T = Integer.parseInt(br.readLine().trim());
		for(int t = 1; t <= T; t++) {
			N = Integer.parseInt(br.readLine().trim());
			board = new int[N][N];
			visited = new boolean[N][N];
			int result = 0;

			for(int i = 0; i < N; i++) {
				char[] line = br.readLine().trim().toCharArray();
				for(int j = 0; j < N; j++) {
					if(line[j] == '*') board[i][j] = -1;
				}
			}

			updateNum();

			// 0인 칸부터 BFS로 방문 처리
			for(int i = 0; i < N; i++) {
				for(int j = 0; j < N; j++) {
					if(!visited[i][j] && board[i][j] == 0) {
						bfs(i, j);
						result++;
					}
				}
			}

			// 남은 숫자 칸들을 방문 처리
			for(int i = 0; i < N; i++) {
				for(int j = 0; j < N; j++) {
					if(!visited[i][j] && board[i][j] > 0) {
						bfs(i, j);
						result++;
					}
				}
			}

			sb.append("#").append(t).append(" ").append(result).append("\n");
		}
		System.out.print(sb);
	}

	private static void updateNum() {
		for(int i = 0; i < N; i++) {
			for(int j = 0; j < N; j++) {
				if(board[i][j] == -1) {
					for(int k = 0; k < 8; k++) {
						int nx = i + dx[k];
						int ny = j + dy[k];

						if(!inRange(nx, ny) || board[nx][ny] == -1) continue;

						board[nx][ny]++;
					}
				}
			}
		}
	}

	private static boolean inRange(int x, int y) {
		return (x >= 0 && x < N && y >= 0 && y < N);
	}

	private static void bfs(int x, int y) {
		Queue<int[]> queue = new ArrayDeque<>();
		queue.offer(new int[] {x, y});
		visited[x][y] = true;

		while(!queue.isEmpty()) {
			int[] curr = queue.poll();

			if(board[curr[0]][curr[1]] == 0) {
				for(int i = 0; i < 8; i++) {
					int nx = curr[0] + dx[i];
					int ny = curr[1] + dy[i];

					if(!inRange(nx, ny) || visited[nx][ny] || board[nx][ny] == -1) continue;

					queue.offer(new int[] {nx, ny});
					visited[nx][ny] = true;
				}
			}
		}
	}
}

import java.util.*;
import java.io.*;

public class swea1868 {
	public static void main(String args[]) throws Exception
	{
		BufferedReader br = new BufferedReader(new InputStreamReader (System.in));
        StringBuilder sb = new StringBuilder();
        int T = Integer.parseInt(br.readLine());
        for (int tc = 1; tc <= T; tc++) {
            int N = Integer.parseInt(br.readLine());
            char[][] map = new char [N][N];
            for (int r = 0; r < N; r++) {
                String line = br.readLine();
                for (int c = 0; c < N; c++) {
                    map[r][c] = line.charAt(c);
                }
            }
            int[] dr = {0, 1, 1, 1, 0, -1, -1, -1};
            int[] dc = {1, 1, 0, -1, -1, -1, 0, 1};
            boolean[][] isZero = new boolean[N][N];
            for (int r = 0; r < N; r++) {
                for (int c = 0; c < N; c++) {
                    if (map[r][c] == '.') {
                        boolean hasBomb = false;

                        for (int d = 0; d < 8; d++) {
                            int nr = r+dr[d];
                            int nc = c+dc[d];
                            if(nr >= 0 && nr < N && nc >= 0 && nc < N && map[nr][nc] == '*') {
                                hasBomb = true;
                                break;
                            }
                        }

                        if (!hasBomb) {
                            isZero[r][c] = true;
                        }
                    }
                }
            }          

            boolean[][] visited = new boolean[N][N];
            int minClick = 0;
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (isZero[i][j] && !visited[i][j]) {
                        minClick++;
                        visited[i][j] = true;

                        Queue<int[]>queue = new ArrayDeque<>();
                        queue.offer(new int[] {i, j});

                        while(!queue.isEmpty()) {
                            int[] curr = queue.poll();
                            int r = curr[0];
                            int c = curr[1];

                            for (int d = 0; d < 8; d++) {
                                int nr = r + dr[d];
                                int nc = c + dc[d];

                                if (nr >= 0 && nr < N && nc >= 0 && nc < N && !visited[nr][nc] && map[nr][nc] != '*') {
                                    visited[nr][nc] = true;

                                    if (isZero[nr][nc]) {
                                    	queue.offer(new int[] {nr, nc});
                                    }
                                }
                            }
                        }
                    }
                }
            }
            for (int i = 0; i < N; i++) {
    			for (int j = 0; j < N; j++) {
       				if (map[i][j] != '*' && !visited[i][j]) {
            			minClick++; 
       				 }
   				 }
			}
			sb.append("#").append(tc).append(" ").append(minClick).append("\n");
        }
        System.out.print(sb.toString());
	}
}

import java.io.BufferedReader;
import java.io.IOException;
