import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.StringTokenizer;

public class SWEA1267 {

	static int N; // 작업수
	static int M; // 조건 수
	static int[] works;
	static List<Integer>[] graph;
	static int[] answer;

	public static void main(String[] args) throws IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		for(int t=0; t<10; t++) {
			StringTokenizer st = new StringTokenizer(in.readLine().trim());
			N = Integer.parseInt(st.nextToken());
			M = Integer.parseInt(st.nextToken());

			works = new int[N+1];
			graph = new List[N+1];

			for(int i=1; i<=N; i++) {
				graph[i] = new ArrayList<>();
			}
			st = new StringTokenizer(in.readLine().trim());
			for(int i=0; i<M; i++) {
				int work1 = Integer.parseInt(st.nextToken());
				int work2 = Integer.parseInt(st.nextToken());

				graph[work1].add(work2);
				works[work2]++;
			}

			Deque<Integer> dq = new ArrayDeque<>();

			answer = new int[N];
			int index = 0;

			for(int i=1; i<=N; i++) {
				if(works[i] == 0) dq.offer(i);
			}

			while(!dq.isEmpty()) {
				int work = dq.poll();

				answer[index++] = work;

				for(int i=0; i<graph[work].size(); i++) {
					works[graph[work].get(i)]--;
					if(works[graph[work].get(i)] == 0) {
						dq.offer(graph[work].get(i));
					}
				}

			}

			sb.append("#").append(t+1).append(" ");

			for(int i=0; i<N; i++) {
				sb.append(answer[i]).append(" ");
			}

			sb.append("\n");
		}
		System.out.println(sb);
	}
}

/*
작업 순서

V개의 작업과 작업들 간의 선행 관계가 주어질 때, 일을 끝낼 수 있는 작업 순서를 찾는 문제

배열로 작업 순서를 명시, 인덱스(현 작업)에 다음 작업 노드 값을 집어 넣는다.

V와 E를 입력받는다.
curTask -> nextTask 관계를 인접 리스트에 저장한다.
nextTask의 진입 차수를 증가시킨다.
진입 차수가 0인 작업을 모두 큐에 넣는다.
큐가 빌 때까지 반복한다.
	현재 작업을 꺼내 정답에 추가한다.
    현재 작업과 연결된 다음 작업들의 진입 차수를 1 감소시킨다.
    진입 차수가 0이 된 작업을 큐에 넣는다.

*/
import java.util.*;
import java.io.*;

class Solution {
	static int V, E; // V: 노드 개수, E: 간선 개수

	static ArrayList<ArrayList<Integer>> task; // 작업들간의 선행 관계 리스트
	static int[] indegree; // 진입하는 간선 개수

	public static void main(String args[]) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		for (int tc = 1; tc <= 10; tc++) {
			st = new StringTokenizer(br.readLine());

			V = Integer.parseInt(st.nextToken()); // 노드
			E = Integer.parseInt(st.nextToken()); // 간선

			task = new ArrayList<>();
			for (int i = 0; i <= V; i++) {
				task.add(new ArrayList<>());
			}

			// 두 개씩 가져와 왼쪽 값을 현 작업, 오른쪽 값을 다음 작업 지정
			// 현 작업을 인덱스로 삼아 task에 다음 작업 값을 추가
			indegree = new int[V + 1];
			st = new StringTokenizer(br.readLine());
			while (st.hasMoreTokens()) {
				int curTask = Integer.parseInt(st.nextToken());
				int nextTask = Integer.parseInt(st.nextToken());

				task.get(curTask).add(nextTask);

				// nextTask로 들어오는 간선 수 증가
				indegree[nextTask]++;
			}

			// 진입 차수가 0인 작업들을 큐에 추가
			Deque<Integer> dq = new ArrayDeque<>();
			for (int i = 1; i <= V; i++) {
				if (indegree[i] == 0) {
					dq.offer(i); // 뒤에 추가
				}
			}

			sb.append("#").append(tc).append(" ");
			while (!dq.isEmpty()) {
				int cur = dq.poll();

				// 현재 작업을 꺼내 정답에 추가
				sb.append(cur).append(" ");

				// 현재 작업과 연결된 다음 작업들의 진입 차수를 1 감소
				for (int next : task.get(cur)) {
					indegree[next]--;

					// 진입 차수가 0이 된 작업을 큐에 추가
					if (indegree[next] == 0) {
						dq.offer(next); // 뒤에 추가
					}
				}
			}

			sb.append("\n");
		}

		System.out.print(sb);
	}
}

import java.io.*;
import java.util.*;

public class swea1267 {

    static int[] indegree = new int[1001];
    static ArrayList<Integer>[] adjList = new ArrayList[1001];

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        // 인접 리스트 객체 미리 생성
        for (int i = 0; i <= 1000; i++) {
            adjList[i] = new ArrayList<>();
        }

        for (int tc = 1; tc <= 10; tc++) {

            StringTokenizer st = new StringTokenizer(br.readLine());

            int v = Integer.parseInt(st.nextToken());
            int e = Integer.parseInt(st.nextToken());

            // 초기화
            Arrays.fill(indegree, 0);

            for (int i = 1; i <= v; i++) {
                adjList[i].clear();
            }

            st = new StringTokenizer(br.readLine());

            for (int i = 0; i < e; i++) {
                int from = Integer.parseInt(st.nextToken());
                int to = Integer.parseInt(st.nextToken());

                adjList[from].add(to);
                indegree[to]++;
            }

            Deque<Integer> q = new ArrayDeque<>();

            for (int i = 1; i <= v; i++) {
                if (indegree[i] == 0) {
                    q.offer(i);
                }
            }

            ArrayList<Integer> answerList = new ArrayList<>();

            while (!q.isEmpty()) {

                int cur = q.poll();
                answerList.add(cur);

                for (int next : adjList[cur]) {

                    indegree[next]--;

                    if (indegree[next] == 0) {
                        q.offer(next);
                    }
                }
            }

            sb.append("#").append(tc).append(" ");

            for (int node : answerList) {
                sb.append(node).append(" ");
            }

            sb.append("\n");
        }

        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class SWEA2105 {
	static final int[] dx = new int[] {1, 1, -1, -1};
	static final int[] dy = new int[] {1, -1, -1, 1};

	static int[][] board;
	static int[] start;
	static int result;
	static boolean[][] visited;
	static List<Integer> cafes;

    public static void main(String[] args) throws Exception{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int T = Integer.parseInt(br.readLine().trim());
        for(int t = 1; t <= T; t++) {
        	int N = Integer.parseInt(br.readLine().trim());
        	board = new int[N][N];
        	start = new int[2];
        	visited = new boolean[N][N];
        	cafes = new LinkedList<>();
        	result = -1;

        	for(int i = 0; i < N; i++) {
        		StringTokenizer st = new StringTokenizer(br.readLine());
        		for(int j = 0; j < N; j++) {
        			board[i][j] = Integer.parseInt(st.nextToken());
        		}
        	}

            for(int i = 0; i < N - 2; i++) {
            	for(int j = 1; j < N - 1; j++) {
            		visited[i][j] = true;
            		cafes.add(board[i][j]);
            		start[0] = i;
            		start[1] = j;

            		dfs(i, j, 0, 0);

            		visited[i][j] = false;
            		cafes.clear();
            	}
            }

            sb.append("#").append(t).append(" ").append(result).append("\n");
        }
        System.out.print(sb);
    }

    private static boolean inRange(int x, int y) {
    	return (x >= 0 && x < board.length && y >= 0 && y < board.length);
    }

    private static void dfs(int x, int y, int depth, int dir) {
    	if(dir == 4) {
    		if(x == start[0] && y == start[1]) {
    			if(result < depth) result = depth;
    		}
    		return;
    	}

    	List<int[]> added = new ArrayList<>();
    	int steps = 0;

    	while(true) {
    		int nx = x + dx[dir];
    		int ny = y + dy[dir];

    		if(nx == start[0] && ny == start[1]) {
    			if(dir == 3) {
    				dfs(nx, ny, depth + steps + 1, dir + 1);
    			}
    			break;
    		}

    		if(!inRange(nx, ny)) break;
    		if(visited[nx][ny] || cafes.contains(board[nx][ny])) break;

    		x = nx;
    		y = ny;
    		steps++;

    		visited[x][y] = true;
    		cafes.add(board[x][y]);
    		added.add(new int[]{x, y});

    		dfs(x, y, depth + steps, dir + 1);
    	}

    	for(int[] p : added) {
    		visited[p[0]][p[1]] = false;
    	}
    	for(int i = 0; i < added.size(); i++) {
    		cafes.remove(cafes.size() - 1);
    	}
    }
}

import java.io.*;
import java.util.*;

public class swea2105 {

    static int[][] board = new int[22][22];
    static int n;

    static boolean[] used = new boolean[101];

    static int answer;

    static int[] dx = {-1, 1, 1, -1};
    static int[] dy = {1, 1, -1, -1};

    static int startx;
    static int starty;

    static void backtrack(int x, int y, int dir, int cnt, int zeroCnt) {

        used[board[x][y]] = true;

        if (dir == 2) {
            zeroCnt--;
        }

        int curCnt = cnt + 1;

        if (x == startx && y == starty && dir == 3) {
            answer = Math.max(answer, curCnt - 1);
            return;
        }

        int nx = x + dx[dir];
        int ny = y + dy[dir];

        if (nx < 0 || nx >= n || ny < 0 || ny >= n) {
            used[board[x][y]] = false;
            return;
        }

        if ((nx != startx || ny != starty) && used[board[nx][ny]]) {
            used[board[x][y]] = false;
            return;
        }

        if (dir <= 1) {
            int nextZeroCnt = zeroCnt + (dir == 0 ? 1 : 0);

            backtrack(nx, ny, dir, curCnt, nextZeroCnt);
            backtrack(nx, ny, dir + 1, curCnt, nextZeroCnt);
        }

        if (dir == 2) {
            if (zeroCnt > 0) {
                backtrack(nx, ny, dir, curCnt, zeroCnt);
            } else {
                backtrack(nx, ny, dir + 1, curCnt, zeroCnt);
            }
        }

        if (dir == 3) {
            backtrack(nx, ny, dir, curCnt, zeroCnt);
        }

        used[board[x][y]] = false;
    }

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {

            answer = -1;
            Arrays.fill(used, false);

            n = Integer.parseInt(br.readLine());

            for (int i = 0; i < n; i++) {
                st = new StringTokenizer(br.readLine());

                for (int j = 0; j < n; j++) {
                    board[i][j] = Integer.parseInt(st.nextToken());
                }
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    startx = i;
                    starty = j;

                    backtrack(i, j, 0, 0, 0);
                }
            }

            System.out.println("#" + tc + " " + answer);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    // 시계방향
    static int[] dx = {1, 1, -1, -1};
    static int[] dy = {1, -1, -1, 1};

    static int n;
    static int[] kind = new int[110];
    static int[][] brd = new int[25][25];
    static int[][] vis = new int[25][25];

    static int cnt;
    static int ans;
    static int sx, sy;

    static boolean oob(int x, int y) {
        return x < 0 || y < 0 || x >= n || y >= n;
    }

    static void make_rec(int x, int y, int dir, int cnt) {

        // oob면 다른 후보
        if (oob(x, y))
            return;

        // 한바퀴 돌았는지 체크
        if (dir == 3 && x == sx && y == sy) {
            ans = Math.max(ans, cnt);
            return;
        }

        // 먹은 종류면 종료
        if (kind[brd[x][y]] == 1)
            return;

        // 종류 먹음 처리
        kind[brd[x][y]] = 1;

        // 현재 방향 진행
        make_rec(x + dx[dir], y + dy[dir], dir, cnt + 1);

        // 꺾은 방향 탐색
        if (dir < 3)
            make_rec(x + dx[dir + 1], y + dy[dir + 1], dir + 1, cnt + 1);

        // 처리 해제
        kind[brd[x][y]] = 0;
    }

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int test_case;
        int T;

        T = Integer.parseInt(br.readLine());

        /*
           여러 개의 테스트 케이스가 주어지므로, 각각을 처리합니다.
        */
        for (test_case = 1; test_case <= T; ++test_case) {

            /////////////////////////////////////////////////////////////////////////////////////////////
            /*
                 이 부분에 여러분의 알고리즘 구현이 들어갑니다.
                 가능한 대각사각형을 그리면서 겹치지 않는 종류만 선택

                 백트래킹으로 풀이

                 함수 정의
                    현재 x,y 방문, cnt개수만큼 종류 체크, 방향은 dir
                    현재 방향, 꺽은 방향 탐색
                        해당 방향 만큼 진행
                        oob면 컨티뉴 => 다른 방향도 후보이기 때문
                        dir==3 이고 시작점이랑 동일시
                            사각형 형성이기에  정답 갱신
                        먹은 종류면 컨티뉴
                        종류 먹음 처리
                        다음 호출
                        처리 해제
                베이스 조건
                    탐색 가능 방향보다 더 가면, 더 이상 만들지 못함
                    한바퀴 돌고 왔으면 종료


            */

            n = Integer.parseInt(br.readLine());

            for (int i = 0; i < n; i++) {
                st = new StringTokenizer(br.readLine());

                for (int j = 0; j < n; j++) {
                    brd[i][j] = Integer.parseInt(st.nextToken());
                }
            }

            ans = 0;

            // 보드탐색
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {

                    // 현재 노드에서 사각형 그리기
                    kind[brd[i][j]] = 1;

                    sx = i;
                    sy = j;

                    make_rec(i + dx[0], j + dy[0], 0, 1);

                    kind[brd[i][j]] = 0;
                }
            }

            if (ans == 0)
                ans = -1;

            System.out.println("#" + test_case + " " + ans);

            /////////////////////////////////////////////////////////////////////////////////////////////
        }
    }
}

import java.util.*;
import java.io.*;
/*
 * 출발점부터 도착점이 가능하면 1 불가능하면 0
 * 
 * 알고리즘: BFS
 * 
 * 길: 0
 * 벽: 1
 * 출발점: 2
 * 도착점: 3
 */
public class Solution { // 우 하 좌 상
	static int[] dx = {0, 1, 0, -1};
	static int[] dy = {1, 0, -1, 0};
	static int[][] board;
	static boolean[][] vis;
	static int startX, startY;
	static int endX, endY;
	static int n, answer;
	public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        for(int tc=1; tc<=10; tc++) {
            n = Integer.parseInt(br.readLine());

            board = new int[100][100];
            vis = new boolean[100][100];

            for(int i=0; i<100; i++) {
            	String str = br.readLine();
            	for(int j=0; j<100; j++) {
            		board[i][j] = str.charAt(j) - '0';
            		if(board[i][j] == 2) {
            			startX = i;
            			startY = j;
            		}
            		else if (board[i][j] == 3) {
            			endX = i;
            			endY = j;
            		}
            	}
            }

            answer = 0;
            bfs(startX, startY);

            sb.append("#").append(tc).append(" ").append(answer).append("\n");
        }
        System.out.println(sb.toString());
	}

	private static void bfs(int x, int y) {
		Queue<int[]> q = new ArrayDeque<>();
		q.offer(new int[]{x, y});
		vis[x][y] = true;
		while(!q.isEmpty()) {
			int[] cur = q.poll();
			for(int dir=0; dir<4; dir++) {
				int nx = cur[0] + dx[dir];
				int ny = cur[1] + dy[dir];
				if(nx < 0 || nx >= 100 || ny < 0 || ny >= 100) continue;
				if(vis[nx][ny]) continue;
				if(board[nx][ny] == 1) continue; // 벽일때

				if(board[nx][ny] == 0) { // 길일때
					q.offer(new int[] {nx, ny});
					vis[nx][ny] = true;
				}

				if(board[nx][ny] == 3) {
					answer = 1;
					return;
				}
			}
		}
	}
}

import java.io.BufferedReader;
