public class SWEA_Maze2 {
	// 100x100 크기의 미로 격자 데이터를 저장할 배열
	static int[][] maze = new int[100][100];
	// 방문 여부를 기록할 배열 (-1: 방문함, 0: 방문 안 함)
	static int[][] visited = new int[100][100];

	// 상, 하, 좌, 우 이동을 위한 방향 배열 (y축 이동, x축 이동)
	public static int[] dy = { 1, -1, 0, 0 };
	public static int[] dx = { 0, 0, 1, -1 };

	public static void main(String[] args) throws IOException {
		// 빠른 입력 처리를 위한 BufferedReader 사용
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		// SWEA 미로2 문제는 항상 10개의 테스트 케이스가 주어짐
		int T = 10;

		for (int test_case = 1; test_case < T + 1; test_case++) {
			// [초기화] 새로운 테스트 케이스를 시작하기 전 방문 배열을 모두 0으로 리셋
			for (int[] visit : visited) {
				Arrays.fill(visit, 0);
			}

			// 테스트 케이스 번호가 적힌 첫 줄을 읽어서 버림 (정수 입력 처리)
			br.readLine();

			// point[0]: 출발점(2)의 {y, x} 좌표, point[1]: 도착점(3)의 {y, x} 좌표 저장용
			int[][] point = new int[2][2];

			// 100줄에 걸쳐 미로의 행 데이터를 입력받음
			for (int i = 0; i < 100; i++) {
				String str = br.readLine(); // 공백 없는 한 줄의 문자열 읽기
				for (int j = 0; j < 100; j++) {
					// 문자를 숫자로 변환 (예: '1' - '0' = 1)
					int n = str.charAt(j) - '0';
					maze[i][j] = n; // 미로 배열에 저장

					// 출발점(2) 위치 찾기
					if (n == 2) {
						point[0][0] = i; // 출발점 y좌표
						point[0][1] = j; // 출발점 x좌표
					} 
					// 도착점(3) 위치 찾기
					else if (n == 3) {
						point[1][0] = i; // 도착점 y좌표
						point[1][1] = j; // 도착점 x좌표
					}
				}
			}

			// 탐색 결과(출발점 좌표 전달)에 따라 결과 출력 (1: 도달 가능, 0: 도달 불가능)
			if (findRoot(point[0][0], point[0][1])) {
				System.out.println("#" + test_case + " 1");
			} else {
				System.out.println("#" + test_case + " 0");
			}
		}
	}

	/**
	 * BFS(너비 우선 탐색)를 이용해 출발점부터 도착점(3)까지 갈 수 있는 길이 있는지 확인하는 메서드
	 */
	public static boolean findRoot(int y, int x) {
		boolean result = false; // 도달 성공 여부를 저장할 플래그 변수

		// BFS 탐색을 위한 큐 생성 및 초기 출발점 삽입
		Queue<int[]> queue = new ArrayDeque<int[]>();
		queue.offer(new int[] { y, x });
		visited[y][x] = -1; // 출발점 방문 처리 (-1)

		// 큐가 빌 때까지 또는 목적지를 찾을 때까지 탐색 반복
		while (!queue.isEmpty() && !result) {
			int[] q = queue.poll(); // 현재 탐색할 좌표 꺼내기

			// 현재 위치에서 상, 하, 좌, 우 4방향 탐색
			for (int i = 0; i < 4; i++) {
				int ny = q[0] + dy[i]; // 다음 탐색할 y좌표
				int nx = q[1] + dx[i]; // 다음 탐색할 x좌표

				// 1. 미로 경계선(0~99)을 벗어나는지 검사
				// 2. 이미 방문한 곳(-1)인지 검사
				// 3. 미로의 벽(1)인지 검사 -> 조건에 걸리면 패스(continue)
				if (ny == 100 || ny < 0 || nx == 100 || nx < 0 || visited[ny][nx] == -1 || maze[ny][nx] == 1) {
					continue;
				}

				// 다음 좌표가 도착점(3)인 경우 탐색을 성공으로 종료
				if (maze[ny][nx] == 3) {
					result = true;
					break; // 4방향 loop 탈출 (이후 while 조건문에 의해 탐색 전체 종료)
				}

				// 갈 수 있는 길(0)인 경우 큐에 삽입하고 방문 표시
				queue.offer(new int[] { ny, nx });
				visited[ny][nx] = -1;
			}
		}
		return result; // 목적지 도달 여부 반환
	}
}

