/*
 * 1 = wall
 * 0 = path 
 * 2 = start point 
 * 3 = end point 
 * 
 * answer 
 * 		1 -> POSSIBLE 
 * 		0 -> IMPOSSIBLE 
 * */

public class swea1227 {

	static int[] dr = {-1, 1, 0, 0};
	static int[] dc = {0, 0, -1, 1}; 

	public static void main(String[] args) throws Exception {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		for (int t = 1; t <= 10; t++) {

			int answer = 0; 

			int[][] map = new int[100][100];

			int startR = 0;
			int startC = 0;

			int endR = 0;
			int endC = 0; 

			// input test case 
			int tc = Integer.parseInt(br.readLine()); 

			// input map 
			for (int i = 0; i < 100; i++) {
				String line = br.readLine();
				for (int j = 0; j < 100; j++) {
					map[i][j] = line.charAt(j) - '0';
					// store start & end x,y
					if (map[i][j] == 2) {
						startR = i;
						startC = j;
					}

					if (map[i][j] == 3) {
						endR = i;
						endC = j; 
					}
				}
			}

			// offer starting point to queue 
			Queue<int[]> q = new ArrayDeque<>(); 
			boolean[][] visited = new boolean[100][100];

			q.offer(new int[] {startR, startC});
			visited[startR][startC] = true; 

			// BFS START
			while(!q.isEmpty()) {

				int[] curr = q.poll();

				int currR = curr[0];
				int currC = curr[1];

				for (int d = 0; d < 4; d++) {

					int nr = currR + dr[d];
					int nc = currC + dc[d]; 

					// check that it is in range 
					if (nr < 0 || nr >= 100 || nc < 0 || nc >= 100) {
						continue; 
					}

					// base case 
					if (nr == endR && nc == endC) {
						answer = 1; 
						break; 
					}

					// only offer to queue if nr nc is not 1 
					if (map[nr][nc] != 1) {

						if (!visited[nr][nc]) {
							q.offer(new int[] {nr, nc}); 
							visited[nr][nc] = true; 
						}						
					}
				}

			}
			// sb
			sb.append("#").append(t).append(" ").append(answer).append("\n"); 
		}
		// print 
		System.out.print(sb);
	}
}

