public class 미로2 {

	static int startX;
	static int startY;
	static int endX;
	static int endY;

	// 우 하 좌 상
	static final int[] dr = { 0, 1, 0, -1 };
	static final int[] dc = { 1, 0, -1, 0 };

	public static void main(String[] args) throws IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		for (int testCase = 1; testCase <= 10; testCase++) {
			in.readLine();

			int[][] map = new int[100][100];

			for (int i = 0; i < 100; i++) {
				String str = in.readLine();
				for (int j = 0; j < 100; j++) {
					map[i][j] = str.charAt(j) - '0';

					if (map[i][j] == 2) {
						startX = i;
						startY = j;
					} else if (map[i][j] == 3) {
						endX = i;
						endY = j;
					}
				}
			}

			int answer = bfs(map);

			sb.append("#").append(testCase).append(" ").append(answer).append("\n");
		}
		System.out.print(sb);
	}

	// 시작점에서 도착점까지 도달 가능하면 1, 아니면 0
	static int bfs(int[][] map) {
		boolean[][] visited = new boolean[100][100];
		Queue<int[]> q = new ArrayDeque<>();

		q.offer(new int[] { startX, startY });
		visited[startX][startY] = true;

		while (!q.isEmpty()) {
			int[] cur = q.poll();
			int curX = cur[0];
			int curY = cur[1];

			if (curX == endX && curY == endY) {
				return 1;
			}

			// 4방향 탐색
			for (int d = 0; d < 4; d++) {
				int nextX = curX + dr[d];
				int nextY = curY + dc[d];

				if (!isRange(nextX, nextY)) continue;
				if (visited[nextX][nextY]) continue;
				if (map[nextX][nextY] == 1) continue;

				visited[nextX][nextY] = true;
				q.offer(new int[] { nextX, nextY });
			}
		}
		return 0;
	}

	static boolean isRange(int nr, int nc) {
		return nr >= 0 && nr < 100 && nc >= 0 && nc < 100;
	}
}

import java.util.*;
import java.io.*;

class Solution {
	static int ans; // 도달 가능 여부
	static int[][] maze; // 미로
	static boolean[][] visited; // 칸 방문 여부

	// 상 하 좌 우
	static int[] dr = { -1, 1, 0, 0 };
	static int[] dc = { 0, 0, -1, 1 };

	public static void main(String args[]) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		// 미로 정보 입력
		maze = new int[100][100];
		for (int tc = 1; tc <= 10; tc++) {
			int testCase = Integer.parseInt(br.readLine()); // 테스트 케이스 입력

			for (int r = 0; r < 100; r++) {
				String line = br.readLine();
				for (int c = 0; c < 100; c++) {
					maze[r][c] = line.charAt(c) - '0';
				}
			}

			// 시작점을 데크에 삽입
			Deque<int[]> dq = new ArrayDeque<>();
			dq.offerFirst(new int[] { 1, 1 }); // x좌표, y좌표, 미로 정보

			// 미로 진행
			ans = 0;
			visited = new boolean[100][100];
			while (!dq.isEmpty() && ans == 0) {
				int[] cur = dq.poll();
				int x = cur[0];
				int y = cur[1];

				for (int d = 0; d < 4; d++) {
					int nx = x + dr[d];
					int ny = y + dc[d];

					// 배열 범위 벗어나면 제외
					if (!isRange(nx, ny))
						continue;

					// 벽이거나 방문한 칸인 경우 제외
					if (maze[nx][ny] == 1 || visited[nx][ny])
						continue;

					// 도착지점인 경우 ans에 1 저장 후 탐색 중단
					if (maze[nx][ny] == 3) {
						ans = 1;

						break;
					}

					// 길인 경우 방문 처리 후 dq에 삽입
					visited[nx][ny] = true;

					dq.offerFirst(new int[] { nx, ny });
				}
			}

			// dq가 다 비었는데 도착지점을 찾지 못한 경우 ans에 0 저장
			if (ans == 0) {
				ans = 0;
			} else {
				ans = 1;
			}

			sb.append("#").append(testCase).append(" ").append(ans).append("\n");
		}

		System.out.print(sb);
	}

	// 배열 범위 체크
	static boolean isRange(int x, int y) {
		if (x > 0 && y > 0 && x < 99 && y < 99) { // 가장 자리는 다 벽
			return true;
		}

		return false;
	}
}

