	}

	private static int find(int x) {
		if(parent[x] == x) return x;
		return parent[x] = find(parent[x]);
	}

	private static boolean union(int a, int b) {
		a = find(a);                                       
		b = find(b);
		if(a == b) return false;     
		parent[b] = a;                                     
		return true;
	}
}

import java.io.*;
import java.util.*;

public class swea7465 {

    static int[] parent = new int[1000001];

    static int findParent(int a) {
        if (parent[a] == -1) {
            return a;
        }

        return parent[a] = findParent(parent[a]);
    }

    static boolean union(int a, int b) {
        int p = findParent(a);
        int q = findParent(b);

        if (p == q) {
            return false;
        }

        parent[q] = p;
        return true;
    }

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {

            StringTokenizer st = new StringTokenizer(br.readLine());

            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            int answer = 0;

            Arrays.fill(parent, 0, n + 1, -1);

            for (int i = 0; i < m; i++) {
                st = new StringTokenizer(br.readLine());

                int a = Integer.parseInt(st.nextToken());
                int b = Integer.parseInt(st.nextToken());

                union(a, b);
            }

            for (int i = 1; i <= n; i++) {
                if (parent[i] == -1) {
                    answer++;
                }
            }

            sb.append("#")
              .append(tc)
              .append(" ")
              .append(answer)
              .append("\n");
        }

        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class swea5648 {

    static int n;

    static int[] dx = {0, 0, -1, 1};
    static int[] dy = {1, -1, 0, 0};

    static class Atom {
        int x;
        int y;
        int dir;
        int energy;

        Atom(int x, int y, int dir, int energy) {
            this.x = x;
            this.y = y;
            this.dir = dir;
            this.energy = energy;
        }
    }

    static Atom[] aliveAtom = new Atom[1001];
    static Atom[] nextAtom = new Atom[1001];

    static int nextAtomCnt;
    static int[][] board = new int[4005][4005];

    static int answer;

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {

            answer = 0;

            n = Integer.parseInt(br.readLine());

            for (int i = 0; i < n; i++) {
                st = new StringTokenizer(br.readLine());

                int x = Integer.parseInt(st.nextToken());
                int y = Integer.parseInt(st.nextToken());
                int dir = Integer.parseInt(st.nextToken());
                int energy = Integer.parseInt(st.nextToken());

                aliveAtom[i] = new Atom(
                        x * 2,
                        y * 2,
                        dir,
                        energy
                );
            }

            for (int time = 1; time <= 4001; time++) {

                nextAtomCnt = 0;
                int localMax = 0;

                if (n <= 1)
                    break;

                // move
                for (int i = 0; i < n; i++) {
                    Atom cur = aliveAtom[i];

                    cur.x += dx[cur.dir];
                    cur.y += dy[cur.dir];
                }

                // mark
                for (int i = 0; i < n; i++) {
                    Atom cur = aliveAtom[i];

                    if (cur.x < -2000 || cur.x > 2000 ||
                        cur.y < -2000 || cur.y > 2000)
                        continue;

                    board[cur.x + 2000][cur.y + 2000]++;
                }

                // count
                for (int i = 0; i < n; i++) {
                    Atom cur = aliveAtom[i];

                    if (cur.x < -2000 || cur.x > 2000 ||
                        cur.y < -2000 || cur.y > 2000)
                        continue;

                    if (board[cur.x + 2000][cur.y + 2000] >= 2) {
                        localMax += cur.energy;
                    } else {
                        nextAtom[nextAtomCnt++] = cur;
                    }
                }

                // board clear
                for (int i = 0; i < n; i++) {
                    Atom cur = aliveAtom[i];

                    if (cur.x < -2000 || cur.x > 2000 ||
                        cur.y < -2000 || cur.y > 2000)
                        continue;

                    board[cur.x + 2000][cur.y + 2000] = 0;
                }

                // renew
                for (int i = 0; i < nextAtomCnt; i++) {
                    aliveAtom[i] = nextAtom[i];
                }

                n = nextAtomCnt;

                answer += localMax;
            }

            System.out.println("#" + tc + " " + answer);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class SWEA5648 {

	static int N;
	static Atom[] atoms;
	static boolean[] crashed;
	static PriorityQueue<Crash> pq = new PriorityQueue<>();
	static int answer;
	static int[] crashTime;


	static class Crash implements Comparable<Crash>{
		int a;
		int b;
		int time;

		Crash(int a, int b, int time){
			this.a = a;
			this.b = b;
			this.time = time;
		}

		@Override
		public int compareTo(Crash o) {
			// TODO Auto-generated method stub
			return this.time - o.time;
		}
	}

	static class Atom{
		int x;
		int y;
		int dir;
		int power;

		Atom(int x, int y, int dir, int power){
			this.x = x;
			this.y = y;
			this.dir = dir;
			this.power = power;
		}
	}

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb =new StringBuilder();

		int T = Integer.parseInt(in.readLine().trim());
		for(int t=0; t<T; t++) {
			N = Integer.parseInt(in.readLine().trim());
			atoms = new Atom[N+1];
			crashed = new boolean[N+1];
			crashTime = new int[N+1];

			StringTokenizer st;
			for(int i=1; i<=N; i++) {
				st = new StringTokenizer(in.readLine().trim());
				atoms[i] = new Atom(
							Integer.parseInt(st.nextToken()) * 2, // x좌표
							Integer.parseInt(st.nextToken()) * 2, // y좌표
							Integer.parseInt(st.nextToken()), // 이동방향
							Integer.parseInt(st.nextToken()) // 보유에너지
						);
			}
			answer = 0;
			dfs(1);

			while(!pq.isEmpty()) {
				Crash crash = pq.poll();

				if(!crashed[crash.a] && !crashed[crash.b]) {
					crashed[crash.a] = true;
					crashed[crash.b] = true;

					crashTime[crash.a] = crash.time;
					crashTime[crash.b] = crash.time;

					answer += (atoms[crash.a].power + atoms[crash.b].power);
				} else if(crashed[crash.a] || crashed[crash.b]) {
					if(crashed[crash.a]) {
						if(crashTime[crash.a] == crash.time && !crashed[crash.b]) {
							crashed[crash.b] = true;
							crashTime[crash.b] = crash.time;
							answer += atoms[crash.b].power;
						}
					} else if(crashed[crash.b]) {
						if(crashTime[crash.b] == crash.time && !crashed[crash.a]) {
							crashed[crash.a] = true;
							crashTime[crash.a] = crash.time;
							answer += atoms[crash.a].power;
						}
					}
				}
			}

			sb.append("#").append(t+1).append(" ").append(answer).append("\n");
		}
		System.out.println(sb);
	}

	static public void dfs(int depth) {
		if(depth == N) {
			return;
		}
		Atom atom1 = atoms[depth];
		for(int i=depth+1; i<=N; i++) {
			Atom atom2 = atoms[i];

			if(atom1.dir == atom2.dir) continue;

			if(atom1.dir == 0) {
				if(atom1.y > atom2.y) continue;
			} else if(atom1.dir == 1) {
				if(atom1.y < atom2.y) continue;
			} else if(atom1.dir == 2) {
				if(atom1.x < atom2.x) continue;
			} else if(atom1.dir == 3) {
				if(atom1.x > atom2.x) continue;
			}

			if(atom1.dir == 0 || atom1.dir == 1) {
				if(atom1.x > atom2.x) {
					if(atom2.dir != 3)continue;
				} else if (atom1.x < atom2.x) {
					if(atom2.dir != 2)continue;
				} else {
					if(atom1.dir == 0) {
						if(atom2.dir != 1) continue;
					} else {
						if(atom2.dir != 0) continue;
					}
				}

				int[] crashLoc = {atom1.x, atom2.y};
				if(atom1.x == atom2.x) crashLoc = new int[]{atom1.x, (atom1.y+atom2.y)/2};
				int time1 = getDistance(atom1, crashLoc);
				int time2 = getDistance(atom2, crashLoc);

				if(time1 == time2) {
					pq.offer(new Crash(depth, i, time1));
				}

			} else {
				if(atom1.y > atom2.y) {
					if(atom2.dir != 0) continue;
				} else if (atom1.y < atom2.y) {
					if(atom2.dir != 1) continue;
				} else {
					if(atom1.dir == 2) {
						if(atom2.dir != 3) continue;
					} else {
						if(atom2.dir != 2) continue;
					}
				}

				int[] crashLoc = {atom2.x, atom1.y};
				if(atom1.y == atom2.y) crashLoc = new int[]{(atom1.x+atom2.x)/2, atom1.y};
				int time1 = getDistance(atom1, crashLoc);
				int time2 = getDistance(atom2, crashLoc);

				if(time1 == time2) {
					pq.offer(new Crash(depth, i, time1));
				}
			}
		}
		dfs(depth+1);
	}

	static public int getDistance(Atom atom, int[] crashLoc) {
		return (Math.abs(crashLoc[0] - atom.x) + Math.abs(crashLoc[1] - atom.y));
	}

}

import java.io.*;
import java.util.*;

public class SWEA_5648 {

	// 빠른 입출력을 위한 BufferedReader 및 StringBuilder 선언
	static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
	static StringTokenizer st;

	static int T, N;

	// 원자의 이동 방향 설정 (문제 조건에 맞춤)
	// 0: 상 (y증가), 1: 하 (y감소), 2: 좌 (x감소), 3: 우 (x증가)
	static int[] dx = { 0, 0, -1, 1 };
	static int[] dy = { 1, -1, 0, 0 };

	static int[][] atom; // 원자들의 정보를 담을 2차원 배열
	static int[][] board; // 원자가 이동한 위치에 에너지를 누적할 2차원 배열

	public static void main(String[] args) throws IOException {

		// 테스트 케이스 개수 입력
		T = Integer.parseInt(br.readLine());

		// [주의] 4001x4001 크기의 거대한 맵을 '단 한 번만' 할당하여 메모리 낭비를 방지함
		// 좌표 범위가 -1000 ~ 1000 이므로 총 길이는 2000, 0.5초 이동 처리를 위해 2배를 하여 4000이 됨 (0 ~ 4000)
		board = new int[4001][4001];

		for (int tc = 1; tc <= T; tc++) {

			// 원자의 개수 입력
			N = Integer.parseInt(br.readLine());

			// 원자의 정보 배열 생성: 각 원자는 [x, y, 방향, 에너지, 소멸여부]의 5가지 정보를 가짐
			atom = new int[N][5];

			for (int i = 0; i < N; i++) {
				st = new StringTokenizer(br.readLine());

				// 입력 좌표계가 음수이므로 +1000을 더해 양수로 변환하고,
				// 0.5초 단위 충돌(정면 충돌 등)을 정수 좌표에서 잡기 위해 좌표 전체를 2배로 확대함
				int x = (Integer.parseInt(st.nextToken()) + 1000) * 2;
				int y = (Integer.parseInt(st.nextToken()) + 1000) * 2;
				int dir = Integer.parseInt(st.nextToken());
				int energy = Integer.parseInt(st.nextToken());

				// atom[i][4] = 0은 현재 원자가 활성화(살아있음) 상태임을 의미 (1이면 소멸)
				atom[i] = new int[] { x, y, dir, energy, 0 };
			}

			// 시뮬레이션을 실행하여 이번 테스트 케이스의 총 소멸 에너지를 구함
			int answer = simulate();
			System.out.println("#" + tc + " " + answer);

		}
	}

	public static int simulate() {
		int answer = 0;
		int leftAtom = N;

		// 원자가 맵 안에서 움직일 수 있는 최대 시간은 4000스텝(0.5초 * 4000 = 2000초)입니다.
		// 무한 루프를 방지하고 시간 초과를 막기 위해 최대 4000번만 반복합니다.
		for (int step = 0; step <= 4000; step++) {
			if (leftAtom <= 0)
				break;

			// 이번 스텝에서 원자들이 새로 밟은 좌표들을 기록해둘 리스트 (다음 스텝 전 청소용)
			List<int[]> movedPoints = new ArrayList<>();

			// --- 1단계: 모든 살아있는 원자 이동 및 해당 좌표 카운트 증가 ---
			for (int i = 0; i < N; i++) {
				if (atom[i][4] == 1) {
					continue;
				}

				int nx = atom[i][0] + dx[atom[i][2]];
				int ny = atom[i][1] + dy[atom[i][2]];

				// 경계를 벗어나면 소멸 처리
				if (nx < 0 || nx > 4000 || ny < 0 || ny > 4000) {
					atom[i][4] = 1;
					leftAtom--;
					continue;
				}

				// 좌표 갱신
				atom[i][0] = nx;
				atom[i][1] = ny;

				// 처음 방문하는 빈 좌표라면 청소 리스트에 등록
				if (board[nx][ny] == 0) {
					movedPoints.add(new int[] { nx, ny });
				}

				// board[nx][ny]에 에너지를 누적하는 대신, '원자의 개수'를 1씩 증가시킵니다.
				board[nx][ny] += 1;
			}

			// --- 2단계: 이동이 끝난 후 원자 개수를 기반으로 충돌 확인 및 정산 ---
			for (int i = 0; i < N; i++) {
				if (atom[i][4] == 1) {
					continue;
				}

				int x = atom[i][0];
				int y = atom[i][1];

				// 해당 좌표에 모인 원자의 개수가 2개 이상이라면 '충돌 발생'
				if (board[x][y] >= 2) {
					answer += atom[i][3]; // 이 원자가 가진 고유 에너지를 정답에 정직하게 누적
					atom[i][4] = 1; // 원자 소멸 처리
					leftAtom--;
				}
				// [주의] board[x][y] == 1 (혼자 온 경우)라면 아무 작업도 하지 않고 살려둡니다.
			}

			// --- 3단계: 다음 스텝을 위해 원자들이 지나간 자리를 확실히 0으로 청소 ---
			// 이 처리를 해주어야 다음 스텝 및 다음 테스트케이스에서 board 배열이 오염되지 않습니다.
			for (int[] point : movedPoints) {
				board[point[0]][point[1]] = 0;
			}
		}

		return answer; // 누적된 총 소멸 에너지 반환
	}
}

import java.io.*;
import java.util.*;

public class SWEA5648 {
    static final int[] dx = {0, 0, -1, 1};
    static final int[] dy = {1, -1, 0, 0};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine().trim());
        for (int t = 1; t <= T; t++) {
            int N = Integer.parseInt(br.readLine().trim());
            Atom[] atoms = new Atom[N];

            for (int i = 0; i < N; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                int x = (Integer.parseInt(st.nextToken()) + 1000) * 2;
                int y = (Integer.parseInt(st.nextToken()) + 1000) * 2;
                int dir = Integer.parseInt(st.nextToken());
                int k = Integer.parseInt(st.nextToken());
                atoms[i] = new Atom(x, y, dir, k);
            }

            int answer = 0;
            int aliveCount = N;

            Map<Integer, Integer> counts = new HashMap<>();

            while (aliveCount > 0) {
                counts.clear(); 
                int inRangeCount = 0;

                for (int i = 0; i < N; i++) {
                    if (!atoms[i].alive) continue;

                    atoms[i].x += dx[atoms[i].dir];
                    atoms[i].y += dy[atoms[i].dir];

                    if (!inRange(atoms[i].x, atoms[i].y)) {
                        atoms[i].alive = false;
                        aliveCount--;
                    } else {
                        int key = atoms[i].x * 10000 + atoms[i].y;
                        counts.put(key, counts.getOrDefault(key, 0) + 1);
                    }
                }

                for (int i = 0; i < N; i++) {
                    if (!atoms[i].alive) continue;

                    int key = atoms[i].x * 10000 + atoms[i].y;
                    if (counts.get(key) >= 2) { 
                        answer += atoms[i].k;
                        atoms[i].alive = false;
                        aliveCount--;
                    }
                }
            }
            sb.append('#').append(t).append(' ').append(answer).append('\n');
        }
        System.out.print(sb);
        br.close();
    }

    private static boolean inRange(int x, int y) {
        return 0 <= x && x <= 4000 && 0 <= y && y <= 4000;
    }

    public static class Atom {
        int x, y, dir, k;
        boolean alive = true;

        public Atom(int x, int y, int dir, int k) {
            this.x = x;
            this.y = y;
            this.dir = dir;
            this.k = k;
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.HashMap;
