import java.util.StringTokenizer;

public class Atomic_simulation {
	/*
	 * 원자시뮬레이션
	 * 
	 * 목표 : 원자들이 소멸되면서 방출하는 에너지의 총합
	 * 
	 * - 원자들이 충돌후 소멸하면서 에너지가 방출된다 - 1.5초후에 A,B원자가 충돌하면 에너지가 발생하는 케이스가 있다.
	 * 
	 * 구현 - 거리공식으로 각각의 방향으로 1씩 뺴줘서 이동시킨다음 최종했을때 겹치는곳있는지 체크 원자들의 에너지는 1이상 k이하 원자들의 수
	 * N은 1000개 이하
	 * 
	 * 원자들의 좌표를 저장 원자들의 위치 상대를 저장할 배열? 만들기 모든 이동 완료시 위치가 동일한곳이 있는지 체크하기 에너지 폭발
	 * 
	 * 범위는 0~2001
	 */

	static int N;

	static int[] dr = { 1, -1, 0, 0 };
	static int[] dc = { 0, 0, -1, 1 };
	static int[][] atoms;
	static int[][] pos;

	public static void main(String[] args) throws Exception {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		StringTokenizer st;

		// 원자들의 수를 배열에 저장
		// 배열돌면서 해당방향으로 이동시켜줌
		// 위치 일치하는지 판별
		// 결과저장

		int T = Integer.parseInt(br.readLine());

		for (int tc = 0; tc < T; tc++) {
			N = Integer.parseInt(br.readLine());// 원자개수
			atoms = new int[N][5]; // 원자들의 위치 저장 배열
			pos = new int[N][N]; // 이동하는 배열 (안쓸수도)
			int totalEnergy = 0;
			// x위치, y위치, 이동방향, 에너지

			for (int i = 0; i < atoms.length; i++) {
				st = new StringTokenizer(br.readLine());
				int x = Integer.parseInt(st.nextToken());
				int y = Integer.parseInt(st.nextToken());
				int dir = Integer.parseInt(st.nextToken());
				int e = Integer.parseInt(st.nextToken());

				// 5번째는 살아있는지 여부, 살아있으면 1 터졌으면 -1
				atoms[i] = new int[] { y * 2, x * 2, dir, e, 1 };

			}

			// 시뮬레이션 atoms돌면서 위치 이동시키기
			// oob 일시 영원히 가는거니까 판별 x
			// 판별 위치가 같으면 터지게 포문 두개
			int time = 0;

			Map<Integer, Integer> positionCount = new HashMap<>(); // 특정 좌표에 원자가 몇개있는지 저장
			int restAtom = N;
			while (time <= 4001) {
				positionCount.clear();
				if (restAtom <= 1)
					break;
				// 이동 페이즈 : 원소개수만큼 이동하고 MAP에 좌표를 저장
				for (int i = 0; i < N; i++) {
					int[] curr = atoms[i];
					int r = atoms[i][0], c = atoms[i][1], dir = atoms[i][2], alive = atoms[i][4];

					if (alive < 0)
						continue;

					int nr = r + dr[dir];
					int nc = c + dc[dir];

					// 좌표 저장
					curr[0] = nr;
					curr[1] = nc;
					if (oob(nr, nc)) {
						curr[4] = -1;
						restAtom -= 1;
						continue;
					}
					// 좌표키만들기,
					int key = nr * 10000 + nc;
					positionCount.put(key, positionCount.getOrDefault(key, 0) + 1);

				}

				// 판결 페이즈
				// 이동한 좌표가 2이상일시 터트린다.
				// 맵에 있는 키들을 도는데, 이 때, 크면 배열을 돌면서 찾고 누적하기
				// 키값이동

				for (int[] curr : atoms) {
					int key = curr[0] * 10000 + curr[1];
					int e = curr[3];
					int alive = curr[4];
					if (alive < 0)
						continue;
					if (positionCount.get(key) >= 2) {
						totalEnergy += e;
						curr[4] = -1; // 죽임
						restAtom -= 1;
					}
				}

				time += 1;
			}

			sb.append("#").append(tc + 1).append(" ").append(totalEnergy).append("\n");

		}
		System.out.println(sb);
	}

	static boolean oob(int r, int c) {
		if (r < -2000 || c < -2000 || r > 2000 || c > 2000)
			return true;
		return false;
	}

}

import java.io.*;
import java.util.*;

public class SWEA2115 {
    static int N, M, C;
    static int[][] board;
    static int[][] profits;
    static boolean[] visited;
    static int sum;
    static int[] nums;

    public static void main(String[] args) throws Exception{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int T = Integer.parseInt(br.readLine());
        for(int t = 1; t <= T; t++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            N = Integer.parseInt(st.nextToken());
            M = Integer.parseInt(st.nextToken());
            C = Integer.parseInt(st.nextToken());
            board = new int[N][N];
            profits = new int[N][N];

            int result = 0;

            for(int i = 0; i < N; i++) {
                st = new StringTokenizer(br.readLine());
                for(int j = 0; j < N; j++) {
                    board[i][j] = Integer.parseInt(st.nextToken());
                }
            }

            for(int i = 0; i < N; i++) {
                for(int j = 0; j < N; j++) {
                    int end = (j + M - 1 >= N) ? N - 1 : j + M - 1;
                    getProfit(i, j, end);
                }
            }

            // (i, j) : 일꾼A의 시작 좌표
            // (x, y) : 일꾼B의 시작 좌표
            for(int i = 0; i < N; i++) {
                for(int j = 0; j < N; j++) {
                    for(int x = i; x < N; x++) {
                        for(int y = 0; y < N; y++) {
                            // A와 B의 채취자리가 겹치면 스킵
                            if(i == x && j <= y && j + M >= y) continue;
                            if(i == x && y <= j && y + M >= j) continue;

                            int curr = profits[i][j] + profits[x][y];
                            if(result < curr) {
                                result = curr;
                            }
                        }
                    }
                }
            }

            sb.append("#").append(t).append(" ").append(result).append("\n");
        }
        System.out.print(sb);
    }

    // 가장 큰 값부터 꺼내니까 엣지 케이스 발생(테케2번)
    // start ~ end까지의 최대 Profit을 찾아서 저장
    private static void getProfit(int row, int start, int end) {
        nums = new int[M];
        visited = new boolean[M];
        sum = 0;

        for(int i = start; i <= end; i++) {
            nums[i - start] = board[row][i];
        }

        dfs(C, 0);

        profits[row][start] = sum;
    }

    // 현재 채취 칸에서 가능한 모든 경우의 수 탐색
    private static void dfs(int currC, int currSum) {
        if(currSum > sum) sum = currSum;

        for(int i = 0; i < M; i++) {
            if(visited[i] || currC < nums[i]) continue;

            visited[i] = true;
            currC -= nums[i];
            currSum += nums[i] * nums[i];

            dfs(currC, currSum);

            visited[i] = false;
            currC += nums[i];
            currSum -= nums[i] * nums[i];
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class SWEA_6782 {

	public static void main(String[] args) throws IOException {
		// 빠른 입력을 위해 BufferedReader 사용
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st;

		// 테스트 케이스의 개수 T를 입력받음
		int T = Integer.parseInt(br.readLine());

		// 1번부터 T번 테스트 케이스까지 반복 실행
		for (int test_case = 1; test_case < T + 1; test_case++) {

			// N의 최대 크기가 10^12이므로 int가 아닌 long 타입으로 입력받음
			long N = Long.parseLong(br.readLine());

			// 결과를 요구하는 형식(#테스트케이스 정답)에 맞춰 출력
			System.out.println("#" + test_case + " " + dfs(N, 0));
		}
	}

	/**
	 * N을 2로 만들기 위한 최소 연산 횟수를 구하는 메서드
	 * @param num   : 현재 숫자 (최대 10^12이므로 long)
	 * @param count : 현재까지 누적된 연산 횟수
	 * @return 최종 연산 횟수
	 */
	public static int dfs(long num, int count) {

		// 숫자가 최종 목적지인 2가 될 때까지 반복
		while (num != 2) {

			// 1. 현재 숫자(num)가 '정수의 제곱'인지 확인 (예: 4, 9, 16 등)
			// Math.sqrt(num) % 1 == 0 이면 소수점 아래가 없으므로 완벽한 제곱수임
			if (Math.sqrt(num) % 1 == 0) {
				num = (long) Math.sqrt(num); // 제곱근을 취함 (예: 9 -> 3)
				count++;                     // 연산 횟수 1회 증가
			} 
			// 2. 현재 숫자가 제곱수가 아니라면 (예: 7)
			else {
				// 현재 숫자보다 큰 제곱수 중 '가장 가까운 제곱수'를 구함
				// 예: num이 7일 때, Math.sqrt(7)은 2.xx 이고 +1을 하면 3이 됨. 3의 제곱인 9를 구함.
				long high = ((long) Math.sqrt(num) + 1) * ((long) Math.sqrt(num) + 1);

				// 현재 숫자에서 다음 제곱수까지 1씩 더하는 연산을 한 번에 점프 처리
				// 예: 7에서 9가 되려면 1을 두 번 더해야 하므로 (9 - 7) = 2회를 count에 한 번에 더함
				count += (high - num);

				// 숫자를 다음 제곱수로 바로 변경 (1씩 누적 더하기를 시뮬레이션)
				num = high;
			}
		}

		// 2에 도달했을 때의 총 연산 횟수를 반환
		return count;
	}
}

import java.io.*;

public class SWEA6782 {
	static long N;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();
		int T = Integer.parseInt(br.readLine().trim());
		for (int t = 1; t <= T; t++) {
			sb.append("#").append(t).append(" ");
			N = Long.parseLong(br.readLine().trim());

			long result = 0;
			while (N != 2) {
				long root = (long) Math.sqrt(N);

				// 소수 자리 오차 보정
				while (root * root > N) root--;
				while ((root + 1) * (root + 1) <= N) root++;

				if (root * root == N) {
					// N이 완전제곱수면 루트로 이동하기. 연산 1회
					N = root;
					result++;
				} else {
					// 완전제곱수가 아니면 다음 완전제곱수까지 점프. 연산 점프한 횟수만큼
					long jumpNum = (root + 1) * (root + 1);
					result += (jumpNum - N);
					N = jumpNum;
				}
			}

			sb.append(result).append("\n");
		}
		System.out.print(sb);
	}
}

import java.io.*;
