public class Solution {
	// 처음에는 다음 완전제곱수를 찾는 방법을 떠올리지 못함
	// floor(sqrt(N)) + 1의 제곱이 다음 완전제곱수라는 점을 학습
	// 현주의 조작은 다음의 케이스가 있다.
	// N 을 N+1로 만들기
	// 루트 N이 정수라면 N을 루트N으로 바꿈
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb = new StringBuilder();

		int T = Integer.parseInt(br.readLine());

		for (int tc = 1; tc <= T; tc++) {
			sb.append("#").append(tc).append(" ");
			long N = Long.parseLong(br.readLine()); // int 형은 2*10^9 까지임
			long control = 0;
			if (N == 2) {
				sb.append(control).append("\n");
				continue;
			}
			long sqrtN;

			// N = 5
			// sqrtN = 2.xx
			// nextSqrt = 3 ;
			// doubleNS = 9
			// N = 9
			// sqrtN = 3
			while (N != 2) {

				sqrtN = (long)Math.sqrt(N);// 3


				long nextSqrt;

				//완전제곱수인가?
				if ((sqrtN * sqrtN) == N ) {
					N = sqrtN;
					control++;
					continue;
				} else { //아닐경우 가까운 제곱근 찾기
					nextSqrt = sqrtN +1; //
					long NS = nextSqrt * nextSqrt;
					control += NS- N;
					N = NS;
				}


			}


			sb.append(control).append("\n");
		}
		System.out.println(sb);
	}
}
